  let user_ok = validate_username("user_123")
  println("  Username: " + (user_ok ? "PASS" : "FAIL"))

  let pwd_ok = validate_password("MyPass123")
  println("  Password: " + (pwd_ok ? "PASS" : "FAIL"))

  let cc_ok = validate_credit_card("1234-5678-9012-3456")
