/*
 * Advanced Commander Tests
 * - 버퍼 오버플로우 테스트
 * - 메모리 누수 테스트
 * - 에러 처리 테스트
 */

#include "../src/kcommander.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

void test_buffer_overflow_protection(void) {
    printf("Test: Buffer Overflow Protection\n");

    kcommander_t *cmd = kcommander_new();
    assert(cmd != NULL);

    // 매우 긴 명령어 이름 테스트
    char long_name[512];
    memset(long_name, 'a', 511);
    long_name[511] = '\0';

    bool result = kcommander_add_command(cmd, long_name, "test");
    // 버퍼 크기: 256 (sizeof(name))
    // strncpy는 버퍼를 초과하지 않도록 처리
    assert(result == true);  // 추가는 성공하지만 잘림

    kcommander_free(cmd);
    printf("  ✅ 버퍼 오버플로우 방어 성공\n\n");
}

void test_null_pointer_handling(void) {
    printf("Test: NULL Pointer Handling\n");

    kcommander_t *cmd = kcommander_new();
    assert(cmd != NULL);

    // NULL 커맨드 추가
    bool result1 = kcommander_add_command(cmd, NULL, "desc");
    assert(result1 == false);

    // NULL 설명
    bool result2 = kcommander_add_command(cmd, "test", NULL);
    assert(result2 == true);  // 설명은 NULL 가능

    // NULL 파싱
    int argc = 1;
    char *argv[] = {"prog", NULL};
    bool result3 = kcommander_parse(cmd, argc, (char**)argv);
    assert(result3 == true);

    // NULL 옵션 조회
    const char *opt = kcommander_get_option(cmd, NULL);
    assert(opt == NULL);

    kcommander_free(cmd);
    printf("  ✅ NULL 포인터 처리 안전\n\n");
}

void test_memory_allocation_failure(void) {
    printf("Test: Large Command Count\n");

    kcommander_t *cmd = kcommander_new();
    assert(cmd != NULL);

    // 100개 명령어 추가 (capacity doubling 테스트)
    for (int i = 0; i < 100; i++) {
        char name[64];
        snprintf(name, sizeof(name), "cmd%d", i);
        bool result = kcommander_add_command(cmd, name, "description");
        assert(result == true);
    }

    assert(cmd->command_count == 100);
    assert(cmd->command_capacity >= 100);

    kcommander_free(cmd);
    printf("  ✅ 대량 명령어 처리 성공 (capacity: %d)\n\n",
           cmd->command_capacity);
}

void test_option_parsing_edge_cases(void) {
    printf("Test: Option Parsing Edge Cases\n");

    kcommander_t *cmd = kcommander_new();
    kcommander_add_command(cmd, "build", "Build");
    kcommander_add_option(cmd, "build", "output", 'o', "output", false, false, "dist");

    // 테스트 케이스
    char *argv1[] = {"prog", "build", "-o", "mydir"};
    kcommander_parse(cmd, 4, argv1);
    const char *out1 = kcommander_get_option(cmd, "output");
    assert(out1 != NULL && strcmp(out1, "mydir") == 0);
    printf("  ✅ 짧은 옵션 파싱 성공\n");

    // 긴 옵션
    char *argv2[] = {"prog", "build", "--output", "otherdir"};
    kcommander_parse(cmd, 4, argv2);
    const char *out2 = kcommander_get_option(cmd, "output");
    assert(out2 != NULL && strcmp(out2, "otherdir") == 0);
    printf("  ✅ 긴 옵션 파싱 성공\n");

    // 옵션 없음
    char *argv3[] = {"prog", "build"};
    kcommander_parse(cmd, 2, argv3);
    const char *out3 = kcommander_get_option(cmd, "output");
    assert(out3 == NULL);  // 제공되지 않음
    printf("  ✅ 옵션 부재 처리 성공\n");

    kcommander_free(cmd);
    printf("\n");
}

void test_flag_combinations(void) {
    printf("Test: Flag Combinations\n");

    kcommander_t *cmd = kcommander_new();
    kcommander_add_command(cmd, "test", "Test");
    kcommander_add_option(cmd, "test", "verbose", 'v', "verbose", true, false, NULL);
    kcommander_add_option(cmd, "test", "debug", 'd', "debug", true, false, NULL);

    // -v -d 조합
    char *argv[] = {"prog", "test", "-v", "-d"};
    kcommander_parse(cmd, 4, argv);

    bool v = kcommander_has_flag(cmd, "verbose");
    bool d = kcommander_has_flag(cmd, "debug");

    assert(v == true);
    assert(d == true);
    printf("  ✅ 플래그 조합 처리 성공\n\n");

    kcommander_free(cmd);
}

int main(void) {
    printf("\n════════════════════════════════════════════\n");
    printf("    Commander-C Advanced Tests\n");
    printf("════════════════════════════════════════════\n\n");

    test_buffer_overflow_protection();
    test_null_pointer_handling();
    test_memory_allocation_failure();
    test_option_parsing_edge_cases();
    test_flag_combinations();

    printf("════════════════════════════════════════════\n");
    printf("✅ All Commander tests passed!\n");
    printf("════════════════════════════════════════════\n\n");

    return 0;
}

