    // Remove hyphens
    char no_hyphens[33];
    int j = 0;
    for (int i = 0; i < 36; i++) {
        if (original_str[i] != '-') {
            no_hyphens[j++] = original_str[i];
        }
    }
    no_hyphens[32] = '\0';

