    test_uuid_comparison();
    test_nil_uuid();
    test_uuid_copy();
    test_uuid_v3();
    test_uuid_v5();
    test_uuid_namespaces();
    test_uuid_base64();
    test_uuid_base32();
    test_convenience_functions();
