#ifndef EXPRESS_H
#define EXPRESS_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_ROUTES 100
#define MAX_MIDDLEWARE 50
#define BUFFER_SIZE 8192

// HTTP Methods
typedef enum {
    HTTP_GET,
    HTTP_POST,
    HTTP_PUT,
    HTTP_DELETE,
    HTTP_PATCH,
    HTTP_OPTIONS,
    HTTP_HEAD
} http_method_t;

// Request structure
typedef struct {
    http_method_t method;
    char path[256];
    char query[512];
    char body[BUFFER_SIZE];
    char headers[50][256];
    int header_count;
    int client_fd;
} request_t;

// Response structure
typedef struct {
    int status_code;
    char headers[50][256];
    int header_count;
    char body[BUFFER_SIZE];
    int body_length;
    int sent;
} response_t;

// Route handler function pointer
typedef void (*route_handler_t)(request_t *req, response_t *res);

// Middleware function pointer
typedef int (*middleware_t)(request_t *req, response_t *res);

// Route structure
typedef struct {
    http_method_t method;
    char path[256];
    route_handler_t handler;
} route_t;

// Express app structure
typedef struct {
    route_t routes[MAX_ROUTES];
    int route_count;
    middleware_t middleware[MAX_MIDDLEWARE];
    int middleware_count;
    int port;
    int server_fd;
} express_app_t;

// Core functions
express_app_t* express_create();
void express_listen(express_app_t *app, int port);
void express_get(express_app_t *app, const char *path, route_handler_t handler);
void express_post(express_app_t *app, const char *path, route_handler_t handler);
void express_put(express_app_t *app, const char *path, route_handler_t handler);
void express_delete(express_app_t *app, const char *path, route_handler_t handler);
void express_use(express_app_t *app, middleware_t middleware);
void express_free(express_app_t *app);

// Response helpers
void res_status(response_t *res, int code);
void res_send(response_t *res, const char *body);
void res_json(response_t *res, const char *json);
void res_set_header(response_t *res, const char *key, const char *value);

// Request helpers
const char* req_get_header(request_t *req, const char *key);
const char* req_query_get(request_t *req, const char *key);

#endif

