/*
 * Kim Async (kasync.h)
 *
 * 비동기 제어 라이브러리 (콜백 기반)
 * - series: 순차 실행
 * - parallel: 병렬 실행
 * - waterfall: 데이터 흐름 제어
 * - queue: 작업 큐
 *
 * JavaScript의 async.js를 Pure C로 구현
 */

#ifndef KASYNC_H
#define KASYNC_H

#include <stdbool.h>
#include <stdint.h>

/* ============================================
   콜백 함수 타입
   ============================================ */

typedef void (*kasync_callback_fn)(void *err, void *result);
typedef void (*kasync_task_fn)(kasync_callback_fn callback);
typedef void (*kasync_iterator_fn)(void *item, kasync_callback_fn callback);
typedef void (*kasync_final_fn)(void *err);

/* ============================================
   에러 구조체
   ============================================ */

typedef struct {
    int code;
    char message[256];
} kasync_error_t;

/* ============================================
   작업 구조체
   ============================================ */

typedef struct kasync_task {
    kasync_task_fn fn;
    void *context;
    void *result;
    kasync_error_t *error;
    struct kasync_task *next;
} kasync_task_t;

/* ============================================
   큐 구조체
   ============================================ */

typedef struct {
    kasync_task_t *head;
    kasync_task_t *tail;
    int count;
    int max_size;
    int concurrent;
    int running;
} kasync_queue_t;

/* ============================================
   에러 함수
   ============================================ */

/**
 * 새로운 에러 생성
 */
kasync_error_t* kasync_error_new(int code, const char *message);

/**
 * 에러 해제
 */
void kasync_error_free(kasync_error_t *err);

/* ============================================
   시리즈 (순차 실행)
   ============================================ */

/**
 * 작업 배열을 순차적으로 실행
 * tasks: 작업 함수 배열
 * count: 작업 수
 * final: 모든 작업 완료 후 호출될 콜백
 */
void kasync_series(kasync_task_fn *tasks, int count, kasync_final_fn final);

/* ============================================
   패러렐 (병렬 실행)
   ============================================ */

/**
 * 작업 배열을 병렬로 실행
 * tasks: 작업 함수 배열
 * count: 작업 수
 * limit: 동시 실행 제한 (0 = 무제한)
 * final: 모든 작업 완료 후 호출될 콜백
 */
void kasync_parallel(kasync_task_fn *tasks, int count, int limit, kasync_final_fn final);

/* ============================================
   워터폴 (데이터 흐름 제어)
   ============================================ */

/**
 * 데이터를 각 작업으로 전달하며 순차 실행
 */
void kasync_waterfall(void *initial_data, kasync_iterator_fn *tasks, int count, kasync_final_fn final);

/* ============================================
   맵 (아이템 변환)
   ============================================ */

/**
 * 배열의 각 요소에 함수를 적용하여 새 배열 생성
 */
void kasync_map(void **items, int count, kasync_iterator_fn fn, kasync_final_fn final);

/**
 * 병렬로 맵 실행
 */
void kasync_map_limit(void **items, int count, int limit, kasync_iterator_fn fn, kasync_final_fn final);

/* ============================================
   필터 (조건 필터링)
   ============================================ */

/**
 * 배열에서 조건을 만족하는 요소만 추출
 */
void kasync_filter(void **items, int count, kasync_iterator_fn fn, kasync_final_fn final);

/* ============================================
   리듀스 (집계)
   ============================================ */

/**
 * 배열을 단일 값으로 축약
 */
typedef void (*kasync_reduce_fn)(void *accumulator, void *item, kasync_callback_fn callback);

void kasync_reduce(void **items, int count, void *initial, kasync_reduce_fn fn, kasync_final_fn final);

/* ============================================
   큐 (작업 큐)
   ============================================ */

/**
 * 새로운 큐 생성
 */
kasync_queue_t* kasync_queue_new(int max_size, int concurrent);

/**
 * 큐에 작업 추가
 */
void kasync_queue_push(kasync_queue_t *queue, kasync_task_fn fn);

/**
 * 큐 처리 시작
 */
void kasync_queue_process(kasync_queue_t *queue, kasync_final_fn final);

/**
 * 큐 크기 반환
 */
int kasync_queue_size(kasync_queue_t *queue);

/**
 * 큐 해제
 */
void kasync_queue_free(kasync_queue_t *queue);

/* ============================================
   유틸리티
   ============================================ */

/**
 * 콜백 생성 (간편 함수)
 */
typedef struct {
    void *result;
    kasync_error_t *error;
    bool done;
} kasync_result_t;

/**
 * 결과 대기 (간단한 동기식 래퍼)
 */
void kasync_wait(kasync_result_t *result);

#endif // KASYNC_H

