typedef struct {
    void **items;
    int count;
    int capacity;
    void (*free_fn)(void *);  // 각 항목 해제 함수
} klodash_array_t;

/* ============================================
   객체 (key-value) 구조체
   ============================================ */

typedef struct {
    char *key;
    void *value;
} klodash_pair_t;

typedef struct {
    klodash_pair_t *pairs;
    int count;
    int capacity;
} klodash_object_t;

/* ============================================
   콜백 함수 타입
   ============================================ */

typedef void (*klodash_each_fn)(void *item, int index);
