void* klodash_array_pop(klodash_array_t *arr);

/**
 * 배열 첫 항목 제거 및 반환
 */
void* klodash_array_shift(klodash_array_t *arr);

/**
 * 배열 첫 항목 추가
 */
void klodash_array_unshift(klodash_array_t *arr, void *item);

/**
 * 배열 특정 인덱스 항목 조회
 */
void* klodash_array_get(klodash_array_t *arr, int index);

/**
 * 배열 특정 인덱스 항목 설정
 */
void klodash_array_set(klodash_array_t *arr, int index, void *item);

/**
 * 배열 길이
 */

 */
int klodash_array_length(klodash_array_t *arr);

/**
 * 각 항목에 대해 함수 실행
 */
void klodash_array_each(klodash_array_t *arr, klodash_each_fn fn);

/**
 * 배열 필터링
 */
klodash_array_t* klodash_array_filter(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 항목 찾기
 */
void* klodash_array_find(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 항목 인덱스 찾기
 */
int klodash_array_find_index(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 포함 여부 (포인터 비교)
 */
bool klodash_array_includes(klodash_array_t *arr, void *item);

/**
 * 배열 역순
 */
void klodash_array_reverse(klodash_array_t *arr);

/**
 * 배열 자르기 (slice)
 */
klodash_array_t* klodash_array_slice(klodash_array_t *arr, int start, int end);

/**
 * 배열 정렬 (비교 함수 제공)
 */
void klodash_array_sort(klodash_array_t *arr, int (*compare_fn)(const void *, const void *));

/**
 * 배열 병합 (새 배열)
 */
klodash_array_t* klodash_array_concat(klodash_array_t *arr1, klodash_array_t *arr2);

