/**
 * Kim-Range-Parser (krange.h)
 * Sovereign HTTP Range Header Parser in Pure C
 *
 * HTTP Range request parser for partial content (HTTP 206),
 * multipart ranges, and conditional requests (If-Range).
 *
 * Features:
 * - Range header parsing (bytes=0-1023)
 * - Multiple ranges (bytes=0-499,1000-1499)
 * - Suffix ranges (bytes=-500)
 * - Open-ended ranges (bytes=9500-)
 * - Content-Range generation
 * - If-Range validation (ETag/Last-Modified)
 * - Multipart/byteranges support
 * - Zero external dependencies (libc only)
 *
 * Philosophy: Stability > Creativity > 0% External Dependencies
 *
 * @author Kim AI Empire
 * @version 1.0.0
 * @date 2026-01-19
 */

#ifndef KRANGE_H
#define KRANGE_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

/* ==================== Configuration ==================== */

#define KRANGE_VERSION "1.0.0"
#define KRANGE_MAX_RANGES 16

/* ==================== Types ==================== */

/**
 * Range type
 */
typedef enum {
    KRANGE_NORMAL,      // 0-1023 (start-end)
    KRANGE_SUFFIX,      // -500 (last N bytes)
    KRANGE_OPEN,        // 9500- (from start to end)
    KRANGE_INVALID      // Invalid range
} krange_type_t;

/**
 * Single range
 */
typedef struct {
    krange_type_t type;    // Range type
    int64_t start;         // Start byte (inclusive)
    int64_t end;           // End byte (inclusive)
} krange_t;

/**
 * Range list (parsed result)
 */
typedef struct {
    krange_t ranges[KRANGE_MAX_RANGES];  // Range array
    int count;             // Number of ranges
    const char *unit;      // Unit (e.g., "bytes")
} krange_list_t;

/**
 * Satisfied range (after validation)
 */
typedef struct {
    int64_t start;         // Start byte
    int64_t end;           // End byte (inclusive)
    int64_t length;        // Content length (end - start + 1)
    int64_t total;         // Total file size
    bool valid;            // Range is satisfiable
} krange_result_t;

/**
 * If-Range condition
 */
typedef struct {
    const char *etag;      // ETag (NULL if not present)
    time_t modified;       // Last-Modified (0 if not present)
} krange_condition_t;

/* ==================== Core API ==================== */

/**
 * Parse Range header
 * @param range_header Range header value (e.g., "bytes=0-1023")
 * @param list Range list (output)
 * @return 0 on success, -1 on error
 */
int krange_parse(const char *range_header, krange_list_t *list);

/**
 * Satisfy range (validate against file size)
 * @param range Single range
 * @param total_size Total file size
 * @param result Satisfied range (output)
 * @return 0 on success, -1 on error
 */
int krange_satisfy(const krange_t *range, int64_t total_size,
                   krange_result_t *result);

/**
 * Satisfy all ranges
 * @param list Range list
 * @param total_size Total file size
 * @param results Satisfied ranges (output, must be KRANGE_MAX_RANGES)
 * @param count Number of satisfied ranges (output)
 * @return 0 on success, -1 on error
 */
int krange_satisfy_all(const krange_list_t *list, int64_t total_size,
                       krange_result_t *results, int *count);

/**
 * Check if ranges are satisfiable
 * @param list Range list
 * @param total_size Total file size
 * @return true if satisfiable, false otherwise
 */
bool krange_is_satisfiable(const krange_list_t *list, int64_t total_size);

/**
 * Generate Content-Range header (single range)
 * @param result Satisfied range
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_content_range(const krange_result_t *result, char *output,
                         size_t size);

/**
 * Check If-Range condition (ETag)
 * @param if_range If-Range header value (ETag)
 * @param current_etag Current ETag
 * @return true if condition met, false otherwise
 */
bool krange_check_if_range_etag(const char *if_range,
                                const char *current_etag);

/**
 * Check If-Range condition (Last-Modified)
 * @param if_range If-Range header value (date)
 * @param current_mtime Current modification time
 * @return true if condition met, false otherwise
 */
bool krange_check_if_range_date(const char *if_range, time_t current_mtime);

/* ==================== Multipart Support ==================== */

/**
 * Generate multipart boundary
 * @param boundary Output buffer (min 64 bytes)
 * @return 0 on success, -1 on error
 */
int krange_generate_boundary(char *boundary);

/**
 * Format multipart header
 * @param result Satisfied range
 * @param content_type Content-Type
 * @param boundary Multipart boundary
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_multipart_header(const krange_result_t *result,
                            const char *content_type,
                            const char *boundary,
                            char *output, size_t size);

/**
 * Format multipart trailer
 * @param boundary Multipart boundary
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_multipart_trailer(const char *boundary, char *output, size_t size);

/* ==================== Utilities ==================== */

/**
 * Normalize range (convert to absolute offsets)
 * @param range Range to normalize
 * @param total_size Total file size
 * @return Normalized range
 */
krange_t krange_normalize(const krange_t *range, int64_t total_size);

/**
 * Check if range overlaps
 * @param r1 First range
 * @param r2 Second range
 * @return true if overlaps, false otherwise
 */
bool krange_overlaps(const krange_result_t *r1, const krange_result_t *r2);

/**
 * Merge overlapping ranges
 * @param results Range results
 * @param count Number of ranges (input/output)
 * @return 0 on success, -1 on error
 */
int krange_merge(krange_result_t *results, int *count);

/**
 * Calculate total bytes from multiple ranges
 * @param results Range results
 * @param count Number of ranges
 * @return Total bytes
 */
int64_t krange_total_bytes(const krange_result_t *results, int count);

#endif /* KRANGE_H */

/*
 * Kim Moment (kmoment.h)
 *
 * 날짜/시간 처리 라이브러리
 * - 타임스탬프 생성 및 파싱
 * - 포맷 변환
 * - 시간 계산 (add, subtract, diff)
 * - 상대 시간 표현 (fromNow, toNow)
 *
 * JavaScript의 moment.js를 Pure C로 구현
 */

#ifndef KMOMENT_H
#define KMOMENT_H

#include <time.h>
#include <stdbool.h>

/* ============================================
   날짜/시간 구조체
   ============================================ */

typedef struct {
    time_t timestamp;
    struct tm tm;
} kmoment_t;

/* ============================================
   포맷 상수
   ============================================ */

#define KMOMENT_ISO_8601      "YYYY-MM-DDTHH:mm:ssZ"
