#define KMOMENT_TIME_SHORT    "HH:mm:ss"
#define KMOMENT_DATETIME      "YYYY-MM-DD HH:mm:ss"

/* ============================================
   생성 함수
   ============================================ */

/**
 * 현재 시간으로 moment 생성
 */
kmoment_t* kmoment_now(void);

/**
 * 타임스탬프로부터 moment 생성
 */
kmoment_t* kmoment_unix(time_t timestamp);

/**
 * 연, 월, 일, 시, 분, 초로부터 moment 생성
 */
kmoment_t* kmoment_date(int year, int month, int day, int hour, int minute, int second);

/**
 * moment 복사
 */
kmoment_t* kmoment_clone(kmoment_t *m);

/**
 * moment 해제
 */
void kmoment_free(kmoment_t *m);

/* ============================================
   파싱 함수
