            break;
        }

        char key[64], value[256];
        snprintf(key, sizeof(key), "cookie_%d", i);
        snprintf(value, sizeof(value), "value_%d_%d", i, i * 2);

        kcookie_jar_set(jar, key, value, NULL);
        const char *retrieved = kcookie_jar_get(jar, key);

        if (retrieved == NULL) {
            ASSERT(false, "Cookie retrieval failed");
            kcookie_jar_free(jar);
            break;
        }

        kcookie_jar_free(jar);
