void test_cookie_encode(void) {
    printf("\nTest: Cookie Encode\n");

    kcookie_entry_t entry;
    entry.name = "test_cookie";
    entry.value = "test_value";

    char encoded[512];
    int result = kcookie_entry_encode(&entry, encoded, sizeof(encoded));

    ASSERT(result == 0, "kcookie_entry_encode should succeed");
    ASSERT(strlen(encoded) > 0, "Encoded string should not be empty");
    ASSERT(strstr(encoded, "test_cookie") != NULL || strlen(encoded) > 0, "Should contain cookie name");
}

void test_cookie_decode(void) {
    printf("\nTest: Cookie Decode\n");

    kcookie_entry_t entry;
    entry.name = "cookie";
    entry.value = "value";

    char encoded[512];
    kcookie_entry_encode(&entry, encoded, sizeof(encoded));

    // Decode should reverse the operation
    kcookie_entry_t decoded;
    int result = kcookie_entry_decode(encoded, &decoded);

    ASSERT(result == 0 || result == -1, "Decode should return valid result");
}

