        int result = provider->sign("test_value", "secret_key", signature, sizeof(signature));

        ASSERT(result == 0 || result > 0, "Signing should succeed");
        ASSERT(strlen(signature) > 0, "Signature should not be empty");
    } else {
        ASSERT(true, "Sign function may not be available in stub");
    }
}

void test_sign_cookie_value(void) {
