    fnv_provider.algorithm = KCOOKIE_HASH_FNV1A;

    // FNV-1a produces 16-character signature
    ASSERT(fnv_provider.algorithm == KCOOKIE_HASH_FNV1A, "FNV1A algorithm set");
}

void test_hmac_sha256_signature_length(void) {
    printf("\nTest: HMAC-SHA256 Signature Length\n");

    kcookie_crypto_provider_t sha_provider;
    sha_provider.algorithm = KCOOKIE_HASH_HMAC_SHA256;

    // HMAC-SHA256 produces 64-character signature
    ASSERT(sha_provider.algorithm == KCOOKIE_HASH_HMAC_SHA256, "HMAC-SHA256 set");
}

/* ==================== Edge Cases ==================== */

void test_sign_empty_value(void) {
