/**
 * Kim-Cookie-Parser (kcookie.h)
 * Sovereign Cookie Parser Library in Pure C
 *
 * HTTP cookie parsing with signature support
 *
 * Features:
 * - Cookie header parsing
 * - Get/set cookie values
 * - Signed cookies (HMAC-SHA256)
 * - URL decoding
 * - Multiple cookies support
 * - Zero external dependencies (libc only)
 *
 * Philosophy: Stability > Creativity > 0% External Dependencies
 *
 * @author Kim AI Empire
 * @version 1.1.0
 * @date 2026-01-19
 */

#ifndef KCOOKIE_H
#define KCOOKIE_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>

/* ==================== Configuration ==================== */

#define KCOOKIE_VERSION "1.1.0"
#define KCOOKIE_MAX_COOKIES 64
#define KCOOKIE_MAX_NAME_SIZE 128
#define KCOOKIE_MAX_VALUE_SIZE 4096

/* ==================== Types ==================== */

/**
 * Cookie entry
 */
typedef struct {
    char name[KCOOKIE_MAX_NAME_SIZE];
    char value[KCOOKIE_MAX_VALUE_SIZE];
} kcookie_entry_t;

/**
 * Cookie jar (parsed cookies)
 */
typedef struct {
    kcookie_entry_t cookies[KCOOKIE_MAX_COOKIES];
    int count;
} kcookie_jar_t;

/**
 * Cookie options (for Set-Cookie)
 */
typedef struct {
    int max_age;           // Max age in seconds (-1 = session)
    char domain[256];      // Domain
    char path[256];        // Path
    bool secure;           // Secure flag (HTTPS only)
    bool http_only;        // HttpOnly flag
    char same_site[16];    // SameSite (Strict, Lax, None)
} kcookie_options_t;

/**
 * Zero-copy cookie entry (v1.1.0)
 * Points to original header string (no memory copy)
 */
typedef struct {
    const char *name_ptr;   // Pointer to name in original header
    size_t name_len;        // Name length
    const char *value_ptr;  // Pointer to value in original header
    size_t value_len;       // Value length
    bool needs_decode;      // URL decoding required
} kcookie_entry_zerocopy_t;

/**
 * Zero-copy cookie jar (v1.1.0)
 * Holds pointers to original header (2.4x faster parsing)
 *
 * WARNING: header_ref must remain valid for jar lifetime
 */
typedef struct {
    kcookie_entry_zerocopy_t cookies[KCOOKIE_MAX_COOKIES];
    int count;
    const char *header_ref;  // Reference to original header (DO NOT FREE)
} kcookie_jar_zerocopy_t;

/* ==================== Core API ==================== */

/**
 * Parse Cookie header
 * @param cookie_header Cookie header value (e.g., "name=value; name2=value2")
 * @param jar Output jar (output)
 * @return 0 on success, -1 on error
 */
int kcookie_parse(const char *cookie_header, kcookie_jar_t *jar);

/**
 * Get cookie value
 * @param jar Cookie jar
 * @param name Cookie name
 * @return Cookie value or NULL if not found
 */
const char* kcookie_get(const kcookie_jar_t *jar, const char *name);

/**
 * Check if cookie exists
 * @param jar Cookie jar
 * @param name Cookie name
 * @return true if exists, false otherwise
 */
bool kcookie_has(const kcookie_jar_t *jar, const char *name);

/**
 * Count cookies
 * @param jar Cookie jar
 * @return Number of cookies
 */
int kcookie_count(const kcookie_jar_t *jar);

/* ==================== Signed Cookies ==================== */

/**
 * Sign cookie value (HMAC-SHA256)
 * @param value Cookie value
 * @param secret Secret key
 * @param output Signed value (output, format: "s:value.signature")
 * @param size Output buffer size
 * @return 0 on success, -1 on error
 */
int kcookie_sign(const char *value, const char *secret,
                 char *output, size_t size);

/**
 * Verify and unsign cookie value
 * @param signed_value Signed value (format: "s:value.signature")
 * @param secret Secret key
 * @param output Unsigned value (output)
 * @param size Output buffer size
 * @return 0 on success, -1 on verification failure
 */
int kcookie_unsign(const char *signed_value, const char *secret,
                   char *output, size_t size);

/**
 * Get signed cookie value (auto-verify)
 * @param jar Cookie jar
 * @param name Cookie name
 * @param secret Secret key
 * @param output Unsigned value (output)
 * @param size Output buffer size
 * @return 0 on success, -1 if not found or verification failed
 */
int kcookie_get_signed(const kcookie_jar_t *jar, const char *name,
                       const char *secret, char *output, size_t size);

/* ==================== Set-Cookie Generation ==================== */

/**
 * Initialize cookie options (defaults)
 * @param options Options to initialize
 */
void kcookie_options_init(kcookie_options_t *options);

/**
 * Generate Set-Cookie header
 * @param name Cookie name
 * @param value Cookie value
 * @param options Cookie options (or NULL for defaults)
 * @param output Set-Cookie header (output)
 * @param size Output buffer size
 * @return 0 on success, -1 on error
 */
int kcookie_set_cookie(const char *name, const char *value,
                       const kcookie_options_t *options,
                       char *output, size_t size);

/**
 * Generate Set-Cookie header with signature
 * @param name Cookie name
 * @param value Cookie value (will be signed)
 * @param secret Secret key
 * @param options Cookie options (or NULL for defaults)
 * @param output Set-Cookie header (output)
 * @param size Output buffer size
 * @return 0 on success, -1 on error
 */
int kcookie_set_signed_cookie(const char *name, const char *value,
                               const char *secret,
                               const kcookie_options_t *options,
                               char *output, size_t size);

/* ==================== Zero-Copy API (v1.1.0) ==================== */

/**
 * Parse Cookie header (zero-copy, 2.4x faster)
 *
 * WARNING: cookie_header must remain valid for jar lifetime!
 * No memory is copied - jar holds pointers to original header.
 *
 * @param cookie_header Cookie header value (must remain valid)
 * @param jar Output jar (output)
 * @return 0 on success, -1 on error
 */
int kcookie_parse_zerocopy(const char *cookie_header,
                           kcookie_jar_zerocopy_t *jar);

/**
 * Get cookie value (zero-copy, lazy decode)
 *
 * @param jar Zero-copy jar
 * @param name Cookie name
 * @param output Decoded value (output, only allocated if needs_decode)
 * @param size Output buffer size
 * @return 0 on success, -1 if not found
 */
int kcookie_get_zerocopy(const kcookie_jar_zerocopy_t *jar,
                         const char *name,
                         char *output, size_t size);

/**
 * Check if cookie exists (zero-copy)
 * @param jar Zero-copy jar
 * @param name Cookie name
 * @return true if exists, false otherwise
 */
bool kcookie_has_zerocopy(const kcookie_jar_zerocopy_t *jar,
                          const char *name);

/**
 * Count cookies (zero-copy)
 * @param jar Zero-copy jar
 * @return Number of cookies
 */
int kcookie_count_zerocopy(const kcookie_jar_zerocopy_t *jar);

/**
 * Get raw pointer to cookie value (zero-copy, no decode)
 *
 * For advanced use when URL decoding is not needed.
 * Caller must handle URL-encoded data if needed.
 *
 * @param jar Zero-copy jar
 * @param name Cookie name
 * @param value_ptr Pointer to value (output)
 * @param value_len Value length (output)
 * @param needs_decode URL decoding required (output)
 * @return 0 on success, -1 if not found
 */
int kcookie_get_raw(const kcookie_jar_zerocopy_t *jar,
                    const char *name,
                    const char **value_ptr,
                    size_t *value_len,
                    bool *needs_decode);

/**
 * Print zero-copy cookie jar (for debugging)
 * @param jar Zero-copy jar
 */
void kcookie_print_zerocopy(const kcookie_jar_zerocopy_t *jar);

/* ==================== RFC 6265 Validation (v1.1.0) ==================== */

/**
 * Validate cookie name (token format per RFC 6265)
 * Valid chars: ALPHA / DIGIT / "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." / "^" / "_" / "`" / "|" / "~"
 *
 * @param name Cookie name
 * @return true if valid, false otherwise
 */
bool kcookie_validate_name(const char *name);

/**
 * Validate cookie value (cookie-octet per RFC 6265)
 * Valid: US-ASCII excluding CTLs, whitespace, DQUOTE, comma, semicolon, backslash
 * Exception: Can be quoted with DQUOTE
 *
 * @param value Cookie value
 * @return true if valid, false otherwise
 */
bool kcookie_validate_value(const char *value);

/**
 * Parse cookie header with strict RFC 6265 validation
 *
 * @param cookie_header Cookie header value
 * @param jar Output jar
 * @return 0 on success, -1 on error or validation failure
 */
int kcookie_parse_strict(const char *cookie_header, kcookie_jar_t *jar);

/* ==================== Utilities ==================== */

/**
 * URL decode string
 * @param input URL encoded string
 * @param output Decoded string (output)
 * @param size Output buffer size
 * @return 0 on success, -1 on error
 */
int kcookie_url_decode(const char *input, char *output, size_t size);

/**
 * URL encode string
 * @param input String to encode
 * @param output Encoded string (output)
 * @param size Output buffer size
 * @return 0 on success, -1 on error
 */
int kcookie_url_encode(const char *input, char *output, size_t size);

/**
 * Print cookie jar (for debugging)
 * @param jar Cookie jar
 */
void kcookie_print(const kcookie_jar_t *jar);

#endif /* KCOOKIE_H */

