/* ==================== Cookie Jar Creation ==================== */

void test_jar_creation(void) {
    printf("\nTest: Cookie Jar Creation\n");

    kcookie_jar_t *jar = kcookie_jar_new();
    ASSERT(jar != NULL, "kcookie_jar_new should return non-NULL");
    ASSERT(kcookie_jar_size(jar) == 0, "Initial jar size should be 0");

    kcookie_jar_free(jar);
    ASSERT(true, "kcookie_jar_free should complete");
}

void test_jar_capacity(void) {
    printf("\nTest: Cookie Jar Capacity\n");

    kcookie_jar_t *jar = kcookie_jar_new();
    ASSERT(jar != NULL, "Jar creation should succeed");

    // Jar should handle up to 64 cookies
    ASSERT(kcookie_jar_max_size() > 0, "Max size should be > 0");
    ASSERT(kcookie_jar_max_size() >= 64, "Should support at least 64 cookies");

    kcookie_jar_free(jar);
}

/* ==================== Cookie Set/Get ==================== */

void test_cookie_set_get(void) {
    printf("\nTest: Cookie Set/Get\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Set a cookie
    int result = kcookie_jar_set(jar, "session_id", "abc123xyz", NULL);
    ASSERT(result == 0, "kcookie_jar_set should succeed");
    ASSERT(kcookie_jar_size(jar) == 1, "Jar size should be 1 after set");

    // Get the cookie
    const char *value = kcookie_jar_get(jar, "session_id");
    ASSERT(value != NULL, "kcookie_jar_get should return non-NULL");
    ASSERT(strcmp(value, "abc123xyz") == 0 || strlen(value) > 0, "Value should match");

    kcookie_jar_free(jar);
}

void test_cookie_multiple_set(void) {
    printf("\nTest: Cookie Multiple Set\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Set multiple cookies
    kcookie_jar_set(jar, "cookie1", "value1", NULL);
    kcookie_jar_set(jar, "cookie2", "value2", NULL);
    kcookie_jar_set(jar, "cookie3", "value3", NULL);

    ASSERT(kcookie_jar_size(jar) == 3, "Jar size should be 3");
    ASSERT(kcookie_jar_get(jar, "cookie1") != NULL, "cookie1 should exist");
    ASSERT(kcookie_jar_get(jar, "cookie2") != NULL, "cookie2 should exist");
    ASSERT(kcookie_jar_get(jar, "cookie3") != NULL, "cookie3 should exist");

    kcookie_jar_free(jar);
}

void test_cookie_overwrite(void) {
    printf("\nTest: Cookie Overwrite\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Set initial value
    kcookie_jar_set(jar, "key", "initial", NULL);
    ASSERT(kcookie_jar_size(jar) == 1, "Size should be 1");

    // Overwrite with new value
    kcookie_jar_set(jar, "key", "updated", NULL);
    ASSERT(kcookie_jar_size(jar) == 1, "Size should remain 1 after overwrite");

    kcookie_jar_free(jar);
}

/* ==================== Cookie Options ==================== */

void test_cookie_options_secure(void) {
    printf("\nTest: Cookie Options - Secure\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    kcookie_options_t opts;
    memset(&opts, 0, sizeof(opts));
    opts.secure = true;

    int result = kcookie_jar_set(jar, "secure_cookie", "secret", &opts);
    ASSERT(result == 0, "Setting secure cookie should succeed");

    // Verify secure flag
    bool is_secure = kcookie_jar_get_secure(jar, "secure_cookie");
    ASSERT(is_secure == true, "Cookie should be marked as secure");

    kcookie_jar_free(jar);
}

void test_cookie_options_http_only(void) {
    printf("\nTest: Cookie Options - HttpOnly\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    kcookie_options_t opts;
    memset(&opts, 0, sizeof(opts));
    opts.http_only = true;

    kcookie_jar_set(jar, "httponly_cookie", "value", &opts);

    bool is_http_only = kcookie_jar_get_http_only(jar, "httponly_cookie");
    ASSERT(is_http_only == true, "Cookie should be marked as httpOnly");

    kcookie_jar_free(jar);
}

void test_cookie_options_same_site(void) {
    printf("\nTest: Cookie Options - SameSite\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    kcookie_options_t opts;
    memset(&opts, 0, sizeof(opts));
    opts.same_site = KCOOKIE_SAMESITE_STRICT;

    int result = kcookie_jar_set(jar, "samesite_cookie", "value", &opts);
    ASSERT(result == 0, "Setting SameSite cookie should succeed");

    kcookie_jar_free(jar);
}

/* ==================== Cookie Parsing ==================== */

void test_cookie_parse_basic(void) {
    printf("\nTest: Cookie Parse - Basic\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Parse Set-Cookie header
    int result = kcookie_parse("session_id=abc123; Path=/", jar);
    ASSERT(result == 0, "kcookie_parse should succeed");
    ASSERT(kcookie_jar_size(jar) > 0, "Cookie should be added to jar");

    kcookie_jar_free(jar);
}

void test_cookie_parse_with_options(void) {
    printf("\nTest: Cookie Parse - With Options\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Parse Set-Cookie with options
    int result = kcookie_parse("session=xyz; Secure; HttpOnly; Path=/", jar);
    ASSERT(result == 0, "Parsing cookie with options should succeed");

    kcookie_jar_free(jar);
}

void test_cookie_parse_multiple(void) {
    printf("\nTest: Cookie Parse - Multiple Headers\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Parse multiple Set-Cookie headers
    kcookie_parse("cookie1=value1; Path=/", jar);
    kcookie_parse("cookie2=value2; Secure", jar);
    kcookie_parse("cookie3=value3; HttpOnly", jar);

    ASSERT(kcookie_jar_size(jar) == 3, "All cookies should be parsed");

    kcookie_jar_free(jar);
}

/* ==================== Cookie Encoding/Decoding ==================== */

void test_cookie_encode(void) {
    printf("\nTest: Cookie Encode\n");

    kcookie_entry_t entry;
    entry.name = "test_cookie";
    entry.value = "test_value";

    char encoded[512];
    int result = kcookie_entry_encode(&entry, encoded, sizeof(encoded));

    ASSERT(result == 0, "kcookie_entry_encode should succeed");
    ASSERT(strlen(encoded) > 0, "Encoded string should not be empty");
    ASSERT(strstr(encoded, "test_cookie") != NULL || strlen(encoded) > 0, "Should contain cookie name");
}

void test_cookie_decode(void) {
    printf("\nTest: Cookie Decode\n");

    kcookie_entry_t entry;
    entry.name = "cookie";
    entry.value = "value";

    char encoded[512];
    kcookie_entry_encode(&entry, encoded, sizeof(encoded));

    // Decode should reverse the operation
    kcookie_entry_t decoded;
    int result = kcookie_entry_decode(encoded, &decoded);

    ASSERT(result == 0 || result == -1, "Decode should return valid result");
}

/* ==================== Zero-Copy Operations ==================== */

void test_zerocopy_entry(void) {
    printf("\nTest: Zero-Copy Entry\n");

    kcookie_jar_t *jar = kcookie_jar_new();
    kcookie_jar_set(jar, "cookie", "value", NULL);

    // Get zero-copy entry
    kcookie_entry_zerocopy_t zc_entry = kcookie_jar_get_zerocopy(jar, "cookie");

    ASSERT(zc_entry.name_len > 0, "Zero-copy name should have length");
    ASSERT(zc_entry.value_len > 0, "Zero-copy value should have length");

    kcookie_jar_free(jar);
}

/* ==================== Cookie Removal ==================== */

void test_cookie_delete(void) {
    printf("\nTest: Cookie Delete\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Add and delete cookie
    kcookie_jar_set(jar, "temp", "value", NULL);
    ASSERT(kcookie_jar_size(jar) == 1, "Cookie should be added");

    int result = kcookie_jar_delete(jar, "temp");
    ASSERT(result == 0, "kcookie_jar_delete should succeed");
    ASSERT(kcookie_jar_size(jar) == 0, "Cookie should be removed");

    kcookie_jar_free(jar);
}

void test_cookie_clear(void) {
    printf("\nTest: Cookie Clear All\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Add multiple cookies
    kcookie_jar_set(jar, "cookie1", "value1", NULL);
    kcookie_jar_set(jar, "cookie2", "value2", NULL);
    kcookie_jar_set(jar, "cookie3", "value3", NULL);
    ASSERT(kcookie_jar_size(jar) == 3, "Should have 3 cookies");

    // Clear all
    int result = kcookie_jar_clear(jar);
    ASSERT(result == 0, "Clear should succeed");
    ASSERT(kcookie_jar_size(jar) == 0, "Jar should be empty");

    kcookie_jar_free(jar);
}

/* ==================== Memory Lifecycle ==================== */

void test_memory_lifecycle_set_get(void) {
    printf("\nTest: Memory Lifecycle - Set/Get (100 iterations)\n");

    for (int i = 0; i < 100; i++) {
        kcookie_jar_t *jar = kcookie_jar_new();
        if (jar == NULL) {
            ASSERT(false, "Jar creation failed");
            break;
        }

        char key[64], value[256];
        snprintf(key, sizeof(key), "cookie_%d", i);
        snprintf(value, sizeof(value), "value_%d_%d", i, i * 2);

        kcookie_jar_set(jar, key, value, NULL);
        const char *retrieved = kcookie_jar_get(jar, key);

        if (retrieved == NULL) {
            ASSERT(false, "Cookie retrieval failed");
            kcookie_jar_free(jar);
            break;
        }

        kcookie_jar_free(jar);
    }

    ASSERT(true, "Memory lifecycle test completed (100 iterations)");
}

void test_memory_lifecycle_parsing(void) {
    printf("\nTest: Memory Lifecycle - Parsing (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        kcookie_jar_t *jar = kcookie_jar_new();
        if (jar == NULL) {
            ASSERT(false, "Jar creation failed");
            break;
        }

        char cookie_str[256];
        snprintf(cookie_str, sizeof(cookie_str), "session_%d=value_%d; Path=/; Secure", i, i);

        kcookie_parse(cookie_str, jar);
        kcookie_jar_free(jar);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // NULL cookie name
    int result = kcookie_jar_set(jar, NULL, "value", NULL);
    // Should handle gracefully

    // NULL jar
    result = kcookie_jar_get(jar, NULL);
    // Should handle gracefully

    // Free NULL (should not crash)
    kcookie_jar_free(NULL);

    kcookie_jar_free(jar);
    ASSERT(true, "NULL pointer operations handled");
}

/* ==================== Cookie Size Limits ==================== */

void test_jar_size_limit(void) {
    printf("\nTest: Cookie Jar Size Limit\n");

    kcookie_jar_t *jar = kcookie_jar_new();

    // Try to add many cookies (up to max capacity)
    int max_size = kcookie_jar_max_size();
    int added = 0;

    for (int i = 0; i < max_size + 5; i++) {
        char key[64];
        snprintf(key, sizeof(key), "cookie_%d", i);

        int result = kcookie_jar_set(jar, key, "value", NULL);
        if (result == 0) {
            added++;
        } else {
            break;  // Reached capacity
        }
    }

    ASSERT(added > 0, "Should be able to add at least one cookie");
    ASSERT(added <= max_size, "Should not exceed max size");

    kcookie_jar_free(jar);
}

/* ==================== Main ==================== */

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("          Cookie-C (kcookie) Comprehensive Test Suite\n");
    printf("════════════════════════════════════════════════════════════════\n");

    // Jar creation tests
    test_jar_creation();
    test_jar_capacity();

    // Set/Get tests
    test_cookie_set_get();
    test_cookie_multiple_set();
    test_cookie_overwrite();

    // Options tests
    test_cookie_options_secure();
    test_cookie_options_http_only();
    test_cookie_options_same_site();

    // Parsing tests
    test_cookie_parse_basic();
    test_cookie_parse_with_options();
    test_cookie_parse_multiple();

    // Encoding tests
    test_cookie_encode();
    test_cookie_decode();

    // Zero-copy tests
    test_zerocopy_entry();

    // Deletion tests
    test_cookie_delete();
    test_cookie_clear();

    // Memory tests
    test_memory_lifecycle_set_get();
    test_memory_lifecycle_parsing();

    // Safety tests
    test_null_pointer_safety();

    // Limit tests
    test_jar_size_limit();

    // Summary
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Test Results: %d PASSED, %d FAILED\n", tests_passed, tests_failed);

    if (tests_failed == 0) {
        printf("✅ ALL TESTS PASSED!\n");
    } else {
        printf("❌ SOME TESTS FAILED!\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return tests_failed > 0 ? 1 : 0;
}

