/*
 * Cookie-Crypto-C Comprehensive Test Suite
 *
 * Test Coverage:
 * - Crypto provider initialization
 * - FNV-1a hashing algorithm
 * - HMAC-SHA256 algorithm
 * - Cookie signing and verification
 * - Provider switching
 * - Algorithm detection
 * - Signature length validation
 * - Error handling
 * - Memory safety
 */

#include "../kcookie.h"
#include "../kcookie_crypto.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

static int tests_passed = 0;
static int tests_failed = 0;

#define ASSERT(condition, message) \
    do { \
        if (!(condition)) { \
            printf("  ❌ FAILED: %s\n", message); \
            tests_failed++; \
        } else { \
            printf("  ✅ %s\n", message); \
            tests_passed++; \
        } \
    } while (0)

/* ==================== Provider Access ==================== */

void test_get_default_provider(void) {
    printf("\nTest: Get Default Provider\n");

    kcookie_crypto_provider_t *provider = kcookie_get_crypto_provider();
    ASSERT(provider != NULL, "Default provider should exist");
    ASSERT(provider->algorithm >= 0, "Provider should have valid algorithm");
}

void test_fnv1a_provider(void) {
    printf("\nTest: FNV-1a Provider\n");

    kcookie_crypto_provider_t *fnv = kcookie_crypto_fnv1a();
    ASSERT(fnv != NULL, "FNV-1a provider should exist");
    ASSERT(fnv->algorithm == KCOOKIE_HASH_FNV1A, "Algorithm should be FNV-1a");
    ASSERT(fnv->name != NULL, "Provider should have a name");
}

void test_hmac_sha256_provider(void) {
    printf("\nTest: HMAC-SHA256 Provider\n");

    kcookie_crypto_provider_t *hmac = kcookie_crypto_hmac_sha256();
    ASSERT(hmac != NULL, "HMAC-SHA256 provider should exist");
    ASSERT(hmac->algorithm == KCOOKIE_HASH_HMAC_SHA256, "Algorithm should be HMAC-SHA256");
    ASSERT(hmac->name != NULL, "Provider should have a name");
}

void test_set_provider_fnv1a(void) {
    printf("\nTest: Set Provider - FNV-1a\n");

    kcookie_crypto_provider_t *fnv = kcookie_crypto_fnv1a();
    kcookie_set_crypto_provider(fnv);

    kcookie_crypto_provider_t *current = kcookie_get_crypto_provider();
    ASSERT(current->algorithm == KCOOKIE_HASH_FNV1A, "FNV-1a should be set");
}

void test_set_provider_hmac_sha256(void) {
    printf("\nTest: Set Provider - HMAC-SHA256\n");

    kcookie_crypto_provider_t *hmac = kcookie_crypto_hmac_sha256();
    kcookie_set_crypto_provider(hmac);

    kcookie_crypto_provider_t *current = kcookie_get_crypto_provider();
    ASSERT(current->algorithm == KCOOKIE_HASH_HMAC_SHA256, "HMAC-SHA256 should be set");
}

void test_reset_provider(void) {
    printf("\nTest: Reset Provider to Default\n");

    // Set to a specific provider
    kcookie_set_crypto_provider(kcookie_crypto_hmac_sha256());

    // Reset to default (NULL)
    kcookie_set_crypto_provider(NULL);

    kcookie_crypto_provider_t *current = kcookie_get_crypto_provider();
    ASSERT(current != NULL, "Should have default provider after reset");
}

/* ==================== Provider Functions ==================== */

void test_provider_has_sign_function(void) {
    printf("\nTest: Provider Has Sign Function\n");

    kcookie_crypto_provider_t *provider = kcookie_get_crypto_provider();
    ASSERT(provider->sign != NULL, "Provider should have sign function");
}

void test_provider_has_verify_function(void) {
    printf("\nTest: Provider Has Verify Function\n");

    kcookie_crypto_provider_t *provider = kcookie_get_crypto_provider();
    ASSERT(provider->verify != NULL, "Provider should have verify function");
}

void test_provider_has_signature_length_function(void) {
    printf("\nTest: Provider Has Signature Length Function\n");

    kcookie_crypto_provider_t *provider = kcookie_get_crypto_provider();
    ASSERT(provider->signature_length != NULL, "Provider should have signature_length function");
}

/* ==================== Signature Length ==================== */

void test_fnv1a_signature_length(void) {
    printf("\nTest: FNV-1a Signature Length\n");

    kcookie_crypto_provider_t *fnv = kcookie_crypto_fnv1a();
    size_t len = fnv->signature_length();

    ASSERT(len == 16, "FNV-1a signature should be 16 characters");
}

void test_hmac_sha256_signature_length(void) {
    printf("\nTest: HMAC-SHA256 Signature Length\n");

    kcookie_crypto_provider_t *hmac = kcookie_crypto_hmac_sha256();
    size_t len = hmac->signature_length();

    ASSERT(len == 64, "HMAC-SHA256 signature should be 64 characters");
}

/* ==================== Signing ==================== */

void test_sign_with_fnv1a(void) {
    printf("\nTest: Sign With FNV-1a\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char signed_value[512];
    int result = kcookie_sign("test_value", "secret_key", signed_value, sizeof(signed_value));

    ASSERT(result == 0, "FNV-1a signing should succeed");
    ASSERT(strlen(signed_value) > 0, "Signature should not be empty");
}

void test_sign_with_hmac_sha256(void) {
    printf("\nTest: Sign With HMAC-SHA256\n");

    kcookie_set_crypto_provider(kcookie_crypto_hmac_sha256());

    char signed_value[512];
    int result = kcookie_sign("test_value", "secret_key", signed_value, sizeof(signed_value));

    ASSERT(result == 0, "HMAC-SHA256 signing should succeed");
    ASSERT(strlen(signed_value) > 0, "Signature should not be empty");
}

void test_sign_deterministic(void) {
    printf("\nTest: Sign Deterministic\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char sig1[512], sig2[512];
    kcookie_sign("value", "key", sig1, sizeof(sig1));
    kcookie_sign("value", "key", sig2, sizeof(sig2));

    ASSERT(strcmp(sig1, sig2) == 0, "Same input should produce same signature");
}

void test_sign_different_values(void) {
    printf("\nTest: Sign Different Values\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char sig1[512], sig2[512];
    kcookie_sign("value1", "key", sig1, sizeof(sig1));
    kcookie_sign("value2", "key", sig2, sizeof(sig2));

    ASSERT(strcmp(sig1, sig2) != 0, "Different values should produce different signatures");
}

void test_sign_different_keys(void) {
    printf("\nTest: Sign Different Keys\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char sig1[512], sig2[512];
    kcookie_sign("value", "key1", sig1, sizeof(sig1));
    kcookie_sign("value", "key2", sig2, sizeof(sig2));

    ASSERT(strcmp(sig1, sig2) != 0, "Different keys should produce different signatures");
}

/* ==================== Verification ==================== */

void test_verify_valid_fnv1a(void) {
    printf("\nTest: Verify Valid - FNV-1a\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char signed_value[512];
    kcookie_sign("original", "secret", signed_value, sizeof(signed_value));

    char unsigned_value[512];
    int result = kcookie_unsign(signed_value, "secret", unsigned_value, sizeof(unsigned_value));

    ASSERT(result == 0, "Verification with correct secret should succeed");
    ASSERT(strcmp(unsigned_value, "original") == 0 || strlen(unsigned_value) > 0, "Value should be recovered");
}

void test_verify_valid_hmac_sha256(void) {
    printf("\nTest: Verify Valid - HMAC-SHA256\n");

    kcookie_set_crypto_provider(kcookie_crypto_hmac_sha256());

    char signed_value[512];
    kcookie_sign("original", "secret", signed_value, sizeof(signed_value));

    char unsigned_value[512];
    int result = kcookie_unsign(signed_value, "secret", unsigned_value, sizeof(unsigned_value));

    ASSERT(result == 0, "HMAC-SHA256 verification should succeed");
}

void test_verify_wrong_secret(void) {
    printf("\nTest: Verify Wrong Secret\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char signed_value[512];
    kcookie_sign("value", "secret1", signed_value, sizeof(signed_value));

    char unsigned_value[512];
    int result = kcookie_unsign(signed_value, "secret2", unsigned_value, sizeof(unsigned_value));

    ASSERT(result == -1, "Verification with wrong secret should fail");
}

void test_verify_wrong_value(void) {
    printf("\nTest: Verify Tampered Value\n");

    kcookie_set_crypto_provider(kcookie_crypto_fnv1a());

    char signed_value[512];
    kcookie_sign("original", "secret", signed_value, sizeof(signed_value));

    // Tamper with the signed value
