/**
 * Kim-BodyParser - Pure C Request Body Parser
 * Parse JSON and form-urlencoded request bodies
 * License: MIT
 */

#ifndef KBODY_H
#define KBODY_H

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

#define KBODY_VERSION "1.0.0"
#define KBODY_MAX_BODY_SIZE (10 * 1024 * 1024)  // 10MB
#define KBODY_MAX_FIELDS 256
#define KBODY_MAX_KEY_LEN 256
#define KBODY_MAX_VALUE_LEN 8192

typedef enum {
    KBODY_JSON,
    KBODY_FORM,
    KBODY_UNKNOWN
} kbody_type_t;

typedef struct {
    char key[KBODY_MAX_KEY_LEN];
    char value[KBODY_MAX_VALUE_LEN];
    int  is_string;
} kbody_field_t;

typedef struct {
    kbody_type_t type;
    char *raw_body;
    size_t raw_len;
    kbody_field_t fields[KBODY_MAX_FIELDS];
    int field_count;
    int is_valid;
    char error_msg[256];
} kbody_t;

// Parse body from raw buffer
int kbody_parse(const char *content_type, const char *body, size_t len, kbody_t *result);

// Get field value by key
const char* kbody_get(const kbody_t *body, const char *key);

// Check if field exists
bool kbody_has(const kbody_t *body, const char *key);

// Get field as integer
int kbody_get_int(const kbody_t *body, const char *key, int default_val);

// Get field as boolean
bool kbody_get_bool(const kbody_t *body, const char *key, bool default_val);

// Get field as double
double kbody_get_double(const kbody_t *body, const char *key, double default_val);

// Get field count
int kbody_count(const kbody_t *body);

// Validate JSON syntax
bool kbody_is_valid_json(const char *json);

// Validate form syntax
bool kbody_is_valid_form(const char *form);

// Get error message
const char* kbody_error(const kbody_t *body);

// Clean up
void kbody_clear(kbody_t *body);

// Iterate fields
typedef void (*kbody_iterator_t)(const char *key, const char *value, void *userdata);
void kbody_foreach(const kbody_t *body, kbody_iterator_t cb, void *userdata);

#endif // KBODY_H

