    ASSERT(result == 0, "JSON parsing should succeed");
    ASSERT(body.type == KBODY_JSON, "Body type should be JSON");
    ASSERT(body.field_count > 0, "Should parse fields");
    ASSERT(body.is_valid, "Body should be valid");

    kbody_clear(&body);
}

void test_parse_json_multiple_fields(void) {
    printf("\nTest: Parse JSON - Multiple Fields\n");

    kbody_t body;
    const char *json = "{\"id\":\"1\",\"username\":\"alice\",\"email\":\"alice@test.com\",\"active\":\"true\"}";
    int result = kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(result == 0, "Parsing multiple fields should succeed");
    ASSERT(body.field_count >= 3, "Should parse at least 3 fields");

    kbody_clear(&body);
}

void test_parse_json_nested_simple(void) {
    printf("\nTest: Parse JSON - Simple Nested\n");

    kbody_t body;
    const char *json = "{\"user\":{\"name\":\"bob\"}}";
    int result = kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(result == 0 || result == -1, "Should handle nested JSON");

    kbody_clear(&body);
}

void test_json_type_detection(void) {
    printf("\nTest: JSON Type Detection\n");

    kbody_t body;
    const char *json = "{\"key\":\"value\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(body.type == KBODY_JSON, "Content-Type should indicate JSON");

    kbody_clear(&body);
}

