            break;
        }

        kbody_clear(&body);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    kbody_t body;

    // NULL content type
    kbody_parse(NULL, "{\"a\":\"1\"}", 13, &body);

    // NULL body
    kbody_parse("application/json", NULL, 0, &body);

    // NULL key
    kbody_get(&body, NULL);

    ASSERT(true, "NULL pointer operations handled");

    kbody_clear(&body);
