    ASSERT(strlen(sql) > 0, "Query string should not be empty");

    kknex_free(q);
}

void test_select_specific_columns(void) {
    printf("\nTest: SELECT Specific Columns\n");

    kknex_query_t *q = kknex_new();
    kknex_table(q, "users");
