    kknex_free(q);
}

void test_select_with_where(void) {
    printf("\nTest: SELECT With WHERE\n");

    kknex_query_t *q = kknex_new();
    kknex_table(q, "users");
    kknex_select(q, "*");
    kknex_where(q, "age > 18");

