    kknex_query_t *q = kknex_new();
    kknex_table(q, "users");
    kknex_left_join(q, "orders", "users.id = orders.user_id");

    ASSERT(strlen(q->join_clause) > 0, "LEFT JOIN clause set");

    kknex_free(q);
}

void test_multiple_joins(void) {
