    kknex_query_t *q = kknex_new();
    kknex_table(q, "users");
    kknex_join(q, "orders", "users.id = orders.user_id");
    kknex_left_join(q, "payments", "orders.id = payments.order_id");

    ASSERT(strlen(q->join_clause) > 0, "Multiple joins set");

    kknex_free(q);
}

/* ==================== GROUP BY and ORDER BY ==================== */

void test_group_by(void) {
