    kknex_table(q, "users");
    kknex_where(q, "id = 1");
    char *sql = kknex_update(q, "name = 'jane', email = 'jane@test.com'");

    ASSERT(sql != NULL, "UPDATE query generated");

    kknex_free(q);
}

void test_update_with_where(void) {
