    kknex_query_t *q = kknex_new();
    kknex_table(q, "users");
    kknex_where(q, "status = 'inactive'");
    char *sql = kknex_update(q, "status = 'deleted'");

    ASSERT(sql != NULL, "UPDATE with WHERE generated");

    kknex_free(q);
}

/* ==================== DELETE Queries ==================== */

void test_delete_basic(void) {
