    ASSERT(sql != NULL, "DELETE with condition generated");

    kknex_free(q);
}

/* ==================== Query String Generation ==================== */

void test_to_string(void) {
    printf("\nTest: To String\n");

    kknex_query_t *q = kknex_new();
