    kknex_order_by(q, "orders.created_at", "DESC");

    char *sql = kknex_to_select(q);
    ASSERT(sql != NULL, "Complex JOIN query generated");

    kknex_free(q);
}

/* ==================== Memory Lifecycle ==================== */

void test_memory_lifecycle_creation(void) {
    printf("\nTest: Memory Lifecycle - Creation (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        kknex_query_t *q = kknex_new();
        if (q == NULL) {
            ASSERT(false, "Query creation failed");
            break;
        }

        char table[256];
        snprintf(table, sizeof(table), "table_%d", i);
        kknex_table(q, table);

        kknex_free(q);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

void test_memory_lifecycle_query_building(void) {
    printf("\nTest: Memory Lifecycle - Query Building (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        kknex_query_t *q = kknex_new();

        kknex_table(q, "users");
        kknex_select(q, "*");
        kknex_where(q, "id > 0");
        kknex_order_by(q, "id", "ASC");
        kknex_limit(q, 10);

        char *sql = kknex_to_select(q);
        if (sql == NULL) {
            ASSERT(false, "Query generation failed");
            kknex_free(q);
            break;
        }

        kknex_free(q);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    kknex_query_t *q = kknex_new();

    // NULL table
    kknex_table(q, NULL);

    // NULL columns
    kknex_select(q, NULL);

    // NULL where clause
    kknex_where(q, NULL);

    // NULL join table
    kknex_join(q, NULL, "condition");

    kknex_free(q);
    ASSERT(true, "NULL pointer operations handled");
}

/* ==================== Main ==================== */

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("           Knex-C (kknex) Comprehensive Test Suite\n");
    printf("════════════════════════════════════════════════════════════════\n");

    // Builder creation tests
    test_create_query_builder();
    test_free_query();

    // Table selection tests
    test_select_table();
    test_select_different_tables();

    // SELECT query tests
    test_select_all_columns();
    test_select_specific_columns();
    test_select_with_where();
    test_select_with_multiple_conditions();
    test_select_with_or_condition();

    // Parameter binding tests
    test_bind_parameter();
    test_bind_multiple_parameters();

    // JOIN tests
    test_inner_join();
    test_left_join();
    test_multiple_joins();

    // GROUP BY and ORDER BY tests
    test_group_by();
    test_order_by();
    test_order_by_descending();

    // LIMIT and OFFSET tests
    test_limit();
    test_offset();
    test_limit_and_offset();

    // INSERT tests
    test_insert_basic();
    test_insert_multiple_values();

    // UPDATE tests
    test_update_basic();
    test_update_with_where();

    // DELETE tests
    test_delete_basic();
    test_delete_with_condition();

    // Query string generation tests
    test_to_string();

    // Complex query tests
    test_complex_select_query();
    test_complex_select_with_join();

    // Memory tests
    test_memory_lifecycle_creation();
    test_memory_lifecycle_query_building();

    // Safety tests
    test_null_pointer_safety();

    // Summary
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Test Results: %d PASSED, %d FAILED\n", tests_passed, tests_failed);

    if (tests_failed == 0) {
        printf("✅ ALL TESTS PASSED!\n");
    } else {
        printf("❌ SOME TESTS FAILED!\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return tests_failed > 0 ? 1 : 0;
}

