        ASSERT(result >= -1, "Empty send handled");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Empty send valid");
    }
}

void test_send_large_data(void) {
    printf("\nTest: Send Large Data\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
