    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[256];
        int result = kconnect_recv(conn, buffer, sizeof(buffer));

        ASSERT(result >= -1, "Receive operation valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Receive function callable");
    }
}

void test_recv_empty_buffer(void) {
    printf("\nTest: Recv - Empty Buffer Size\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[256];
