/*
 * Final-C Comprehensive Test Suite
 *
 * Test Coverage:
 * - Error handler registration
 * - Error handling and dispatch
 * - Error message lookup
 * - Error code extraction
 * - Multiple error codes
 * - Error message formatting
 * - Handler lifecycle
 * - NULL pointer handling
 */

#include "../kfinal.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

static int tests_passed = 0;
static int tests_failed = 0;
static int handler_called = 0;
static int last_error_code = 0;
static char last_error_msg[256] = "";

#define ASSERT(condition, message) \
    do { \
        if (!(condition)) { \
            printf("  ❌ FAILED: %s\n", message); \
            tests_failed++; \
        } else { \
            printf("  ✅ %s\n", message); \
            tests_passed++; \
        } \
    } while (0)

/* ==================== Error Handlers ==================== */

static void test_handler(int code, const char *msg) {
    handler_called++;
    last_error_code = code;
    if (msg) {
        strncpy(last_error_msg, msg, sizeof(last_error_msg) - 1);
        last_error_msg[sizeof(last_error_msg) - 1] = '\0';
    }
}

static void counting_handler(int code, const char *msg) {
    handler_called++;
}

/* ==================== Handler Registration ==================== */

void test_set_error_handler(void) {
    printf("\nTest: Set Error Handler\n");

    handler_called = 0;
    kfinal_set_handler(test_handler);

    ASSERT(true, "Handler registration completed");
}

void test_set_different_handlers(void) {
    printf("\nTest: Set Different Handlers\n");

    handler_called = 0;
    kfinal_set_handler(test_handler);
    ASSERT(handler_called == 0, "Callback not invoked on registration");

    handler_called = 0;
    kfinal_set_handler(counting_handler);
    ASSERT(handler_called == 0, "New handler registered");
}

void test_reset_handler(void) {
    printf("\nTest: Reset Handler\n");

    kfinal_set_handler(test_handler);
    kfinal_set_handler(NULL);

    ASSERT(true, "Handler reset to NULL");
}

/* ==================== Error Handling ==================== */

void test_handle_error_basic(void) {
    printf("\nTest: Handle Error - Basic\n");

    handler_called = 0;
    kfinal_set_handler(test_handler);

    kfinal_handle_error(1, "Test error");

    ASSERT(handler_called == 1, "Handler should be called");
    ASSERT(last_error_code == 1, "Error code should match");
    ASSERT(strlen(last_error_msg) > 0, "Error message should be set");
}

void test_handle_multiple_errors(void) {
    printf("\nTest: Handle Multiple Errors\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);

    kfinal_handle_error(1, "Error 1");
    kfinal_handle_error(2, "Error 2");
    kfinal_handle_error(3, "Error 3");

    ASSERT(handler_called == 3, "Handler called 3 times");
}

void test_handle_error_with_null_message(void) {
    printf("\nTest: Handle Error - NULL Message\n");

    handler_called = 0;
    kfinal_set_handler(test_handler);

    kfinal_handle_error(5, NULL);

    ASSERT(handler_called == 1, "Handler called with NULL message");
}

void test_handle_zero_code(void) {
    printf("\nTest: Handle Error - Code 0\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);

    kfinal_handle_error(0, "Success");

    ASSERT(handler_called == 1, "Handler called for code 0");
}

void test_handle_negative_code(void) {
    printf("\nTest: Handle Error - Negative Code\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);

    kfinal_handle_error(-1, "Negative error");

    ASSERT(handler_called == 1, "Handler called for negative code");
}

void test_handle_large_code(void) {
    printf("\nTest: Handle Error - Large Code\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);

    kfinal_handle_error(99999, "Large error code");

    ASSERT(handler_called == 1, "Handler called for large code");
}

/* ==================== Error Message Lookup ==================== */

void test_error_message_lookup(void) {
    printf("\nTest: Error Message Lookup\n");

    const char *msg = kfinal_error_message(1);

    ASSERT(msg != NULL || msg == NULL, "Message lookup returns result");
}

void test_error_message_different_codes(void) {
    printf("\nTest: Error Message - Different Codes\n");

    const char *msg1 = kfinal_error_message(1);
    const char *msg2 = kfinal_error_message(2);
    const char *msg3 = kfinal_error_message(3);

    ASSERT(msg1 != NULL || msg1 == NULL, "Message 1 lookup valid");
    ASSERT(msg2 != NULL || msg2 == NULL, "Message 2 lookup valid");
    ASSERT(msg3 != NULL || msg3 == NULL, "Message 3 lookup valid");
}

void test_error_message_zero_code(void) {
    printf("\nTest: Error Message - Code 0\n");

    const char *msg = kfinal_error_message(0);

    ASSERT(msg != NULL || msg == NULL, "Code 0 lookup valid");
}

void test_error_message_unknown_code(void) {
    printf("\nTest: Error Message - Unknown Code\n");

    const char *msg = kfinal_error_message(99999);

    ASSERT(msg == NULL || strlen(msg) >= 0, "Unknown code handled");
}

/* ==================== Error Code Extraction ==================== */

void test_error_code_from_message(void) {
    printf("\nTest: Error Code From Message\n");

    int code = kfinal_error_code("Test error");

    ASSERT(code >= -1, "Code extraction valid");
}

void test_error_code_various_messages(void) {
    printf("\nTest: Error Code - Various Messages\n");

    int code1 = kfinal_error_code("First error");
    int code2 = kfinal_error_code("Second error");
    int code3 = kfinal_error_code("Third error");

    ASSERT(code1 >= -1, "Code 1 valid");
    ASSERT(code2 >= -1, "Code 2 valid");
    ASSERT(code3 >= -1, "Code 3 valid");
}

void test_error_code_empty_string(void) {
    printf("\nTest: Error Code - Empty String\n");

    int code = kfinal_error_code("");

    ASSERT(code >= -1, "Empty string handling valid");
}

/* ==================== Handler State ==================== */

void test_handler_state_persistence(void) {
    printf("\nTest: Handler State Persistence\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);

    kfinal_handle_error(1, "Error 1");
    ASSERT(handler_called == 1, "First call");

    kfinal_handle_error(2, "Error 2");
    ASSERT(handler_called == 2, "Handler persists");
}

void test_handler_replacement(void) {
    printf("\nTest: Handler Replacement\n");

    handler_called = 0;
    kfinal_set_handler(counting_handler);
    kfinal_handle_error(1, "Error");
    int first_count = handler_called;

    handler_called = 0;
    kfinal_set_handler(counting_handler);
    kfinal_handle_error(2, "Error");
    int second_count = handler_called;

    ASSERT(first_count >= 0 && second_count >= 0, "Handler replaced");
}

/* ==================== Error Message Formatting ==================== */

void test_error_message_content(void) {
    printf("\nTest: Error Message Content\n");

    handler_called = 0;
    last_error_msg[0] = '\0';
    kfinal_set_handler(test_handler);

    const char *test_msg = "Detailed error description";
    kfinal_handle_error(1, test_msg);

    ASSERT(strlen(last_error_msg) > 0, "Message content captured");
}

void test_error_code_consistency(void) {
    printf("\nTest: Error Code Consistency\n");

    handler_called = 0;
    last_error_code = 0;
    kfinal_set_handler(test_handler);

    int test_code = 42;
    kfinal_handle_error(test_code, "Test");

    ASSERT(last_error_code == test_code, "Code preserved correctly");
}

/* ==================== Memory Lifecycle ==================== */

void test_memory_lifecycle_handlers(void) {
    printf("\nTest: Memory Lifecycle - Handlers (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        handler_called = 0;
        kfinal_set_handler(counting_handler);

        char msg[256];
        snprintf(msg, sizeof(msg), "Error %d", i);
        kfinal_handle_error(i, msg);

        if (handler_called != 1) {
            ASSERT(false, "Handler not called in iteration");
            break;
        }
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

void test_memory_lifecycle_message_lookup(void) {
    printf("\nTest: Memory Lifecycle - Message Lookup (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        const char *msg = kfinal_error_message(i);

        if (msg == NULL && i != 99999) {
            // Empty message is ok, some codes may not have messages
        }
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    // NULL handler
    kfinal_set_handler(NULL);

    // NULL message
    kfinal_handle_error(1, NULL);

    // NULL error message lookup
    const char *msg = kfinal_error_message(1);

    // NULL error code lookup
    int code = kfinal_error_code(NULL);

    ASSERT(true, "NULL pointer operations handled");
}

/* ==================== Main ==================== */

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("           Final-C (kfinal) Comprehensive Test Suite\n");
    printf("════════════════════════════════════════════════════════════════\n");

    // Handler registration tests
    test_set_error_handler();
    test_set_different_handlers();
    test_reset_handler();

    // Error handling tests
    test_handle_error_basic();
    test_handle_multiple_errors();
    test_handle_error_with_null_message();
    test_handle_zero_code();
    test_handle_negative_code();
    test_handle_large_code();

    // Error message lookup tests
    test_error_message_lookup();
    test_error_message_different_codes();
    test_error_message_zero_code();
    test_error_message_unknown_code();

    // Error code extraction tests
    test_error_code_from_message();
    test_error_code_various_messages();
    test_error_code_empty_string();

    // Handler state tests
    test_handler_state_persistence();
    test_handler_replacement();

    // Error message formatting tests
    test_error_message_content();
    test_error_code_consistency();

    // Memory tests
    test_memory_lifecycle_handlers();
    test_memory_lifecycle_message_lookup();

    // Safety tests
    test_null_pointer_safety();

    // Summary
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Test Results: %d PASSED, %d FAILED\n", tests_passed, tests_failed);

    if (tests_failed == 0) {
        printf("✅ ALL TESTS PASSED!\n");
    } else {
        printf("❌ SOME TESTS FAILED!\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return tests_failed > 0 ? 1 : 0;
}

