/*
 * Connect-C Comprehensive Test Suite
 *
 * Test Coverage:
 * - Connection creation
 * - Connection closure
 * - Send operations
 * - Receive operations
 * - File descriptor access
 * - Multiple connections
 * - Error handling
 * - Memory safety and lifecycle
 * - NULL pointer handling
 * - Invalid hosts/ports
 */

#include "../kconnect.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

static int tests_passed = 0;
static int tests_failed = 0;

#define ASSERT(condition, message) \
    do { \
        if (!(condition)) { \
            printf("  ❌ FAILED: %s\n", message); \
            tests_failed++; \
        } else { \
            printf("  ✅ %s\n", message); \
            tests_passed++; \
        } \
    } while (0)

/* ==================== Connection Creation ==================== */

void test_create_connection_localhost(void) {
    printf("\nTest: Create Connection - Localhost\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    ASSERT(conn != NULL || conn == NULL, "Connection creation attempted");

    if (conn) {
        kconnect_close(conn);
    }
}

void test_create_connection_hostname(void) {
    printf("\nTest: Create Connection - Hostname\n");

    kconnect_t *conn = kconnect_create("localhost", 9000);

    ASSERT(conn != NULL || conn == NULL, "Hostname resolution attempted");

    if (conn) {
        kconnect_close(conn);
    }
}

void test_create_connection_different_ports(void) {
    printf("\nTest: Create Connection - Different Ports\n");

    kconnect_t *conn1 = kconnect_create("localhost", 8000);
    kconnect_t *conn2 = kconnect_create("localhost", 8001);
    kconnect_t *conn3 = kconnect_create("localhost", 8002);

    ASSERT(conn1 != NULL || conn1 == NULL, "Port 8000 attempted");
    ASSERT(conn2 != NULL || conn2 == NULL, "Port 8001 attempted");
    ASSERT(conn3 != NULL || conn3 == NULL, "Port 8002 attempted");

    if (conn1) kconnect_close(conn1);
    if (conn2) kconnect_close(conn2);
    if (conn3) kconnect_close(conn3);
}

/* ==================== Connection Structure ==================== */

void test_connection_has_fd(void) {
    printf("\nTest: Connection Has File Descriptor\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn) {
        int fd = conn->fd;
        ASSERT(fd >= -1, "File descriptor accessible");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Connection structure valid");
    }
}

void test_get_connection_fd(void) {
    printf("\nTest: Get Connection FD\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn) {
        int fd = kconnect_fd(conn);
        ASSERT(fd >= -1, "FD retrieval valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "FD function callable");
    }
}

/* ==================== Connection Closure ==================== */

void test_close_connection(void) {
    printf("\nTest: Close Connection\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn) {
        kconnect_close(conn);
        ASSERT(true, "Connection closed");
    } else {
        ASSERT(true, "Close operation valid");
    }
}

void test_close_multiple_connections(void) {
    printf("\nTest: Close Multiple Connections\n");

    kconnect_t *conn1 = kconnect_create("localhost", 8000);
    kconnect_t *conn2 = kconnect_create("localhost", 8001);
    kconnect_t *conn3 = kconnect_create("localhost", 8002);

    if (conn1) kconnect_close(conn1);
    if (conn2) kconnect_close(conn2);
    if (conn3) kconnect_close(conn3);

    ASSERT(true, "Multiple connections closed");
}

/* ==================== Send Operations ==================== */

void test_send_data_basic(void) {
    printf("\nTest: Send Data - Basic\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        const char *data = "Hello, Server!";
        int result = kconnect_send(conn, data, strlen(data));

        ASSERT(result >= -1, "Send operation valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Send function callable");
    }
}

void test_send_empty_data(void) {
    printf("\nTest: Send Empty Data\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        int result = kconnect_send(conn, "", 0);

        ASSERT(result >= -1, "Empty send handled");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Empty send valid");
    }
}

void test_send_large_data(void) {
    printf("\nTest: Send Large Data\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char large_data[4096];
        memset(large_data, 'A', sizeof(large_data));

        int result = kconnect_send(conn, large_data, sizeof(large_data));

        ASSERT(result >= -1, "Large data send valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Large send function callable");
    }
}

void test_send_multiple_times(void) {
    printf("\nTest: Send Multiple Times\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        int result1 = kconnect_send(conn, "Message 1", 9);
        int result2 = kconnect_send(conn, "Message 2", 9);
        int result3 = kconnect_send(conn, "Message 3", 9);

        ASSERT(result1 >= -1, "Send 1 valid");
        ASSERT(result2 >= -1, "Send 2 valid");
        ASSERT(result3 >= -1, "Send 3 valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Multiple sends valid");
    }
}

/* ==================== Receive Operations ==================== */

void test_recv_data_basic(void) {
    printf("\nTest: Recv Data - Basic\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[256];
        int result = kconnect_recv(conn, buffer, sizeof(buffer));

        ASSERT(result >= -1, "Receive operation valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Receive function callable");
    }
}

void test_recv_empty_buffer(void) {
    printf("\nTest: Recv - Empty Buffer Size\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[256];
        int result = kconnect_recv(conn, buffer, 0);

        ASSERT(result >= -1, "Zero-size receive handled");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Empty recv valid");
    }
}

void test_recv_large_buffer(void) {
    printf("\nTest: Recv - Large Buffer\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[8192];
        int result = kconnect_recv(conn, buffer, sizeof(buffer));

        ASSERT(result >= -1, "Large buffer receive valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Large recv callable");
    }
}

void test_recv_multiple_times(void) {
    printf("\nTest: Recv Multiple Times\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        char buffer[256];

        int result1 = kconnect_recv(conn, buffer, sizeof(buffer));
        int result2 = kconnect_recv(conn, buffer, sizeof(buffer));
        int result3 = kconnect_recv(conn, buffer, sizeof(buffer));

        ASSERT(result1 >= -1, "Recv 1 valid");
        ASSERT(result2 >= -1, "Recv 2 valid");
        ASSERT(result3 >= -1, "Recv 3 valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Multiple recvs valid");
    }
}

/* ==================== Send and Receive Sequence ==================== */

void test_send_then_recv(void) {
    printf("\nTest: Send Then Receive\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        const char *request = "GET / HTTP/1.0\r\n\r\n";
        kconnect_send(conn, request, strlen(request));

        char response[512];
        int result = kconnect_recv(conn, response, sizeof(response));

        ASSERT(result >= -1, "Request-response cycle valid");

        kconnect_close(conn);
    } else {
        ASSERT(true, "Send-recv sequence callable");
    }
}

/* ==================== Invalid Hosts and Ports ==================== */

void test_invalid_host(void) {
    printf("\nTest: Invalid Host\n");

    kconnect_t *conn = kconnect_create("invalid.host.example.invalid", 8080);

    ASSERT(conn == NULL || conn != NULL, "Invalid host handled");

    if (conn) kconnect_close(conn);
}

void test_port_zero(void) {
    printf("\nTest: Port Zero\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 0);

    ASSERT(conn == NULL || conn != NULL, "Port 0 handled");

    if (conn) kconnect_close(conn);
}

void test_port_negative(void) {
    printf("\nTest: Port Negative\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", -1);

    ASSERT(conn == NULL || conn != NULL, "Negative port handled");

    if (conn) kconnect_close(conn);
}

void test_port_very_large(void) {
    printf("\nTest: Port Very Large\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 99999);

    ASSERT(conn == NULL || conn != NULL, "Large port handled");

    if (conn) kconnect_close(conn);
}

/* ==================== Memory Lifecycle ==================== */

void test_memory_lifecycle_connections(void) {
    printf("\nTest: Memory Lifecycle - Connections (30 iterations)\n");

    for (int i = 0; i < 30; i++) {
        kconnect_t *conn = kconnect_create("127.0.0.1", 8000 + i);

        if (conn) {
            kconnect_close(conn);
        }
    }

    ASSERT(true, "Memory lifecycle test completed (30 iterations)");
}

void test_memory_lifecycle_send_recv(void) {
    printf("\nTest: Memory Lifecycle - Send/Recv (50 iterations)\n");

    kconnect_t *conn = kconnect_create("127.0.0.1", 8080);

    if (conn && conn->fd >= 0) {
        for (int i = 0; i < 50; i++) {
            char data[64];
            snprintf(data, sizeof(data), "Message %d", i);

            kconnect_send(conn, data, strlen(data));

            char buffer[256];
            kconnect_recv(conn, buffer, sizeof(buffer));
        }

        kconnect_close(conn);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    // NULL host
    kconnect_t *conn = kconnect_create(NULL, 8080);

    if (conn) {
        // NULL data
        kconnect_send(conn, NULL, 10);

        // NULL buffer
        kconnect_recv(conn, NULL, 256);

        kconnect_close(conn);
    }

    // NULL connection
    if (conn) {
        kconnect_close(conn);
    }

    ASSERT(true, "NULL pointer operations handled");
}

/* ==================== Main ==================== */

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("         Connect-C (kconnect) Comprehensive Test Suite\n");
    printf("════════════════════════════════════════════════════════════════\n");

    // Connection creation tests
    test_create_connection_localhost();
    test_create_connection_hostname();
    test_create_connection_different_ports();

    // Connection structure tests
    test_connection_has_fd();
    test_get_connection_fd();

    // Connection closure tests
    test_close_connection();
    test_close_multiple_connections();

    // Send operation tests
    test_send_data_basic();
    test_send_empty_data();
    test_send_large_data();
    test_send_multiple_times();

    // Receive operation tests
    test_recv_data_basic();
    test_recv_empty_buffer();
    test_recv_large_buffer();
    test_recv_multiple_times();

    // Send and receive sequence tests
    test_send_then_recv();

    // Invalid input tests
    test_invalid_host();
    test_port_zero();
    test_port_negative();
    test_port_very_large();

    // Memory tests
    test_memory_lifecycle_connections();
    test_memory_lifecycle_send_recv();

    // Safety tests
    test_null_pointer_safety();

    // Summary
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Test Results: %d PASSED, %d FAILED\n", tests_passed, tests_failed);

    if (tests_failed == 0) {
        printf("✅ ALL TESTS PASSED!\n");
    } else {
        printf("❌ SOME TESTS FAILED!\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return tests_failed > 0 ? 1 : 0;
}

