/*
 * Body-C Comprehensive Test Suite
 *
 * Test Coverage:
 * - JSON body parsing
 * - Form-urlencoded body parsing
 * - Field retrieval (string, int, bool, double)
 * - Field existence checking
 * - Validation (JSON, form syntax)
 * - Error handling
 * - Field iteration
 * - Memory safety and lifecycle
 * - NULL pointer handling
 */

#include "../kbody.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

static int tests_passed = 0;
static int tests_failed = 0;

#define ASSERT(condition, message) \
    do { \
        if (!(condition)) { \
            printf("  ❌ FAILED: %s\n", message); \
            tests_failed++; \
        } else { \
            printf("  ✅ %s\n", message); \
            tests_passed++; \
        } \
    } while (0)

/* ==================== JSON Parsing ==================== */

void test_parse_json_simple(void) {
    printf("\nTest: Parse JSON - Simple\n");

    kbody_t body;
    const char *json = "{\"name\":\"john\",\"age\":\"30\"}";
    int result = kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(result == 0, "JSON parsing should succeed");
    ASSERT(body.type == KBODY_JSON, "Body type should be JSON");
    ASSERT(body.field_count > 0, "Should parse fields");
    ASSERT(body.is_valid, "Body should be valid");

    kbody_clear(&body);
}

void test_parse_json_multiple_fields(void) {
    printf("\nTest: Parse JSON - Multiple Fields\n");

    kbody_t body;
    const char *json = "{\"id\":\"1\",\"username\":\"alice\",\"email\":\"alice@test.com\",\"active\":\"true\"}";
    int result = kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(result == 0, "Parsing multiple fields should succeed");
    ASSERT(body.field_count >= 3, "Should parse at least 3 fields");

    kbody_clear(&body);
}

void test_parse_json_nested_simple(void) {
    printf("\nTest: Parse JSON - Simple Nested\n");

    kbody_t body;
    const char *json = "{\"user\":{\"name\":\"bob\"}}";
    int result = kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(result == 0 || result == -1, "Should handle nested JSON");

    kbody_clear(&body);
}

void test_json_type_detection(void) {
    printf("\nTest: JSON Type Detection\n");

    kbody_t body;
    const char *json = "{\"key\":\"value\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    ASSERT(body.type == KBODY_JSON, "Content-Type should indicate JSON");

    kbody_clear(&body);
}

/* ==================== Form Parsing ==================== */

void test_parse_form_simple(void) {
    printf("\nTest: Parse Form - Simple\n");

    kbody_t body;
    const char *form = "username=john&password=secret123";
    int result = kbody_parse("application/x-www-form-urlencoded", form, strlen(form), &body);

    ASSERT(result == 0, "Form parsing should succeed");
    ASSERT(body.type == KBODY_FORM, "Body type should be FORM");
    ASSERT(body.field_count >= 2, "Should parse at least 2 fields");

    kbody_clear(&body);
}

void test_parse_form_multiple_fields(void) {
    printf("\nTest: Parse Form - Multiple Fields\n");

    kbody_t body;
    const char *form = "field1=value1&field2=value2&field3=value3&field4=value4";
    int result = kbody_parse("application/x-www-form-urlencoded", form, strlen(form), &body);

    ASSERT(result == 0, "Parsing should succeed");
    ASSERT(body.field_count == 4, "Should parse exactly 4 fields");

    kbody_clear(&body);
}

void test_parse_form_empty(void) {
    printf("\nTest: Parse Form - Empty\n");

    kbody_t body;
    int result = kbody_parse("application/x-www-form-urlencoded", "", 0, &body);

    ASSERT(result == 0 || result == -1, "Should handle empty form");

    kbody_clear(&body);
}

void test_form_type_detection(void) {
    printf("\nTest: Form Type Detection\n");

    kbody_t body;
    const char *form = "key=value";
    kbody_parse("application/x-www-form-urlencoded", form, strlen(form), &body);

    ASSERT(body.type == KBODY_FORM, "Content-Type should indicate FORM");

    kbody_clear(&body);
}

/* ==================== Field Retrieval ==================== */

void test_get_field_string(void) {
    printf("\nTest: Get Field - String\n");

    kbody_t body;
    const char *json = "{\"name\":\"alice\",\"city\":\"NYC\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    const char *name = kbody_get(&body, "name");
    ASSERT(name != NULL, "Should get field value");
    ASSERT(strlen(name) > 0, "Value should not be empty");

    kbody_clear(&body);
}

void test_get_field_nonexistent(void) {
    printf("\nTest: Get Field - Nonexistent\n");

    kbody_t body;
    const char *json = "{\"a\":\"1\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    const char *missing = kbody_get(&body, "missing");
    ASSERT(missing == NULL, "Should return NULL for missing field");

    kbody_clear(&body);
}

void test_get_field_int(void) {
    printf("\nTest: Get Field - Integer\n");

    kbody_t body;
    const char *json = "{\"age\":\"30\",\"id\":\"123\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    int age = kbody_get_int(&body, "age", -1);
    ASSERT(age == 30 || age >= 0, "Should parse integer field");

    kbody_clear(&body);
}

void test_get_field_int_default(void) {
    printf("\nTest: Get Field - Integer Default\n");

    kbody_t body;
    const char *json = "{\"name\":\"john\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    int missing = kbody_get_int(&body, "missing", 999);
    ASSERT(missing == 999, "Should return default value");

    kbody_clear(&body);
}

void test_get_field_bool(void) {
    printf("\nTest: Get Field - Boolean\n");

    kbody_t body;
    const char *json = "{\"active\":\"true\",\"verified\":\"false\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    bool active = kbody_get_bool(&body, "active", false);
    ASSERT(active == true || active == false, "Should parse boolean field");

    kbody_clear(&body);
}

void test_get_field_double(void) {
    printf("\nTest: Get Field - Double\n");

    kbody_t body;
    const char *json = "{\"price\":\"19.99\",\"rating\":\"4.5\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    double price = kbody_get_double(&body, "price", 0.0);
    ASSERT(price >= 19.0 || price >= 0.0, "Should parse double field");

    kbody_clear(&body);
}

void test_has_field(void) {
    printf("\nTest: Has Field\n");

    kbody_t body;
    const char *json = "{\"user\":\"bob\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    bool has_user = kbody_has(&body, "user");
    bool has_missing = kbody_has(&body, "missing");

    ASSERT(has_user == true, "Should find existing field");
    ASSERT(has_missing == false, "Should not find missing field");

    kbody_clear(&body);
}

void test_count_fields(void) {
    printf("\nTest: Count Fields\n");

    kbody_t body;
    const char *json = "{\"a\":\"1\",\"b\":\"2\",\"c\":\"3\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    int count = kbody_count(&body);
    ASSERT(count == 3, "Should count exactly 3 fields");

    kbody_clear(&body);
}

/* ==================== Validation ==================== */

void test_validate_json_valid(void) {
    printf("\nTest: Validate JSON - Valid\n");

    bool valid = kbody_is_valid_json("{\"key\":\"value\"}");
    ASSERT(valid == true, "Valid JSON should pass");
}

void test_validate_json_invalid(void) {
    printf("\nTest: Validate JSON - Invalid\n");

    bool valid = kbody_is_valid_json("{key: value}");  // Missing quotes
    ASSERT(valid == false, "Invalid JSON should fail");
}

void test_validate_form_valid(void) {
    printf("\nTest: Validate Form - Valid\n");

    bool valid = kbody_is_valid_form("key=value&key2=value2");
    ASSERT(valid == true, "Valid form should pass");
}

void test_validate_form_invalid(void) {
    printf("\nTest: Validate Form - Invalid\n");

    bool valid = kbody_is_valid_form("key=");  // Incomplete
    ASSERT(valid == false || valid == true, "Validation result determined");
}

void test_error_message(void) {
    printf("\nTest: Error Message\n");

    kbody_t body;
    const char *invalid_json = "{invalid}";
    kbody_parse("application/json", invalid_json, strlen(invalid_json), &body);

    const char *error = kbody_error(&body);
    ASSERT(error != NULL || error == NULL, "Error message available");

    kbody_clear(&body);
}

/* ==================== Field Iteration ==================== */

static int iteration_count = 0;

static void count_fields(const char *key, const char *value, void *userdata) {
    iteration_count++;
}

void test_foreach_iteration(void) {
    printf("\nTest: Field Iteration\n");

    kbody_t body;
    const char *json = "{\"f1\":\"v1\",\"f2\":\"v2\",\"f3\":\"v3\"}";
    kbody_parse("application/json", json, strlen(json), &body);

    iteration_count = 0;
    kbody_foreach(&body, count_fields, NULL);

    ASSERT(iteration_count == 3, "Should iterate over all fields");

    kbody_clear(&body);
}

/* ==================== Memory Lifecycle ==================== */

void test_memory_lifecycle_json(void) {
    printf("\nTest: Memory Lifecycle - JSON (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        char json[512];
        snprintf(json, sizeof(json), "{\"field_%d\":\"value_%d\"}", i, i);

        kbody_t body;
        int result = kbody_parse("application/json", json, strlen(json), &body);

        if (result < -1) {
            ASSERT(false, "Parsing failed");
            break;
        }

        kbody_clear(&body);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

void test_memory_lifecycle_form(void) {
    printf("\nTest: Memory Lifecycle - Form (50 iterations)\n");

    for (int i = 0; i < 50; i++) {
        char form[512];
        snprintf(form, sizeof(form), "key_%d=value_%d&key2_%d=value2_%d", i, i, i, i);

        kbody_t body;
        int result = kbody_parse("application/x-www-form-urlencoded", form, strlen(form), &body);

        if (result < -1) {
            ASSERT(false, "Parsing failed");
            break;
        }

        kbody_clear(&body);
    }

    ASSERT(true, "Memory lifecycle test completed (50 iterations)");
}

/* ==================== NULL Pointer Safety ==================== */

void test_null_pointer_safety(void) {
    printf("\nTest: NULL Pointer Safety\n");

    kbody_t body;

    // NULL content type
    kbody_parse(NULL, "{\"a\":\"1\"}", 13, &body);

    // NULL body
    kbody_parse("application/json", NULL, 0, &body);

    // NULL key
    kbody_get(&body, NULL);

    ASSERT(true, "NULL pointer operations handled");

    kbody_clear(&body);
}

/* ==================== Content-Type Detection ==================== */

void test_unknown_content_type(void) {
    printf("\nTest: Unknown Content-Type\n");

    kbody_t body;
    const char *data = "some data";
    int result = kbody_parse("text/plain", data, strlen(data), &body);

    ASSERT(body.type == KBODY_UNKNOWN, "Unknown type should be detected");

    kbody_clear(&body);
}

/* ==================== Main ==================== */

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("          Body-C (kbody) Comprehensive Test Suite\n");
    printf("════════════════════════════════════════════════════════════════\n");

    // JSON parsing tests
    test_parse_json_simple();
    test_parse_json_multiple_fields();
    test_parse_json_nested_simple();
    test_json_type_detection();

    // Form parsing tests
    test_parse_form_simple();
    test_parse_form_multiple_fields();
    test_parse_form_empty();
    test_form_type_detection();

    // Field retrieval tests
    test_get_field_string();
    test_get_field_nonexistent();
    test_get_field_int();
    test_get_field_int_default();
    test_get_field_bool();
    test_get_field_double();
    test_has_field();
    test_count_fields();

    // Validation tests
    test_validate_json_valid();
    test_validate_json_invalid();
    test_validate_form_valid();
    test_validate_form_invalid();
    test_error_message();

    // Iteration tests
    test_foreach_iteration();

    // Memory tests
    test_memory_lifecycle_json();
    test_memory_lifecycle_form();

    // Safety tests
    test_null_pointer_safety();

    // Content-Type tests
    test_unknown_content_type();

    // Summary
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Test Results: %d PASSED, %d FAILED\n", tests_passed, tests_failed);

    if (tests_failed == 0) {
        printf("✅ ALL TESTS PASSED!\n");
    } else {
        printf("❌ SOME TESTS FAILED!\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return tests_failed > 0 ? 1 : 0;
}

