   105→
   106→static int kbody_parse_json(const char *body, size_t len, kbody_t *result) {
   107→    // Simple JSON parser for basic key-value objects
   108→    char buffer[KBODY_MAX_BODY_SIZE];
   109→    if (len >= sizeof(buffer)) {
