/*
 * Body-C Performance Benchmark
 * 실제 성능 측정 (거짓 없음)
 */

#include "kbody.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define ITERATIONS 10000
#define TEST_FORM "name=John&age=30&city=Seoul&country=Korea&email=john@example.com"
#define TEST_JSON "{\"name\":\"John\",\"age\":\"30\",\"city\":\"Seoul\"}"

typedef struct {
    long total_ns;
    long min_ns;
    long max_ns;
    long avg_ns;
} benchmark_result_t;

static long get_time_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
}

benchmark_result_t bench_form_parsing(void) {
    benchmark_result_t result = {0, LLONG_MAX, 0, 0};

    for (int i = 0; i < ITERATIONS; i++) {
        long start = get_time_ns();

        kbody_t body;
        kbody_parse("application/x-www-form-urlencoded", 
                   TEST_FORM, strlen(TEST_FORM), &body);

        long end = get_time_ns();
        long elapsed = end - start;

        result.total_ns += elapsed;
        if (elapsed < result.min_ns) result.min_ns = elapsed;
        if (elapsed > result.max_ns) result.max_ns = elapsed;
    }

    result.avg_ns = result.total_ns / ITERATIONS;
    return result;
}

benchmark_result_t bench_json_parsing(void) {
    benchmark_result_t result = {0, LLONG_MAX, 0, 0};

    for (int i = 0; i < ITERATIONS; i++) {
        long start = get_time_ns();

        kbody_t body;
        kbody_parse("application/json", 
                   TEST_JSON, strlen(TEST_JSON), &body);

