/*
 * Memory Leak Detection Test
 * malloc/free 호출 추적
 */

#include "kbody.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int malloc_count = 0;
static int free_count = 0;
static long total_allocated = 0;
static long total_freed = 0;

// Wrapped malloc for tracking
void *tracked_malloc(size_t size) {
    malloc_count++;
    total_allocated += size;
    void *ptr = malloc(size);
    printf("  [MALLOC] #%d: %zu bytes @ %p\n", malloc_count, size, ptr);
    return ptr;
}

// Wrapped free for tracking
void tracked_free(void *ptr) {
    if (ptr) {
        free_count++;
        printf("  [FREE]   #%d: %p\n", free_count, ptr);
    }
}

void test_single_form_parse(void) {
    printf("\n=== Test 1: Single Form Parse ===\n");

    const char *form = "name=John&age=30&city=Seoul";

    printf("Parsing: %s\n", form);
    printf("Before parse: malloc=%d, free=%d\n", malloc_count, free_count);

    kbody_t body;
    kbody_parse("application/x-www-form-urlencoded", form, strlen(form), &body);

    printf("After parse: malloc=%d, free=%d\n", malloc_count, free_count);
    printf("Fields parsed: %d\n", body.field_count);

    kbody_clear(&body);
}

void test_multiple_parses(void) {
    printf("\n=== Test 2: 100 Sequential Parses ===\n");

    printf("Before: malloc=%d, free=%d\n", malloc_count, free_count);
    int malloc_before = malloc_count;
    int free_before = free_count;

    for (int i = 0; i < 100; i++) {
        kbody_t body;
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "field_%d=value_%d", i, i);

        kbody_parse("application/x-www-form-urlencoded", buffer, strlen(buffer), &body);
        kbody_clear(&body);
    }

    printf("After: malloc=%d, free=%d\n", malloc_count, free_count);
    printf("Difference: malloc_calls=%d, free_calls=%d\n",
           malloc_count - malloc_before,
           free_count - free_before);

    if (malloc_count - malloc_before == free_count - free_before) {
        printf("✅ NO MEMORY LEAK DETECTED\n");
    } else {
        printf("❌ POSSIBLE MEMORY LEAK\n");
    }
}

void test_json_parses(void) {
    printf("\n=== Test 3: 100 JSON Parses ===\n");

    printf("Before: malloc=%d, free=%d\n", malloc_count, free_count);
    int malloc_before = malloc_count;
    int free_before = free_count;

    for (int i = 0; i < 100; i++) {
        kbody_t body;
        const char *json = "{\"key\":\"value\"}";

        kbody_parse("application/json", json, strlen(json), &body);
        kbody_clear(&body);
    }

    printf("After: malloc=%d, free=%d\n", malloc_count, free_count);
    printf("Difference: malloc_calls=%d, free_calls=%d\n",
           malloc_count - malloc_before,
           free_count - free_before);

    if (malloc_count - malloc_before == free_count - free_before) {
        printf("✅ NO MEMORY LEAK DETECTED\n");
    } else {
        printf("❌ POSSIBLE MEMORY LEAK\n");
    }
}

int main(void) {
    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("           Memory Leak Detection Test\n");
    printf("════════════════════════════════════════════════════════════════\n");

    test_single_form_parse();
    test_multiple_parses();
    test_json_parses();

    printf("\n");
    printf("════════════════════════════════════════════════════════════════\n");
    printf("Summary:\n");
    printf("  Total malloc calls: %d\n", malloc_count);
    printf("  Total free calls:   %d\n", free_count);
    printf("  Total allocated:    %ld bytes\n", total_allocated);
    printf("  Total freed:        %ld bytes\n", total_freed);

    if (malloc_count == free_count && total_allocated >= total_freed) {
        printf("\n✅ Memory management appears correct\n");
    } else {
        printf("\n⚠️  Warning: Check malloc/free balance\n");
    }
    printf("════════════════════════════════════════════════════════════════\n\n");

    return 0;
}
EOF

