#include "kconnect.h"
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <unistd.h>
kconnect_t* kconnect_create(const char *host, int port) {
    kconnect_t *c = malloc(sizeof(*c));
    if (!c) return NULL;
    struct hostent *h = gethostbyname(host);
    if (!h) { free(c); return NULL; }
    c->fd = socket(AF_INET, SOCK_STREAM, 0);
    if (c->fd < 0) { free(c); return NULL; }
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    memcpy(&addr.sin_addr, h->h_addr, h->h_length);
    if (connect(c->fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(c->fd); free(c); return NULL;
    }
    return c;
}
void kconnect_close(kconnect_t *conn) {
    if (conn) { close(conn->fd); free(conn); }
}
int kconnect_send(kconnect_t *conn, const void *data, int len) {
    if (!conn || !data) return -1;
    return send(conn->fd, data, len, 0);
}
int kconnect_recv(kconnect_t *conn, void *buffer, int size) {
    if (!conn || !buffer) return -1;
    return recv(conn->fd, buffer, size, 0);
}
int kconnect_fd(kconnect_t *conn) {
    return conn ? conn->fd : -1;
}

