/*
 * Kim FS-Extra (kfs.c)
 *
 * 파일 시스템 유틸리티 구현
 */

#define _GNU_SOURCE
#include "kfs.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

/* ============================================
   파일 정보
   ============================================ */

bool kfs_exists(const char *path) {
    if (!path) return false;
    return access(path, F_OK) == 0;
}

bool kfs_is_file(const char *path) {
    if (!path) return false;

    struct stat st;
    if (stat(path, &st) != 0) return false;
    return S_ISREG(st.st_mode);
}

bool kfs_is_dir(const char *path) {
    if (!path) return false;

    struct stat st;
    if (stat(path, &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

long kfs_size(const char *path) {
    if (!path) return -1;

    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

long kfs_mtime(const char *path) {
    if (!path) return -1;

    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_mtime;
}

/* ============================================
   파일 읽기/쓰기
   ============================================ */

