/*
 * Kim FS-Extra (kfs.c)
 *
 * 파일 시스템 유틸리티 구현
 */

#define _GNU_SOURCE
#include "kfs.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

/* ============================================
   파일 정보
   ============================================ */

bool kfs_exists(const char *path) {
    if (!path) return false;
    return access(path, F_OK) == 0;
}

bool kfs_is_file(const char *path) {
    if (!path) return false;

    struct stat st;
    if (stat(path, &st) != 0) return false;
    return S_ISREG(st.st_mode);
}

bool kfs_is_dir(const char *path) {
    if (!path) return false;

    struct stat st;
    if (stat(path, &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

long kfs_size(const char *path) {
    if (!path) return -1;

    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

long kfs_mtime(const char *path) {
    if (!path) return -1;

    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_mtime;
}

/* ============================================
   파일 읽기/쓰기
   ============================================ */

char* kfs_read_file(const char *path) {
    if (!path) return NULL;

    FILE *f = fopen(path, "r");
    if (!f) return NULL;

    // 파일 크기 계산
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *content = (char *)malloc(size + 1);
    if (!content) {
        fclose(f);
        return NULL;
    }

    size_t read = fread(content, 1, size, f);
    content[read] = '\0';

    fclose(f);
    return content;
}

bool kfs_write_file(const char *path, const char *content) {
    if (!path || !content) return false;

    FILE *f = fopen(path, "w");
    if (!f) return false;

    size_t written = fwrite(content, 1, strlen(content), f);
    fclose(f);

    return written == strlen(content);
}

bool kfs_append_file(const char *path, const char *content) {
    if (!path || !content) return false;

    FILE *f = fopen(path, "a");
    if (!f) return false;

    size_t written = fwrite(content, 1, strlen(content), f);
    fclose(f);

    return written == strlen(content);
}

char* kfs_read_json(const char *path) {
    return kfs_read_file(path);
}

bool kfs_write_json(const char *path, const char *json) {
    return kfs_write_file(path, json);
}

/* ============================================
   파일 조작
   ============================================ */

bool kfs_copy_file(const char *src, const char *dest) {
    if (!src || !dest) return false;

    FILE *source = fopen(src, "rb");
    if (!source) return false;

    FILE *destination = fopen(dest, "wb");
    if (!destination) {
        fclose(source);
        return false;
    }

    char buffer[4096];
    size_t bytes;
    while ((bytes = fread(buffer, 1, sizeof(buffer), source)) > 0) {
        fwrite(buffer, 1, bytes, destination);
    }

    fclose(source);
    fclose(destination);
    return true;
}

bool kfs_move_file(const char *src, const char *dest) {
    if (!src || !dest) return false;
    return rename(src, dest) == 0;
}

bool kfs_remove_file(const char *path) {
    if (!path) return false;
    return unlink(path) == 0;
}

bool kfs_create_file(const char *path) {
    if (!path) return false;

    FILE *f = fopen(path, "a");
    if (f) {
        fclose(f);
        return true;
    }
    return false;
}

/* ============================================
   디렉토리 조작
   ============================================ */

bool kfs_ensure_dir(const char *path) {
    if (!path) return false;

    if (kfs_is_dir(path)) return true;

    return mkdir(path, 0755) == 0;
}

bool kfs_mkdir_p(const char *path) {
    if (!path) return false;

    char temp[1024];
    strncpy(temp, path, sizeof(temp) - 1);

    for (char *p = temp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            if (!kfs_is_dir(temp)) {
                mkdir(temp, 0755);
            }
            *p = '/';
        }
    }

    return kfs_ensure_dir(temp);
}

bool kfs_copy_dir(const char *src, const char *dest) {
    if (!src || !dest) return false;

    kfs_mkdir_p(dest);

    DIR *d = opendir(src);
    if (!d) return false;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char src_path[1024], dest_path[1024];
        snprintf(src_path, sizeof(src_path), "%s/%s", src, entry->d_name);
        snprintf(dest_path, sizeof(dest_path), "%s/%s", dest, entry->d_name);

        if (kfs_is_dir(src_path)) {
            kfs_copy_dir(src_path, dest_path);
        } else {
            kfs_copy_file(src_path, dest_path);
        }
    }

    closedir(d);
    return true;
}

bool kfs_remove_dir(const char *path) {
    if (!path) return false;

    DIR *d = opendir(path);
    if (!d) return false;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        if (kfs_is_dir(full_path)) {
            kfs_remove_dir(full_path);
        } else {
            kfs_remove_file(full_path);
        }
    }

    closedir(d);
    return rmdir(path) == 0;
}

bool kfs_empty_dir(const char *path) {
    if (!path) return false;

    DIR *d = opendir(path);
    if (!d) return false;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        if (kfs_is_file(full_path)) {
            kfs_remove_file(full_path);
        }
    }

    closedir(d);
    return true;
}

char* kfs_cwd(void) {
    char *result = (char *)malloc(1024);
    if (!result) return NULL;

    if (getcwd(result, 1024) == NULL) {
        free(result);
        return NULL;
    }

    return result;
}

bool kfs_chmod(const char *path, int mode) {
    if (!path) return false;
    return chmod(path, mode) == 0;
}

char* kfs_resolve(const char *path) {
    if (!path) return NULL;

    char *result = (char *)malloc(1024);
    if (!result) return NULL;

    if (realpath(path, result) == NULL) {
        free(result);
        return NULL;
    }

    return result;
}

/* ============================================
   유틸리티
   ============================================ */

char* kfs_basename(const char *path) {
    if (!path) return NULL;

    const char *last_slash = strrchr(path, '/');
    if (!last_slash) return (char *)path;

    return (char *)last_slash + 1;
}

char* kfs_dirname(const char *path) {
    if (!path) return NULL;

    char *result = (char *)malloc(1024);
    if (!result) return NULL;

    strncpy(result, path, 1023);

    char *last_slash = strrchr(result, '/');
    if (last_slash) {
        if (last_slash == result) {
            last_slash[1] = '\0';
        } else {
            last_slash[0] = '\0';
        }
    } else {
        strcpy(result, ".");
    }

    return result;
}

char* kfs_extname(const char *path) {
    if (!path) return NULL;

    const char *last_dot = strrchr(path, '.');
    const char *last_slash = strrchr(path, '/');

    if (!last_dot || (last_slash && last_dot < last_slash)) {
        char *result = (char *)malloc(1);
        if (result) *result = '\0';
        return result;
    }

    char *result = (char *)malloc(strlen(last_dot) + 1);
    if (result) strcpy(result, last_dot);

    return result;
}

char* kfs_join(const char *path1, const char *path2) {
    if (!path1 || !path2) return NULL;

    char *result = (char *)malloc(2048);
    if (!result) return NULL;

    snprintf(result, 2048, "%s/%s", path1, path2);
    return result;
}

char* kfs_normalize(const char *path) {
    if (!path) return NULL;

    char *result = (char *)malloc(1024);
    if (!result) return NULL;

    strncpy(result, path, 1023);

    // 간단한 정규화: ../ 및 ./ 제거
    char *p = result;
    while ((p = strstr(p, "/./")) != NULL) {
        memmove(p, p + 2, strlen(p + 2) + 1);
    }

    return result;
}

/*
 * Kim FS-Extra (kfs.h)
