/*
 * Kim Knex (kknex.c)
 *
 * SQL 쿼리 빌더 구현
 */

#define _GNU_SOURCE
#include "kknex.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

kknex_query_t* kknex_new(void) {
    kknex_query_t *q = (kknex_query_t *)malloc(sizeof(kknex_query_t));
    if (!q) return NULL;

    memset(q, 0, sizeof(kknex_query_t));
    q->limit_val = -1;
    q->offset_val = 0;

    return q;
}

void kknex_free(kknex_query_t *q) {
    if (q) free(q);
}

kknex_query_t* kknex_table(kknex_query_t *q, const char *table) {
    if (!q || !table) return q;
    strncpy(q->table, table, sizeof(q->table) - 1);
    return q;
}

kknex_query_t* kknex_select(kknex_query_t *q, const char *columns) {
    if (!q || !columns) return q;
    strncpy(q->select_columns, columns, sizeof(q->select_columns) - 1);
    return q;
}

kknex_query_t* kknex_where(kknex_query_t *q, const char *condition) {
    if (!q || !condition) return q;
    strcpy(q->where_clause, condition);
    return q;
}

kknex_query_t* kknex_and_where(kknex_query_t *q, const char *condition) {
    if (!q || !condition) return q;
    if (q->where_clause[0] != '\0') {
        strcat(q->where_clause, " AND ");
    }
    strcat(q->where_clause, condition);
    return q;
}

kknex_query_t* kknex_or_where(kknex_query_t *q, const char *condition) {
    if (!q || !condition) return q;
    if (q->where_clause[0] != '\0') {
        strcat(q->where_clause, " OR ");
    }
    strcat(q->where_clause, condition);
    return q;
}

kknex_query_t* kknex_bind(kknex_query_t *q, const char *value) {
    if (!q || !value || q->param_count >= 1024) return q;
    strncpy(q->params[q->param_count], value, sizeof(q->params[0]) - 1);
    q->param_count++;
    return q;
}

kknex_query_t* kknex_join(kknex_query_t *q, const char *table, const char *condition) {
    if (!q || !table || !condition) return q;
    sprintf(q->join_clause + strlen(q->join_clause), "INNER JOIN %s ON %s ", table, condition);
    return q;
}

kknex_query_t* kknex_left_join(kknex_query_t *q, const char *table, const char *condition) {
    if (!q || !table || !condition) return q;
    sprintf(q->join_clause + strlen(q->join_clause), "LEFT JOIN %s ON %s ", table, condition);
    return q;
}

kknex_query_t* kknex_group_by(kknex_query_t *q, const char *columns) {
    if (!q || !columns) return q;
    strcpy(q->group_by, columns);
    return q;
}

kknex_query_t* kknex_order_by(kknex_query_t *q, const char *column, const char *direction) {
    if (!q || !column) return q;
    sprintf(q->order_by, "%s %s", column, direction ? direction : "ASC");
    return q;
}

kknex_query_t* kknex_limit(kknex_query_t *q, int limit) {
    if (!q) return q;
    q->limit_val = limit;
    return q;
}

kknex_query_t* kknex_offset(kknex_query_t *q, int offset) {
    if (!q) return q;
    q->offset_val = offset;
    return q;
}

char* kknex_to_select(kknex_query_t *q) {
    if (!q || q->table[0] == '\0') return NULL;

    char *result = (char *)malloc(4096);
    int pos = 0;

    pos += sprintf(result, "SELECT %s FROM %s",
                   q->select_columns[0] != '\0' ? q->select_columns : "*",
                   q->table);

    if (q->join_clause[0] != '\0') {
        pos += sprintf(result + pos, " %s", q->join_clause);
    }

    if (q->where_clause[0] != '\0') {
        pos += sprintf(result + pos, " WHERE %s", q->where_clause);
    }

    if (q->group_by[0] != '\0') {
        pos += sprintf(result + pos, " GROUP BY %s", q->group_by);
    }

    if (q->order_by[0] != '\0') {
        pos += sprintf(result + pos, " ORDER BY %s", q->order_by);
    }

    if (q->limit_val > 0) {
        pos += sprintf(result + pos, " LIMIT %d", q->limit_val);
    }

    if (q->offset_val > 0) {
        pos += sprintf(result + pos, " OFFSET %d", q->offset_val);
    }

    return result;
}

char* kknex_insert(kknex_query_t *q, const char *columns, const char *values) {
    if (!q || !columns || !values) return NULL;

    char *result = (char *)malloc(1024);
    sprintf(result, "INSERT INTO %s (%s) VALUES (%s)", q->table, columns, values);

    return result;
}

char* kknex_update(kknex_query_t *q, const char *set_clause) {
    if (!q || !set_clause) return NULL;

    char *result = (char *)malloc(1024);
    sprintf(result, "UPDATE %s SET %s", q->table, set_clause);

    if (q->where_clause[0] != '\0') {
        strcat(result, " WHERE ");
        strcat(result, q->where_clause);
    }

    return result;
}

char* kknex_delete(kknex_query_t *q) {
    if (!q) return NULL;

    char *result = (char *)malloc(1024);
    sprintf(result, "DELETE FROM %s", q->table);

    if (q->where_clause[0] != '\0') {
        strcat(result, " WHERE ");
        strcat(result, q->where_clause);
    }

    return result;
}

char* kknex_to_string(kknex_query_t *q) {
    if (!q) return NULL;
    return kknex_to_select(q);
}

