/*
 * Kim Chalk (kchalk.h)
 *
 * 터미널 컬러 라이브러리
 * - 전경색/배경색 지원
 * - 텍스트 스타일 (굵게, 이탤릭, 밑줄)
 * - 256색 지원
 */

#ifndef KCHALK_H
#define KCHALK_H

#include <stdbool.h>

/* ============================================
   컬러 정의
   ============================================ */

typedef enum {
    KCHALK_BLACK = 30,
    KCHALK_RED = 31,
    KCHALK_GREEN = 32,
    KCHALK_YELLOW = 33,
    KCHALK_BLUE = 34,
    KCHALK_MAGENTA = 35,
    KCHALK_CYAN = 36,
    KCHALK_WHITE = 37,
    KCHALK_GRAY = 90,
    KCHALK_DEFAULT = 39
} kchalk_color_t;

typedef enum {
    KCHALK_BG_BLACK = 40,
    KCHALK_BG_RED = 41,
    KCHALK_BG_GREEN = 42,
    KCHALK_BG_YELLOW = 43,
    KCHALK_BG_BLUE = 44,
    KCHALK_BG_MAGENTA = 45,
    KCHALK_BG_CYAN = 46,
    KCHALK_BG_WHITE = 47,
    KCHALK_BG_DEFAULT = 49
} kchalk_bg_color_t;

typedef enum {
    KCHALK_RESET = 0,
    KCHALK_BOLD = 1,
    KCHALK_DIM = 2,
    KCHALK_ITALIC = 3,
    KCHALK_UNDERLINE = 4,
    KCHALK_BLINK = 5,
    KCHALK_REVERSE = 7,
    KCHALK_HIDDEN = 8,
    KCHALK_STRIKETHROUGH = 9
} kchalk_style_t;

typedef struct {
    char buffer[1024];
    int pos;
    kchalk_color_t color;
    kchalk_bg_color_t bg_color;
    kchalk_style_t *styles;
    int style_count;
    int style_capacity;
    bool enabled;
} kchalk_t;

/* ============================================
   생성 및 정리
   ============================================ */

/**
 * Chalk 인스턴스 생성
 */
kchalk_t* kchalk_new(void);

/**
 * Chalk 정리
 */
void kchalk_free(kchalk_t *chalk);

/* ============================================
   스타일 적용
   ============================================ */

/**
 * 전경색 설정
 */
kchalk_t* kchalk_color(kchalk_t *chalk, kchalk_color_t color);

/**
 * 배경색 설정
 */
kchalk_t* kchalk_bg_color(kchalk_t *chalk, kchalk_bg_color_t bg_color);

/**
 * 텍스트 스타일 추가
 */
kchalk_t* kchalk_style(kchalk_t *chalk, kchalk_style_t style);

/**
 * 굵게
 */
