/*
 * Kim Chalk (kchalk.c)
 *
 * 터미널 컬러 구현
 */

#define _GNU_SOURCE
#include "kchalk.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ============================================
   생성 및 정리
   ============================================ */

kchalk_t* kchalk_new(void) {
    kchalk_t *chalk = (kchalk_t *)malloc(sizeof(kchalk_t));
    if (!chalk) return NULL;

    memset(chalk, 0, sizeof(kchalk_t));
    chalk->color = KCHALK_DEFAULT;
    chalk->bg_color = KCHALK_BG_DEFAULT;
    chalk->style_capacity = 5;
    chalk->styles = (kchalk_style_t *)malloc(chalk->style_capacity * sizeof(kchalk_style_t));
    chalk->enabled = true;

    return chalk;
}

void kchalk_free(kchalk_t *chalk) {
    if (!chalk) return;
    if (chalk->styles) free(chalk->styles);
    free(chalk);
}

/* ============================================
   스타일 적용
   ============================================ */

kchalk_t* kchalk_color(kchalk_t *chalk, kchalk_color_t color) {
    if (!chalk) return NULL;
    chalk->color = color;
    return chalk;
}

kchalk_t* kchalk_bg_color(kchalk_t *chalk, kchalk_bg_color_t bg_color) {
    if (!chalk) return NULL;
    chalk->bg_color = bg_color;
    return chalk;
}

kchalk_t* kchalk_style(kchalk_t *chalk, kchalk_style_t style) {
    if (!chalk) return NULL;

    if (chalk->style_count >= chalk->style_capacity) {
        chalk->style_capacity *= 2;
        chalk->styles = (kchalk_style_t *)realloc(chalk->styles,
                        chalk->style_capacity * sizeof(kchalk_style_t));
    }

    chalk->styles[chalk->style_count] = style;
    chalk->style_count++;
    return chalk;
}

kchalk_t* kchalk_bold(kchalk_t *chalk) {
    return kchalk_style(chalk, KCHALK_BOLD);
}

kchalk_t* kchalk_dim(kchalk_t *chalk) {
    return kchalk_style(chalk, KCHALK_DIM);
}

kchalk_t* kchalk_italic(kchalk_t *chalk) {
    return kchalk_style(chalk, KCHALK_ITALIC);
}

kchalk_t* kchalk_underline(kchalk_t *chalk) {
    return kchalk_style(chalk, KCHALK_UNDERLINE);
}

kchalk_t* kchalk_reverse(kchalk_t *chalk) {
    return kchalk_style(chalk, KCHALK_REVERSE);
}

/* ============================================
   출력
   ============================================ */

char* kchalk_apply(kchalk_t *chalk, const char *text) {
    if (!chalk || !text) return NULL;

    char *result = (char *)malloc(2048);
    if (!result) return NULL;

    int pos = 0;

    if (chalk->enabled) {
        // ANSI 이스케이프 시퀀스 시작
        pos += sprintf(result + pos, "\033[");

        // 스타일 추가
        for (int i = 0; i < chalk->style_count; i++) {
            if (i > 0) pos += sprintf(result + pos, ";");
            pos += sprintf(result + pos, "%d", chalk->styles[i]);
        }

        // 색상 추가
        if (chalk->color != KCHALK_DEFAULT) {
            if (chalk->style_count > 0) pos += sprintf(result + pos, ";");
            pos += sprintf(result + pos, "%d", chalk->color);
        }

        // 배경색 추가
        if (chalk->bg_color != KCHALK_BG_DEFAULT) {
            if (chalk->style_count > 0 || chalk->color != KCHALK_DEFAULT) {
                pos += sprintf(result + pos, ";");
            }
            pos += sprintf(result + pos, "%d", chalk->bg_color);
        }

        pos += sprintf(result + pos, "m");
    }

    // 텍스트 추가
    pos += sprintf(result + pos, "%s", text);

    // 리셋 코드 추가
    if (chalk->enabled) {
        pos += sprintf(result + pos, "\033[0m");
    }

    return result;
}

void kchalk_print(kchalk_t *chalk, const char *text) {
    if (!chalk || !text) return;

    char *styled = kchalk_apply(chalk, text);
    if (styled) {
        printf("%s\n", styled);
        free(styled);
    }
}

kchalk_t* kchalk_reset(kchalk_t *chalk) {
    if (!chalk) return NULL;

    chalk->color = KCHALK_DEFAULT;
    chalk->bg_color = KCHALK_BG_DEFAULT;
    chalk->style_count = 0;

    return chalk;
}

void kchalk_enable(kchalk_t *chalk, bool enabled) {
    if (chalk) {
        chalk->enabled = enabled;
    }
}

/* ============================================
   편의 함수
   ============================================ */

char* kchalk_red(const char *text) {
    if (!text) return NULL;

    kchalk_t *chalk = kchalk_new();
    kchalk_color(chalk, KCHALK_RED);
    char *result = kchalk_apply(chalk, text);
    kchalk_free(chalk);

    return result;
}

char* kchalk_green(const char *text) {
    if (!text) return NULL;

    kchalk_t *chalk = kchalk_new();
    kchalk_color(chalk, KCHALK_GREEN);
    char *result = kchalk_apply(chalk, text);
    kchalk_free(chalk);

    return result;
}

char* kchalk_yellow(const char *text) {
    if (!text) return NULL;

    kchalk_t *chalk = kchalk_new();
    kchalk_color(chalk, KCHALK_YELLOW);
    char *result = kchalk_apply(chalk, text);
    kchalk_free(chalk);

    return result;
}

char* kchalk_blue(const char *text) {
    if (!text) return NULL;

    kchalk_t *chalk = kchalk_new();
    kchalk_color(chalk, KCHALK_BLUE);
    char *result = kchalk_apply(chalk, text);
    kchalk_free(chalk);

    return result;
}

char* kchalk_gray(const char *text) {
    if (!text) return NULL;

    kchalk_t *chalk = kchalk_new();
    kchalk_color(chalk, KCHALK_GRAY);
    char *result = kchalk_apply(chalk, text);
    kchalk_free(chalk);

    return result;
}

