kasync_error_t* kasync_error_new(int code, const char *message) {
    kasync_error_t *err = (kasync_error_t *)malloc(sizeof(kasync_error_t));
    if (!err) return NULL;

    err->code = code;
    if (message) {
        strncpy(err->message, message, sizeof(err->message) - 1);
    } else {
        err->message[0] = '\0';
    }

    return err;
}

void kasync_error_free(kasync_error_t *err) {
    if (err) free(err);
}

/* ============================================
   시리즈 (순차 실행)
   ============================================ */

typedef struct {
    kasync_task_fn *tasks;
    int count;
    int current;
    int total_errors;
    kasync_final_fn final_callback;
} kasync_series_ctx_t;

static void kasync_series_next(kasync_series_ctx_t *ctx, void *err, void *result) {
    if (err) {
        ctx->total_errors++;
    }

    ctx->current++;

    if (ctx->current >= ctx->count) {
        if (ctx->final_callback) {
            if (ctx->total_errors > 0) {
                kasync_error_t *error = kasync_error_new(1, "Series failed");
                ctx->final_callback(error);
                free(error);
            } else {
                ctx->final_callback(NULL);
            }
        }
        free(ctx);
        return;
    }

    // 다음 작업 실행
    kasync_callback_fn callback = (kasync_callback_fn)kasync_series_next;
    ctx->tasks[ctx->current](callback);
}

void kasync_series(kasync_task_fn *tasks, int count, kasync_final_fn final) {
    if (!tasks || count <= 0) return;

    kasync_series_ctx_t *ctx = (kasync_series_ctx_t *)malloc(sizeof(kasync_series_ctx_t));
    ctx->tasks = tasks;
    ctx->count = count;
    ctx->current = 0;
    ctx->total_errors = 0;
    ctx->final_callback = final;

    // 첫 작업 시작
    kasync_callback_fn callback = (kasync_callback_fn)kasync_series_next;
    tasks[0](callback);
}

