            }
        }
        free(ctx);
    }
}

void kasync_parallel(kasync_task_fn *tasks, int count, int limit, kasync_final_fn final) {
    if (!tasks || count <= 0) return;

    kasync_parallel_ctx_t *ctx = (kasync_parallel_ctx_t *)malloc(sizeof(kasync_parallel_ctx_t));
    ctx->tasks = tasks;
