    // 다음 작업 실행 (데이터 전달)
    kasync_callback_fn callback = (kasync_callback_fn)kasync_waterfall_next;
    ctx->tasks[ctx->current](ctx->data, callback);
}

void kasync_waterfall(void *initial_data, kasync_iterator_fn *tasks, int count, kasync_final_fn final) {
