} kasync_map_ctx_t;

static void kasync_map_item_complete(kasync_map_ctx_t *ctx, int index, void *err, void *result) {
    if (!err && result) {
        ctx->results[index] = result;
    }

    ctx->completed++;

    if (ctx->completed >= ctx->count) {
        if (ctx->final_callback) {
            ctx->final_callback(NULL);
        }
        free(ctx->results);
        free(ctx);
    }
}

void kasync_map(void **items, int count, kasync_iterator_fn fn, kasync_final_fn final) {
    if (!items || !fn || count <= 0) return;

    kasync_map_ctx_t *ctx = (kasync_map_ctx_t *)malloc(sizeof(kasync_map_ctx_t));
    ctx->items = items;
