/*
 * Kim Lodash (klodash.h)
 *
 * 배열/객체 유틸리티 라이브러리
 * - 배열 조작 (map, filter, reduce, forEach, etc)
 * - 객체 조작 (merge, keys, values, etc)
 * - 문자열 처리
 * - 수학 연산
 *
 * JavaScript의 lodash를 Pure C로 구현
 */

#ifndef KLODASH_H
#define KLODASH_H

#include <stdbool.h>
#include <stddef.h>

/* ============================================
   배열 구조체
   ============================================ */

typedef struct {
    void **items;
    int count;
    int capacity;
    void (*free_fn)(void *);  // 각 항목 해제 함수
} klodash_array_t;

/* ============================================
   객체 (key-value) 구조체
   ============================================ */

typedef struct {
    char *key;
    void *value;
} klodash_pair_t;

typedef struct {
    klodash_pair_t *pairs;
    int count;
    int capacity;
} klodash_object_t;

/* ============================================
   콜백 함수 타입
   ============================================ */

typedef void (*klodash_each_fn)(void *item, int index);
typedef void* (*klodash_map_fn)(void *item, int index);
typedef bool (*klodash_filter_fn)(void *item, int index);
typedef void (*klodash_reduce_fn)(void *accumulator, void *item, int index);

/* ============================================
   배열 함수
   ============================================ */

/**
 * 새 배열 생성
 */
klodash_array_t* klodash_array_new(void (*free_fn)(void *));

/**
 * 배열 해제
 */
void klodash_array_free(klodash_array_t *arr);

/**
 * 배열 추가
 */
void klodash_array_push(klodash_array_t *arr, void *item);

/**
 * 배열 마지막 항목 제거 및 반환
 */
void* klodash_array_pop(klodash_array_t *arr);

/**
 * 배열 첫 항목 제거 및 반환
 */
void* klodash_array_shift(klodash_array_t *arr);

/**
 * 배열 첫 항목 추가
 */
void klodash_array_unshift(klodash_array_t *arr, void *item);

/**
 * 배열 특정 인덱스 항목 조회
 */
void* klodash_array_get(klodash_array_t *arr, int index);

/**
 * 배열 특정 인덱스 항목 설정
 */
void klodash_array_set(klodash_array_t *arr, int index, void *item);

/**
 * 배열 길이
 */
int klodash_array_length(klodash_array_t *arr);

/**
 * 각 항목에 대해 함수 실행
 */
void klodash_array_each(klodash_array_t *arr, klodash_each_fn fn);

/**
 * 배열 필터링
 */
klodash_array_t* klodash_array_filter(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 항목 찾기
 */
void* klodash_array_find(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 항목 인덱스 찾기
 */
int klodash_array_find_index(klodash_array_t *arr, klodash_filter_fn fn);

/**
 * 배열 포함 여부 (포인터 비교)
 */
bool klodash_array_includes(klodash_array_t *arr, void *item);

/**
 * 배열 역순
 */
void klodash_array_reverse(klodash_array_t *arr);

/**
 * 배열 자르기 (slice)
 */
klodash_array_t* klodash_array_slice(klodash_array_t *arr, int start, int end);

/**
 * 배열 정렬 (비교 함수 제공)
 */
void klodash_array_sort(klodash_array_t *arr, int (*compare_fn)(const void *, const void *));

/**
 * 배열 병합 (새 배열)
 */
klodash_array_t* klodash_array_concat(klodash_array_t *arr1, klodash_array_t *arr2);

/* ============================================
   객체 함수
   ============================================ */

/**
 * 새 객체 생성
 */
klodash_object_t* klodash_object_new(void);

/**
 * 객체 해제
 */
void klodash_object_free(klodash_object_t *obj);

/**
 * 객체에 키-값 추가
 */
void klodash_object_set(klodash_object_t *obj, const char *key, void *value);

/**
 * 객체에서 키-값 조회
 */
void* klodash_object_get(klodash_object_t *obj, const char *key);

/**
 * 객체 키 존재 여부
 */
bool klodash_object_has(klodash_object_t *obj, const char *key);

/**
 * 객체 키 삭제
 */
void klodash_object_delete(klodash_object_t *obj, const char *key);

/**
 * 객체 키 배열 반환
 */
klodash_array_t* klodash_object_keys(klodash_object_t *obj);

/**
 * 객체 값 배열 반환
 */
klodash_array_t* klodash_object_values(klodash_object_t *obj);

/**
 * 객체 크기
 */
int klodash_object_size(klodash_object_t *obj);

/**
 * 객체 병합
 */
void klodash_object_merge(klodash_object_t *target, klodash_object_t *source);

/**
 * 객체 복사
 */
klodash_object_t* klodash_object_clone(klodash_object_t *obj);

/* ============================================
   문자열 함수
   ============================================ */

/**
 * 문자열 합치기
 */
char* klodash_string_concat(const char *s1, const char *s2);

/**
 * 문자열 포함 여부
 */
bool klodash_string_includes(const char *str, const char *substring);

/**
 * 문자열 시작 확인
 */
bool klodash_string_starts_with(const char *str, const char *prefix);

/**
 * 문자열 끝 확인
 */
bool klodash_string_ends_with(const char *str, const char *suffix);

/**
 * 문자열 반복
 */
char* klodash_string_repeat(const char *str, int count);

/**
 * 문자열 공백 제거
 */
char* klodash_string_trim(const char *str);

/**
 * 문자열 소문자 변환
 */
char* klodash_string_lower_case(const char *str);

/**
 * 문자열 대문자 변환
 */
char* klodash_string_upper_case(const char *str);

/**
 * 문자열 뒤집기
 */
char* klodash_string_reverse(const char *str);

/* ============================================
   수학 함수
   ============================================ */

/**
 * 최대값
 */
int klodash_math_max(const int *nums, int count);

/**
 * 최소값
 */
int klodash_math_min(const int *nums, int count);

/**
 * 합계
 */
int klodash_math_sum(const int *nums, int count);

/**
 * 평균
 */
double klodash_math_avg(const int *nums, int count);

/**
 * 범위 생성
 */
klodash_array_t* klodash_math_range(int start, int end, int step);

#endif // KLODASH_H

