/*
 * Kim Lodash (klodash.c)
 *
 * 배열/객체 유틸리티 구현
 */

#define _GNU_SOURCE
#include "klodash.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>

/* ============================================
   배열 구현
   ============================================ */

klodash_array_t* klodash_array_new(void (*free_fn)(void *)) {
    klodash_array_t *arr = (klodash_array_t *)malloc(sizeof(klodash_array_t));
    if (!arr) return NULL;

    arr->capacity = 10;
    arr->count = 0;
    arr->items = (void **)malloc(arr->capacity * sizeof(void *));
    arr->free_fn = free_fn;

    return arr;
}

void klodash_array_free(klodash_array_t *arr) {
    if (!arr) return;

    if (arr->free_fn) {
        for (int i = 0; i < arr->count; i++) {
            arr->free_fn(arr->items[i]);
        }
    }

    free(arr->items);
    free(arr);
}

void klodash_array_push(klodash_array_t *arr, void *item) {
    if (!arr) return;

    if (arr->count >= arr->capacity) {
        arr->capacity *= 2;
        arr->items = (void **)realloc(arr->items, arr->capacity * sizeof(void *));
    }

    arr->items[arr->count++] = item;
}

void* klodash_array_pop(klodash_array_t *arr) {
    if (!arr || arr->count == 0) return NULL;
    return arr->items[--arr->count];
}

void* klodash_array_shift(klodash_array_t *arr) {
    if (!arr || arr->count == 0) return NULL;

    void *first = arr->items[0];
    for (int i = 0; i < arr->count - 1; i++) {
        arr->items[i] = arr->items[i + 1];
    }
    arr->count--;

    return first;
}

void klodash_array_unshift(klodash_array_t *arr, void *item) {
    if (!arr) return;

    if (arr->count >= arr->capacity) {
        arr->capacity *= 2;
        arr->items = (void **)realloc(arr->items, arr->capacity * sizeof(void *));
    }

    for (int i = arr->count; i > 0; i--) {
        arr->items[i] = arr->items[i - 1];
    }
    arr->items[0] = item;
    arr->count++;
}

void* klodash_array_get(klodash_array_t *arr, int index) {
    if (!arr || index < 0 || index >= arr->count) return NULL;
    return arr->items[index];
}

void klodash_array_set(klodash_array_t *arr, int index, void *item) {
    if (!arr || index < 0 || index >= arr->count) return;
    arr->items[index] = item;
}

int klodash_array_length(klodash_array_t *arr) {
    if (!arr) return 0;
    return arr->count;
}

