klodash_array_t* klodash_array_filter(klodash_array_t *arr, klodash_filter_fn fn) {
    if (!arr || !fn) return NULL;

    klodash_array_t *filtered = klodash_array_new(arr->free_fn);
    if (!filtered) return NULL;

    for (int i = 0; i < arr->count; i++) {
        if (fn(arr->items[i], i)) {
            klodash_array_push(filtered, arr->items[i]);
        }
    }

    return filtered;
}

void* klodash_array_find(klodash_array_t *arr, klodash_filter_fn fn) {
    if (!arr || !fn) return NULL;

    for (int i = 0; i < arr->count; i++) {
        if (fn(arr->items[i], i)) {
            return arr->items[i];
        }
    }

    return NULL;
}

int klodash_array_find_index(klodash_array_t *arr, klodash_filter_fn fn) {
    if (!arr || !fn) return -1;

    for (int i = 0; i < arr->count; i++) {
        if (fn(arr->items[i], i)) {
            return i;
        }
    }

    return -1;
}

bool klodash_array_includes(klodash_array_t *arr, void *item) {
    if (!arr) return false;

    for (int i = 0; i < arr->count; i++) {
        if (arr->items[i] == item) {
            return true;
        }
    }

    return false;
}

void klodash_array_reverse(klodash_array_t *arr) {
    if (!arr) return;

    for (int i = 0; i < arr->count / 2; i++) {
        void *tmp = arr->items[i];
        arr->items[i] = arr->items[arr->count - 1 - i];
        arr->items[arr->count - 1 - i] = tmp;
    }
}

klodash_array_t* klodash_array_slice(klodash_array_t *arr, int start, int end) {
    if (!arr) return NULL;

    if (start < 0) start = arr->count + start;
    if (end < 0) end = arr->count + end;

    if (start < 0) start = 0;
    if (end > arr->count) end = arr->count;
    if (start >= end) return klodash_array_new(arr->free_fn);

    klodash_array_t *sliced = klodash_array_new(arr->free_fn);
    for (int i = start; i < end; i++) {
        klodash_array_push(sliced, arr->items[i]);
    }

    return sliced;
}

void klodash_array_sort(klodash_array_t *arr, int (*compare_fn)(const void *, const void *)) {
