klodash_object_t* klodash_object_new(void) {
    klodash_object_t *obj = (klodash_object_t *)malloc(sizeof(klodash_object_t));
    if (!obj) return NULL;

    obj->capacity = 10;
    obj->count = 0;
    obj->pairs = (klodash_pair_t *)malloc(obj->capacity * sizeof(klodash_pair_t));

    return obj;
}

void klodash_object_free(klodash_object_t *obj) {
    if (!obj) return;

    for (int i = 0; i < obj->count; i++) {
        free(obj->pairs[i].key);
    }

    free(obj->pairs);
    free(obj);
}

void klodash_object_set(klodash_object_t *obj, const char *key, void *value) {
    if (!obj || !key) return;

    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->pairs[i].key, key) == 0) {
            obj->pairs[i].value = value;
            return;
        }
    }

    if (obj->count >= obj->capacity) {
        obj->capacity *= 2;
        obj->pairs = (klodash_pair_t *)realloc(obj->pairs, obj->capacity * sizeof(klodash_pair_t));
    }

    obj->pairs[obj->count].key = strdup(key);
    obj->pairs[obj->count].value = value;
    obj->count++;
}

void* klodash_object_get(klodash_object_t *obj, const char *key) {
    if (!obj || !key) return NULL;

    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->pairs[i].key, key) == 0) {
            return obj->pairs[i].value;
        }
    }

    return NULL;
}

bool klodash_object_has(klodash_object_t *obj, const char *key) {
    return klodash_object_get(obj, key) != NULL;
}

void klodash_object_delete(klodash_object_t *obj, const char *key) {
    if (!obj || !key) return;

    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->pairs[i].key, key) == 0) {
            free(obj->pairs[i].key);
            for (int j = i; j < obj->count - 1; j++) {
                obj->pairs[j] = obj->pairs[j + 1];
            }
            obj->count--;
            return;
        }
    }
}

int klodash_object_size(klodash_object_t *obj) {
    if (!obj) return 0;
    return obj->count;
}

void klodash_object_merge(klodash_object_t *target, klodash_object_t *source) {
    if (!target || !source) return;

    for (int i = 0; i < source->count; i++) {
        klodash_object_set(target, source->pairs[i].key, source->pairs[i].value);
    }
}

