char* klodash_string_concat(const char *s1, const char *s2) {
    if (!s1 || !s2) return NULL;

    int len1 = strlen(s1);
    int len2 = strlen(s2);
    char *result = (char *)malloc(len1 + len2 + 1);

    strcpy(result, s1);
    strcat(result, s2);

    return result;
}

bool klodash_string_includes(const char *str, const char *substring) {
    if (!str || !substring) return false;
    return strstr(str, substring) != NULL;
}

bool klodash_string_starts_with(const char *str, const char *prefix) {
    if (!str || !prefix) return false;
    return strncmp(str, prefix, strlen(prefix)) == 0;
}

bool klodash_string_ends_with(const char *str, const char *suffix) {
    if (!str || !suffix) return false;

    int str_len = strlen(str);
    int suffix_len = strlen(suffix);

    if (suffix_len > str_len) return false;

    return strcmp(str + str_len - suffix_len, suffix) == 0;
}

char* klodash_string_repeat(const char *str, int count) {
    if (!str || count <= 0) return NULL;

    int len = strlen(str);
    char *result = (char *)malloc(len * count + 1);
    result[0] = '\0';

    for (int i = 0; i < count; i++) {
        strcat(result, str);
    }

    return result;
}

char* klodash_string_trim(const char *str) {
    if (!str) return NULL;

    while (*str && isspace(*str)) str++;

    int len = strlen(str);
    while (len > 0 && isspace(str[len - 1])) len--;

    char *result = (char *)malloc(len + 1);
    strncpy(result, str, len);
    result[len] = '\0';

    return result;
}

char* klodash_string_lower_case(const char *str) {
    if (!str) return NULL;

    char *result = strdup(str);
    for (int i = 0; result[i]; i++) {
        result[i] = tolower(result[i]);
    }

    return result;
}

char* klodash_string_upper_case(const char *str) {
    if (!str) return NULL;

    char *result = strdup(str);
    for (int i = 0; result[i]; i++) {
        result[i] = toupper(result[i]);
    }

    return result;
}

char* klodash_string_reverse(const char *str) {
    if (!str) return NULL;

    int len = strlen(str);
    char *result = (char *)malloc(len + 1);

    for (int i = 0; i < len; i++) {
        result[i] = str[len - 1 - i];
    }
    result[len] = '\0';

    return result;
}

/* ============================================
   수학 함수
   ============================================ */

int klodash_math_max(const int *nums, int count) {
    if (!nums || count <= 0) return 0;

    int max = nums[0];
    for (int i = 1; i < count; i++) {
        if (nums[i] > max) max = nums[i];
    }

    return max;
}

int klodash_math_min(const int *nums, int count) {
    if (!nums || count <= 0) return 0;

    int min = nums[0];
    for (int i = 1; i < count; i++) {
        if (nums[i] < min) min = nums[i];
    }

    return min;
}

int klodash_math_sum(const int *nums, int count) {
    if (!nums || count <= 0) return 0;

    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += nums[i];
    }

    return sum;
}

double klodash_math_avg(const int *nums, int count) {
    if (!nums || count <= 0) return 0.0;
    return (double)klodash_math_sum(nums, count) / count;
}

klodash_array_t* klodash_math_range(int start, int end, int step) {
    if (step == 0) return NULL;

    klodash_array_t *arr = klodash_array_new(free);

    if (step > 0) {
        for (int i = start; i < end; i += step) {
            int *num = (int *)malloc(sizeof(int));
            *num = i;
            klodash_array_push(arr, num);
        }
    } else {
        for (int i = start; i > end; i += step) {
            int *num = (int *)malloc(sizeof(int));
            *num = i;
            klodash_array_push(arr, num);
        }
    }

    return arr;
}

