/*
 * Kim Moment (kmoment.h)
 *
 * 날짜/시간 처리 라이브러리
 * - 타임스탬프 생성 및 파싱
 * - 포맷 변환
 * - 시간 계산 (add, subtract, diff)
 * - 상대 시간 표현 (fromNow, toNow)
 *
 * JavaScript의 moment.js를 Pure C로 구현
 */

#ifndef KMOMENT_H
#define KMOMENT_H

#include <time.h>
#include <stdbool.h>

/* ============================================
   날짜/시간 구조체
   ============================================ */

typedef struct {
    time_t timestamp;
    struct tm tm;
} kmoment_t;

/* ============================================
   포맷 상수
   ============================================ */

#define KMOMENT_ISO_8601      "YYYY-MM-DDTHH:mm:ssZ"
#define KMOMENT_DATE_SHORT    "YYYY-MM-DD"
#define KMOMENT_TIME_SHORT    "HH:mm:ss"
#define KMOMENT_DATETIME      "YYYY-MM-DD HH:mm:ss"

/* ============================================
   생성 함수
   ============================================ */

/**
 * 현재 시간으로 moment 생성
 */
kmoment_t* kmoment_now(void);

/**
 * 타임스탬프로부터 moment 생성
 */
kmoment_t* kmoment_unix(time_t timestamp);

/**
 * 연, 월, 일, 시, 분, 초로부터 moment 생성
 */
kmoment_t* kmoment_date(int year, int month, int day, int hour, int minute, int second);

/**
 * moment 복사
 */
kmoment_t* kmoment_clone(kmoment_t *m);

/**
 * moment 해제
 */
void kmoment_free(kmoment_t *m);

/* ============================================
   파싱 함수
   ============================================ */

/**
 * 문자열 파싱 (포맷: "2025-01-22" 또는 "2025-01-22 10:30:45")
 */
kmoment_t* kmoment_parse(const char *str);

/**
 * Unix 시간 문자열 파싱
 */
kmoment_t* kmoment_parse_unix(const char *unix_str);

/* ============================================
   포맷 변환 함수
   ============================================ */

/**
 * 지정된 포맷으로 변환
 * 포맷 토큰: YYYY (년), MM (월), DD (일), HH (시), mm (분), ss (초)
 */
char* kmoment_format(kmoment_t *m, const char *format);

/**
 * ISO 8601 포맷
 */
char* kmoment_to_iso_string(kmoment_t *m);

/**
 * 일반 문자열 (예: "2025-01-22 10:30:45")
 */
char* kmoment_to_string(kmoment_t *m);

/**
 * Unix 타임스탬프 문자열
 */
char* kmoment_to_unix_string(kmoment_t *m);

/* ============================================
   시간 계산 함수
   ============================================ */

/**
 * 시간 추가
 */
kmoment_t* kmoment_add(kmoment_t *m, int value, const char *unit);

/**
 * 시간 빼기
 */
kmoment_t* kmoment_subtract(kmoment_t *m, int value, const char *unit);

/**
 * 일 수 추가 (편의 함수)
 */
kmoment_t* kmoment_add_days(kmoment_t *m, int days);

/**
 * 시간 추가 (편의 함수)
 */
kmoment_t* kmoment_add_hours(kmoment_t *m, int hours);

/**
 * 분 추가 (편의 함수)
 */
kmoment_t* kmoment_add_minutes(kmoment_t *m, int minutes);

/**
 * 초 추가 (편의 함수)
 */
kmoment_t* kmoment_add_seconds(kmoment_t *m, int seconds);

/* ============================================
   비교 함수
   ============================================ */

/**
 * 두 시간의 차이 (초 단위)
 */
long kmoment_diff(kmoment_t *m1, kmoment_t *m2);

/**
 * 두 시간의 차이 (지정된 단위)
 * unit: "days", "hours", "minutes", "seconds"
 */
long kmoment_diff_unit(kmoment_t *m1, kmoment_t *m2, const char *unit);

/**
 * 이후 시간인지 확인
 */
bool kmoment_is_after(kmoment_t *m1, kmoment_t *m2);

/**
 * 이전 시간인지 확인
 */
bool kmoment_is_before(kmoment_t *m1, kmoment_t *m2);

/**
 * 같은 시간인지 확인
 */
bool kmoment_is_same(kmoment_t *m1, kmoment_t *m2);

/* ============================================
   상대 시간 함수
   ============================================ */

/**
 * 지금부터 얼마 떨어져 있는지 (예: "3 days ago", "in 2 hours")
 */
char* kmoment_from_now(kmoment_t *m);

/**
 * 지금부터 얼마 떨어져 있는지 (역순)
 */
char* kmoment_to_now(kmoment_t *m);

/**
 * 특정 시간으로부터 얼마 떨어져 있는지
 */
char* kmoment_from(kmoment_t *m, kmoment_t *base);

/* ============================================
   유틸리티 함수
   ============================================ */

/**
 * 년도
 */
int kmoment_year(kmoment_t *m);

/**
 * 월 (1-12)
 */
int kmoment_month(kmoment_t *m);

/**
 * 일 (1-31)
 */
int kmoment_day(kmoment_t *m);

/**
 * 요일 (0=일요일, 1=월요일, ..., 6=토요일)
 */
int kmoment_day_of_week(kmoment_t *m);

/**
 * 시간 (0-23)
 */
int kmoment_hour(kmoment_t *m);

/**
 * 분 (0-59)
 */
int kmoment_minute(kmoment_t *m);

/**
 * 초 (0-59)
 */
int kmoment_second(kmoment_t *m);

/**
 * Unix 타임스탬프
 */
time_t kmoment_unix_timestamp(kmoment_t *m);

/**
 * 밀리초 단위 현재 시간
 */
long kmoment_now_ms(void);

#endif // KMOMENT_H

