/*
 * Kim Moment (kmoment.c)
 *
 * 날짜/시간 처리 구현
 */

#define _GNU_SOURCE
#include "kmoment.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ============================================
   생성 함수
   ============================================ */

kmoment_t* kmoment_now(void) {
    kmoment_t *m = (kmoment_t *)malloc(sizeof(kmoment_t));
    if (!m) return NULL;

    m->timestamp = time(NULL);
    localtime_r(&m->timestamp, &m->tm);

    return m;
}

kmoment_t* kmoment_unix(time_t timestamp) {
    kmoment_t *m = (kmoment_t *)malloc(sizeof(kmoment_t));
    if (!m) return NULL;

    m->timestamp = timestamp;
    localtime_r(&m->timestamp, &m->tm);

    return m;
}

kmoment_t* kmoment_date(int year, int month, int day, int hour, int minute, int second) {
    kmoment_t *m = (kmoment_t *)malloc(sizeof(kmoment_t));
    if (!m) return NULL;

    memset(&m->tm, 0, sizeof(struct tm));
    m->tm.tm_year = year - 1900;
    m->tm.tm_mon = month - 1;
    m->tm.tm_mday = day;
    m->tm.tm_hour = hour;
    m->tm.tm_min = minute;
    m->tm.tm_sec = second;

    m->timestamp = mktime(&m->tm);

    return m;
}

kmoment_t* kmoment_clone(kmoment_t *m) {
    if (!m) return NULL;

    kmoment_t *clone = (kmoment_t *)malloc(sizeof(kmoment_t));
    memcpy(clone, m, sizeof(kmoment_t));

    return clone;
}

void kmoment_free(kmoment_t *m) {
    if (m) free(m);
}

/* ============================================
   파싱 함수
   ============================================ */

kmoment_t* kmoment_parse(const char *str) {
    if (!str) return NULL;

    int year, month, day, hour = 0, minute = 0, second = 0;

    if (sscanf(str, "%d-%d-%d %d:%d:%d", &year, &month, &day, &hour, &minute, &second) < 3) {
        if (sscanf(str, "%d-%d-%d", &year, &month, &day) != 3) {
            return NULL;
        }
    }

    return kmoment_date(year, month, day, hour, minute, second);
}

kmoment_t* kmoment_parse_unix(const char *unix_str) {
    if (!unix_str) return NULL;

    time_t timestamp = (time_t)atoll(unix_str);
    return kmoment_unix(timestamp);
}

/* ============================================
   포맷 변환 함수
   ============================================ */

char* kmoment_format(kmoment_t *m, const char *format) {
    if (!m || !format) return NULL;

    char *result = (char *)malloc(256);
    if (!result) return NULL;

    result[0] = '\0';
    int pos = 0;

    for (int i = 0; format[i] && pos < 255; i++) {
        if (format[i] == 'Y' && i + 3 < strlen(format) &&
            strncmp(&format[i], "YYYY", 4) == 0) {
            pos += snprintf(result + pos, 256 - pos, "%04d", m->tm.tm_year + 1900);
            i += 3;
        } else if (format[i] == 'M' && i + 1 < strlen(format) &&
                   strncmp(&format[i], "MM", 2) == 0) {
            pos += snprintf(result + pos, 256 - pos, "%02d", m->tm.tm_mon + 1);
            i += 1;
        } else if (format[i] == 'D' && i + 1 < strlen(format) &&
                   strncmp(&format[i], "DD", 2) == 0) {
            pos += snprintf(result + pos, 256 - pos, "%02d", m->tm.tm_mday);
            i += 1;
        } else if (format[i] == 'H' && i + 1 < strlen(format) &&
                   strncmp(&format[i], "HH", 2) == 0) {
            pos += snprintf(result + pos, 256 - pos, "%02d", m->tm.tm_hour);
            i += 1;
        } else if (format[i] == 'm' && i + 1 < strlen(format) &&
                   format[i + 1] == 'm') {
            pos += snprintf(result + pos, 256 - pos, "%02d", m->tm.tm_min);
            i += 1;
        } else if (format[i] == 's' && i + 1 < strlen(format) &&
                   format[i + 1] == 's') {
            pos += snprintf(result + pos, 256 - pos, "%02d", m->tm.tm_sec);
            i += 1;
        } else {
            result[pos++] = format[i];
        }
    }

    result[pos] = '\0';
    return result;
}

char* kmoment_to_iso_string(kmoment_t *m) {
    if (!m) return NULL;
    return kmoment_format(m, "YYYY-MM-DDTHH:mm:ssZ");
}

char* kmoment_to_string(kmoment_t *m) {
    if (!m) return NULL;
    return kmoment_format(m, "YYYY-MM-DD HH:mm:ss");
}

char* kmoment_to_unix_string(kmoment_t *m) {
    if (!m) return NULL;

    char *result = (char *)malloc(32);
    snprintf(result, 32, "%ld", m->timestamp);

    return result;
}

/* ============================================
   시간 계산 함수
   ============================================ */

kmoment_t* kmoment_add(kmoment_t *m, int value, const char *unit) {
    if (!m || !unit) return NULL;

    kmoment_t *result = kmoment_clone(m);
    time_t seconds = 0;

    if (strcmp(unit, "days") == 0) {
        seconds = value * 86400;
    } else if (strcmp(unit, "hours") == 0) {
        seconds = value * 3600;
    } else if (strcmp(unit, "minutes") == 0) {
        seconds = value * 60;
    } else if (strcmp(unit, "seconds") == 0) {
        seconds = value;
    }

    result->timestamp += seconds;
    localtime_r(&result->timestamp, &result->tm);

    return result;
}

kmoment_t* kmoment_subtract(kmoment_t *m, int value, const char *unit) {
    if (!m || !unit) return NULL;
    return kmoment_add(m, -value, unit);
}

kmoment_t* kmoment_add_days(kmoment_t *m, int days) {
    return kmoment_add(m, days, "days");
}

kmoment_t* kmoment_add_hours(kmoment_t *m, int hours) {
    return kmoment_add(m, hours, "hours");
}

kmoment_t* kmoment_add_minutes(kmoment_t *m, int minutes) {
    return kmoment_add(m, minutes, "minutes");
}

