            snprintf(result, 64, "in %ld hour%s", diff / 3600, (diff / 3600) > 1 ? "s" : "");
        } else {
            snprintf(result, 64, "in %ld day%s", diff / 86400, (diff / 86400) > 1 ? "s" : "");
        }
    } else {
        diff = -diff;
        if (diff < 60) {
            snprintf(result, 64, "%ld second%s ago", diff, diff > 1 ? "s" : "");
