/*
 * Kim Glob (kglob.c)
 *
 * 파일 검색 패턴 구현
 */

#define _GNU_SOURCE
#include "kglob.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>

/* ============================================
   생성 및 정리
   ============================================ */

kglob_result_t* kglob_result_new(void) {
    kglob_result_t *result = (kglob_result_t *)malloc(sizeof(kglob_result_t));
    if (!result) return NULL;

    result->capacity = 20;
    result->count = 0;
    result->files = (kglob_file_t *)malloc(result->capacity * sizeof(kglob_file_t));

    return result;
}

void kglob_result_free(kglob_result_t *result) {
    if (result) {
        if (result->files) free(result->files);
        free(result);
    }
}

bool kglob_result_add(kglob_result_t *result, const char *path, bool is_dir) {
    if (!result || !path) return false;

    if (result->count >= result->capacity) {
        result->capacity *= 2;
        result->files = (kglob_file_t *)realloc(result->files,
                        result->capacity * sizeof(kglob_file_t));
    }

    kglob_file_t *file = &result->files[result->count];
    strncpy(file->path, path, sizeof(file->path) - 1);

    // 파일명 추출
    const char *name = strrchr(path, '/');
    if (name) {
        strncpy(file->name, name + 1, sizeof(file->name) - 1);
    } else {
        strncpy(file->name, path, sizeof(file->name) - 1);
    }

    file->is_dir = is_dir;

    // 파일 정보 조회
    struct stat st;
    if (stat(path, &st) == 0) {
        file->size = st.st_size;
        file->mtime = st.st_mtime;
    } else {
        file->size = 0;
        file->mtime = 0;
    }

    result->count++;
    return true;
}

/* ============================================
   패턴 매칭
   ============================================ */

bool kglob_match(const char *pattern, const char *string) {
    if (!pattern || !string) return false;

    const char *p = pattern;
    const char *s = string;

    while (*p && *s) {
        if (*p == '*') {
            if (!p[1]) return true;  // * 끝
            while (*s && !kglob_match(p + 1, s)) s++;
            return kglob_match(p + 1, s);
        } else if (*p == '?' || *p == *s) {
            p++;
            s++;
        } else {
            return false;
        }
    }

    return *s == '\0' && (*p == '\0' || (p[0] == '*' && p[1] == '\0'));
}

bool kglob_match_simple(const char *pattern, const char *string) {
    if (!pattern || !string) return false;

    const char *p = pattern;
    const char *s = string;

    while (*p && *s) {
        if (*p == '*') {
            if (!p[1]) return true;
            while (*s && !kglob_match_simple(p + 1, s)) s++;
            return kglob_match_simple(p + 1, s);
        } else if (*p == '?' || *p == *s) {
            p++;
            s++;
        } else {
            return false;
        }
    }

    return *s == '\0' && (*p == '\0' || (p[0] == '*' && p[1] == '\0'));
}

/* ============================================
   검색
   ============================================ */

static void kglob_scan_dir(const char *dir, const char *pattern,
                          kglob_result_t *result, bool recursive) {
    DIR *d = opendir(dir);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (entry->d_name[0] == '.') continue;  // 숨김 파일 제외

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir, entry->d_name);

        struct stat st;
        stat(full_path, &st);

        // 패턴 매칭
        if (kglob_match_simple(pattern, entry->d_name)) {
            kglob_result_add(result, full_path, S_ISDIR(st.st_mode));
        }

        // 재귀 (디렉토리)
        if (recursive && S_ISDIR(st.st_mode)) {
            kglob_scan_dir(full_path, pattern, result, recursive);
        }
    }

    closedir(d);
}

kglob_result_t* kglob_glob(const char *pattern) {
    return kglob_glob_in(".", pattern);
}

kglob_result_t* kglob_glob_in(const char *directory, const char *pattern) {
    if (!directory || !pattern) return NULL;

    kglob_result_t *result = kglob_result_new();
    if (!result) return NULL;

    // ** 재귀 패턴 처리
    bool recursive = strstr(pattern, "**") != NULL;

    // 패턴 단순화
    char clean_pattern[256];
    strncpy(clean_pattern, pattern, sizeof(clean_pattern) - 1);

    // ** 제거
    char *ptr = clean_pattern;
    while ((ptr = strstr(ptr, "/**/")) != NULL) {
        memmove(ptr, ptr + 3, strlen(ptr + 3) + 1);
    }

    // 시작 패턴 추출
    char *slash = strchr(clean_pattern, '/');
    char search_pattern[256];
    if (slash) {
        strncpy(search_pattern, clean_pattern, slash - clean_pattern);
        search_pattern[slash - clean_pattern] = '\0';
    } else {
        strcpy(search_pattern, clean_pattern);
    }

    kglob_scan_dir(directory, search_pattern, result, recursive);
    return result;
}

kglob_result_t* kglob_glob_simple(const char *pattern) {
    return kglob_glob_in(".", pattern);
}

/* ============================================
   필터링
   ============================================ */

kglob_result_t* kglob_filter_dirs(kglob_result_t *result) {
    if (!result) return NULL;

    kglob_result_t *filtered = kglob_result_new();
    if (!filtered) return result;

    for (int i = 0; i < result->count; i++) {
        if (result->files[i].is_dir) {
            kglob_result_add(filtered, result->files[i].path, true);
        }
    }

    kglob_result_free(result);
    return filtered;
}

kglob_result_t* kglob_filter_files(kglob_result_t *result) {
    if (!result) return NULL;

    kglob_result_t *filtered = kglob_result_new();
    if (!filtered) return result;

    for (int i = 0; i < result->count; i++) {
        if (!result->files[i].is_dir) {
            kglob_result_add(filtered, result->files[i].path, false);
        }
    }

    kglob_result_free(result);
    return filtered;
}

kglob_result_t* kglob_filter_by_size(kglob_result_t *result, long min_size, long max_size) {
    if (!result) return NULL;

    kglob_result_t *filtered = kglob_result_new();
    if (!filtered) return result;

    for (int i = 0; i < result->count; i++) {
        long size = result->files[i].size;
        if (size >= min_size && size <= max_size) {
            kglob_result_add(filtered, result->files[i].path, result->files[i].is_dir);
        }
    }

    kglob_result_free(result);
    return filtered;
}

/* ============================================
   유틸리티
   ============================================ */

kglob_result_t* kglob_filter_by_ext(kglob_result_t *result, const char *ext) {
    if (!result || !ext) return result;

    kglob_result_t *filtered = kglob_result_new();
    if (!filtered) return result;

    for (int i = 0; i < result->count; i++) {
        const char *dot = strrchr(result->files[i].name, '.');
        if (dot && strcmp(dot + 1, ext) == 0) {
            kglob_result_add(filtered, result->files[i].path, result->files[i].is_dir);
        }
    }

    kglob_result_free(result);
    return filtered;
}

static int kglob_compare_name(const void *a, const void *b) {
    const kglob_file_t *fa = (const kglob_file_t *)a;
    const kglob_file_t *fb = (const kglob_file_t *)b;
    return strcmp(fa->name, fb->name);
}

void kglob_result_sort(kglob_result_t *result) {
    if (result) {
        qsort(result->files, result->count, sizeof(kglob_file_t), kglob_compare_name);
    }
}

int kglob_count(kglob_result_t *result) {
    return result ? result->count : 0;
}

const char* kglob_get_path(kglob_result_t *result, int index) {
    if (!result || index < 0 || index >= result->count) return NULL;
    return result->files[index].path;
}

