/*
 * Kim GraphQL (kgraphql.c)
 *
 * GraphQL API 구현
 */

#define _GNU_SOURCE
#include "kgraphql.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ============================================
   스키마 구성
   ============================================ */

kgraphql_schema_t* kgraphql_schema_new(void) {
    kgraphql_schema_t *schema = (kgraphql_schema_t *)malloc(sizeof(kgraphql_schema_t));
    if (!schema) return NULL;

    schema->type_capacity = 10;
    schema->type_count = 0;
    schema->types = (kgraphql_type_def_t **)malloc(schema->type_capacity * sizeof(kgraphql_type_def_t *));
    schema->query_type = NULL;
    schema->mutation_type = NULL;

    return schema;
}

kgraphql_type_def_t* kgraphql_type_new(const char *name) {
    if (!name) return NULL;

    kgraphql_type_def_t *type = (kgraphql_type_def_t *)malloc(sizeof(kgraphql_type_def_t));
    if (!type) return NULL;

    memset(type, 0, sizeof(kgraphql_type_def_t));
    strncpy(type->name, name, sizeof(type->name) - 1);
    type->field_capacity = 10;
    type->fields = (kgraphql_field_t *)malloc(type->field_capacity * sizeof(kgraphql_field_t));

    return type;
}

bool kgraphql_type_add_field(kgraphql_type_def_t *type,
                              const char *name, kgraphql_type_t field_type,
                              kgraphql_resolver_t resolver, bool required) {
    if (!type || !name || !resolver) return false;

    if (type->field_count >= type->field_capacity) {
        type->field_capacity *= 2;
        type->fields = (kgraphql_field_t *)realloc(type->fields,
                       type->field_capacity * sizeof(kgraphql_field_t));
    }

    kgraphql_field_t *field = &type->fields[type->field_count];
    strncpy(field->name, name, sizeof(field->name) - 1);
    field->type = field_type;
    field->resolver = resolver;
    field->required = required;

    type->field_count++;
    return true;
}

bool kgraphql_schema_add_type(kgraphql_schema_t *schema, kgraphql_type_def_t *type) {
    if (!schema || !type) return false;

    if (schema->type_count >= schema->type_capacity) {
        schema->type_capacity *= 2;
        schema->types = (kgraphql_type_def_t **)realloc(schema->types,
                       schema->type_capacity * sizeof(kgraphql_type_def_t *));
    }

    schema->types[schema->type_count] = type;
    schema->type_count++;
    return true;
}

bool kgraphql_schema_set_query(kgraphql_schema_t *schema, kgraphql_type_def_t *query_type) {
    if (!schema || !query_type) return false;
    schema->query_type = query_type;
    return true;
}

bool kgraphql_schema_set_mutation(kgraphql_schema_t *schema, kgraphql_type_def_t *mutation_type) {
    if (!schema || !mutation_type) return false;
    schema->mutation_type = mutation_type;
    return true;
}

/* ============================================
   쿼리 실행
   ============================================ */

char* kgraphql_execute(kgraphql_schema_t *schema, const char *query, void *context) {
    if (!schema || !query) return NULL;

    // 간단한 시뮬레이션: 쿼리 파싱 및 실행
    char *result = (char *)malloc(1024);
    if (!result) return NULL;

    snprintf(result, 1024, "{\"data\":{\"message\":\"Query executed\"}}");
    return result;
}

bool kgraphql_parse_query(const char *query, char *operation, char *args) {
    if (!query || !operation || !args) return false;

    // 간단한 파싱: "operation(args)" 형태
    sscanf(query, "%255s(%255s)", operation, args);
    return true;
}

bool kgraphql_validate_query(kgraphql_schema_t *schema, const char *query) {
    if (!schema || !query) return false;

    // 간단한 검증: 쿼리가 비어있지 않은지 확인
    return strlen(query) > 0;
}

/* ============================================
   JSON 응답
   ============================================ */

char* kgraphql_response(const char *data, const char *errors) {
    char *response = (char *)malloc(4096);
    if (!response) return NULL;

    if (errors) {
        snprintf(response, 4096, "{\"data\":%s,\"errors\":[{\"message\":\"%s\"}]}",
                 data ? data : "null", errors);
    } else {
        snprintf(response, 4096, "{\"data\":%s}", data ? data : "null");
    }

    return response;
}

char* kgraphql_error(const char *message) {
    char *error = (char *)malloc(1024);
    if (!error) return NULL;

    snprintf(error, 1024, "{\"errors\":[{\"message\":\"%s\"}]}", message ? message : "Unknown error");
    return error;
}

void kgraphql_response_free(char *response) {
    if (response) free(response);
}

