/**
 * Kim-UUID (kuuid.c)
 * Implementation of UUID generation in Pure C
 *
 * @author Kim AI Empire
 * @version 1.0.0
 * @date 2026-01-18
 */

#include "kuuid.h"
#include <unistd.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <linux/if.h>
#include <sys/ioctl.h>
#include <ifaddrs.h>

/* Static state for UUID v1 */
static pthread_mutex_t uuid_mutex = PTHREAD_MUTEX_INITIALIZER;
static uint16_t clock_seq = 0;
static uint64_t last_timestamp = 0;
static int initialized = 0;

/* ==================== Initialization ==================== */

void kuuid_init(void) {
    if (initialized) return;

    // Seed random with high-resolution time + PID
    struct timeval tv;
    gettimeofday(&tv, NULL);
    unsigned int seed = (unsigned int)(tv.tv_sec ^ tv.tv_usec ^ getpid());
    srand(seed);

    // Initialize clock sequence for UUID v1
    clock_seq = (uint16_t)(rand() & 0x3FFF);  // 14 bits

    initialized = 1;
}

/* ==================== Random Helpers ==================== */

static uint8_t random_byte(void) {
    return (uint8_t)(rand() & 0xFF);
}

static void random_bytes(uint8_t *buffer, size_t count) {
    // Try to use /dev/urandom for better randomness
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        ssize_t result = read(fd, buffer, count);
        close(fd);
        if (result == (ssize_t)count) {
            return;
        }
    }

    // Fallback to rand()
    for (size_t i = 0; i < count; i++) {
        buffer[i] = random_byte();
    }
}

/* ==================== UUID v4 (Random) ==================== */

kuuid_t kuuid_v4(void) {
    if (!initialized) kuuid_init();

    kuuid_t uuid;

    // Generate random bytes
    random_bytes(uuid.bytes, 16);

    // Set version (4 bits, version 4)
    uuid.bytes[6] = (uuid.bytes[6] & 0x0F) | 0x40;

    // Set variant (2 bits, RFC 4122)
    uuid.bytes[8] = (uuid.bytes[8] & 0x3F) | 0x80;

    return uuid;
}

/* ==================== UUID v1 (Time-based) ==================== */

uint64_t kuuid_get_timestamp(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    // UUID timestamp is 100-nanosecond intervals since October 15, 1582
    // Unix epoch is January 1, 1970
    // Offset between UUID epoch and Unix epoch: 122192928000000000

    uint64_t unix_time = (uint64_t)tv.tv_sec * 10000000ULL +
                         (uint64_t)tv.tv_usec * 10ULL;

    return unix_time + 0x01B21DD213814000ULL;  // Add UUID epoch offset
}

bool kuuid_get_mac_address(uint8_t mac[6]) {
    struct ifaddrs *ifaddr, *ifa;
    int found = 0;

    if (getifaddrs(&ifaddr) == -1) {
        // Failed to get interfaces, use random MAC
        random_bytes(mac, 6);
        mac[0] |= 0x01;  // Set multicast bit to indicate random MAC
        return false;
    }

    // Find first non-loopback interface
    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL) continue;

        if (ifa->ifa_addr->sa_family == AF_PACKET &&
            strcmp(ifa->ifa_name, "lo") != 0) {

            int sock = socket(AF_INET, SOCK_DGRAM, 0);
            if (sock < 0) continue;

            struct ifreq ifr;
            strncpy(ifr.ifr_name, ifa->ifa_name, IFNAMSIZ - 1);

            if (ioctl(sock, SIOCGIFHWADDR, &ifr) == 0) {
                memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
                found = 1;
                close(sock);
                break;
            }

            close(sock);
        }
    }

    freeifaddrs(ifaddr);

    if (!found) {
        // No interface found, use random MAC
        random_bytes(mac, 6);
        mac[0] |= 0x01;  // Set multicast bit
        return false;
    }

    return true;
}

kuuid_t kuuid_v1(void) {
    if (!initialized) kuuid_init();

    kuuid_t uuid;
    uint64_t timestamp;
    uint16_t seq;
    uint8_t mac[6];

    pthread_mutex_lock(&uuid_mutex);

    // Get timestamp
    timestamp = kuuid_get_timestamp();

    // Handle clock sequence
    if (timestamp <= last_timestamp) {
        clock_seq = (clock_seq + 1) & 0x3FFF;
    }
    last_timestamp = timestamp;
    seq = clock_seq;

    pthread_mutex_unlock(&uuid_mutex);

    // Get MAC address
    kuuid_get_mac_address(mac);

    // Build UUID
    // time_low (0-3)
    uuid.bytes[0] = (uint8_t)(timestamp & 0xFF);
    uuid.bytes[1] = (uint8_t)((timestamp >> 8) & 0xFF);
    uuid.bytes[2] = (uint8_t)((timestamp >> 16) & 0xFF);
    uuid.bytes[3] = (uint8_t)((timestamp >> 24) & 0xFF);

    // time_mid (4-5)
    uuid.bytes[4] = (uint8_t)((timestamp >> 32) & 0xFF);
    uuid.bytes[5] = (uint8_t)((timestamp >> 40) & 0xFF);

    // time_hi_and_version (6-7)
    uuid.bytes[6] = (uint8_t)((timestamp >> 48) & 0x0F) | 0x10;  // Version 1
    uuid.bytes[7] = (uint8_t)((timestamp >> 56) & 0xFF);

    // clock_seq_hi_and_reserved (8)
    uuid.bytes[8] = (uint8_t)((seq >> 8) & 0x3F) | 0x80;  // Variant

    // clock_seq_low (9)
    uuid.bytes[9] = (uint8_t)(seq & 0xFF);

    // node (MAC address) (10-15)
    memcpy(&uuid.bytes[10], mac, 6);

    return uuid;
}

/* ==================== NIL UUID ==================== */

kuuid_t kuuid_nil(void) {
    kuuid_t uuid;
    memset(uuid.bytes, 0, 16);
    return uuid;
}

/* ==================== String Conversion ==================== */

char* kuuid_to_string(const kuuid_t *uuid, char *buffer) {
    if (!uuid || !buffer) return NULL;

    snprintf(buffer, KUUID_STRING_SIZE,
             "%02x%02x%02x%02x-%02x%02x-%02x%02x-%02x%02x-%02x%02x%02x%02x%02x%02x",
             uuid->bytes[0], uuid->bytes[1], uuid->bytes[2], uuid->bytes[3],
             uuid->bytes[4], uuid->bytes[5],
             uuid->bytes[6], uuid->bytes[7],
             uuid->bytes[8], uuid->bytes[9],
             uuid->bytes[10], uuid->bytes[11], uuid->bytes[12],
             uuid->bytes[13], uuid->bytes[14], uuid->bytes[15]);

    return buffer;
}

static int hex_char_to_int(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

bool kuuid_from_string(const char *str, kuuid_t *uuid) {
    if (!str || !uuid) return false;

    // Remove hyphens and copy to clean buffer
    char clean[33];
    int j = 0;

    for (int i = 0; str[i] && j < 32; i++) {
        if (str[i] == '-') continue;

        int val = hex_char_to_int(str[i]);
        if (val < 0) return false;

        clean[j++] = str[i];
    }

    if (j != 32) return false;
    clean[32] = '\0';

    // Parse hex pairs
    for (int i = 0; i < 16; i++) {
        int high = hex_char_to_int(clean[i * 2]);
        int low = hex_char_to_int(clean[i * 2 + 1]);

        if (high < 0 || low < 0) return false;

        uuid->bytes[i] = (uint8_t)((high << 4) | low);
    }

    return true;
}

bool kuuid_is_valid(const char *str) {
    if (!str) return false;

    kuuid_t dummy;
    return kuuid_from_string(str, &dummy);
}

/* ==================== Comparison ==================== */

int kuuid_compare(const kuuid_t *a, const kuuid_t *b) {
    if (!a || !b) return 0;
    return memcmp(a->bytes, b->bytes, 16);
}

bool kuuid_equal(const kuuid_t *a, const kuuid_t *b) {
    return kuuid_compare(a, b) == 0;
}

bool kuuid_is_nil(const kuuid_t *uuid) {
    if (!uuid) return true;

    for (int i = 0; i < 16; i++) {
        if (uuid->bytes[i] != 0) return false;
    }

    return true;
}

/* ==================== Copy ==================== */

void kuuid_copy(kuuid_t *dest, const kuuid_t *src) {
    if (!dest || !src) return;
    memcpy(dest->bytes, src->bytes, 16);
}

/* ==================== Metadata ==================== */

int kuuid_get_version(const kuuid_t *uuid) {
    if (!uuid) return 0;
    return (uuid->bytes[6] >> 4) & 0x0F;
}

int kuuid_get_variant(const kuuid_t *uuid) {
    if (!uuid) return 0;

    uint8_t byte = uuid->bytes[8];

    if ((byte & 0x80) == 0) return 0;      // NCS backward compatibility
    if ((byte & 0xC0) == 0x80) return 2;   // RFC 4122
    if ((byte & 0xE0) == 0xC0) return 6;   // Microsoft
    return 7;                               // Future definition
}

/* ==================== Convenience Functions ==================== */

char* kuuid_v4_string(char *buffer) {
    kuuid_t uuid = kuuid_v4();
    return kuuid_to_string(&uuid, buffer);
}

char* kuuid_v1_string(char *buffer) {
    kuuid_t uuid = kuuid_v1();
    return kuuid_to_string(&uuid, buffer);
}

char* kuuid_v4_alloc(void) {
    char *buffer = malloc(KUUID_STRING_SIZE);
    if (!buffer) return NULL;

    kuuid_v4_string(buffer);
    return buffer;
}

char* kuuid_v1_alloc(void) {
    char *buffer = malloc(KUUID_STRING_SIZE);
    if (!buffer) return NULL;

    kuuid_v1_string(buffer);
    return buffer;
}

/* ==================== Print ==================== */

void kuuid_print(const kuuid_t *uuid) {
    kuuid_fprint(stdout, uuid);
}

void kuuid_fprint(FILE *fp, const kuuid_t *uuid) {
    if (!uuid || !fp) return;

    char buffer[KUUID_STRING_SIZE];
    kuuid_to_string(uuid, buffer);
    fprintf(fp, "%s", buffer);
}

