// 2. 더 강한 seed 생성
#include <fcntl.h>
#include <errno.h>

void kuuid_init(void) {
    if (initialized) return;

    unsigned int seed = 0;
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        read(fd, &seed, sizeof(seed));
        close(fd);
    } else {
        // 폴백: 여러 소스 조합
        struct timeval tv;
        gettimeofday(&tv, NULL);
        seed = (unsigned int)(
            (tv.tv_sec ^ tv.tv_usec) +
            getpid() +
            getppid() +
            getuid()
        );
    }

    srand(seed);
    initialized = 1;
}
