/**
 * Kim-MIME-Types (kmime.c)
 * Implementation of MIME type detection library in Pure C
 *
 * @author Kim AI Empire
 * @version 1.0.0
 * @date 2026-01-19
 */

#define _GNU_SOURCE

#include "kmime.h"
#include <ctype.h>
#include <strings.h>

/* ==================== MIME Database ==================== */

typedef struct {
    const char *ext;
    const char *mime;
    const char *charset;
    bool compressible;
} mime_entry_t;

static const mime_entry_t mime_db[] = {
    /* Text */
    {"html", "text/html", "UTF-8", true},
    {"htm", "text/html", "UTF-8", true},
    {"css", "text/css", "UTF-8", true},
    {"txt", "text/plain", "UTF-8", true},
    {"xml", "text/xml", "UTF-8", true},
    {"csv", "text/csv", "UTF-8", true},
    {"md", "text/markdown", "UTF-8", true},
    {"rtf", "text/rtf", NULL, true},
    {"ics", "text/calendar", "UTF-8", true},
    {"vtt", "text/vtt", "UTF-8", true},

    /* JavaScript */
    {"js", "application/javascript", "UTF-8", true},
    {"mjs", "application/javascript", "UTF-8", true},
    {"json", "application/json", "UTF-8", true},
    {"jsonld", "application/ld+json", "UTF-8", true},
    {"map", "application/json", "UTF-8", true},

    /* Images */
    {"png", "image/png", NULL, false},
    {"jpg", "image/jpeg", NULL, false},
    {"jpeg", "image/jpeg", NULL, false},
    {"gif", "image/gif", NULL, false},
    {"webp", "image/webp", NULL, false},
    {"svg", "image/svg+xml", "UTF-8", true},
    {"ico", "image/x-icon", NULL, false},
    {"bmp", "image/bmp", NULL, false},
    {"tiff", "image/tiff", NULL, false},
    {"tif", "image/tiff", NULL, false},
    {"avif", "image/avif", NULL, false},

    /* Fonts */
    {"woff", "font/woff", NULL, false},
    {"woff2", "font/woff2", NULL, false},
    {"ttf", "font/ttf", NULL, false},
    {"otf", "font/otf", NULL, false},
    {"eot", "application/vnd.ms-fontobject", NULL, false},

    /* Documents */
    {"pdf", "application/pdf", NULL, false},
    {"doc", "application/msword", NULL, false},
    {"docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", NULL, false},
    {"xls", "application/vnd.ms-excel", NULL, false},
    {"xlsx", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", NULL, false},
    {"ppt", "application/vnd.ms-powerpoint", NULL, false},
    {"pptx", "application/vnd.openxmlformats-officedocument.presentationml.presentation", NULL, false},
    {"odt", "application/vnd.oasis.opendocument.text", NULL, false},
    {"ods", "application/vnd.oasis.opendocument.spreadsheet", NULL, false},
    {"odp", "application/vnd.oasis.opendocument.presentation", NULL, false},

    /* Archives */
    {"zip", "application/zip", NULL, false},
    {"rar", "application/x-rar-compressed", NULL, false},
    {"7z", "application/x-7z-compressed", NULL, false},
    {"tar", "application/x-tar", NULL, false},
    {"gz", "application/gzip", NULL, false},
    {"bz2", "application/x-bzip2", NULL, false},
    {"xz", "application/x-xz", NULL, false},

    /* Video */
    {"mp4", "video/mp4", NULL, false},
    {"webm", "video/webm", NULL, false},
    {"ogv", "video/ogg", NULL, false},
    {"avi", "video/x-msvideo", NULL, false},
    {"mov", "video/quicktime", NULL, false},
    {"wmv", "video/x-ms-wmv", NULL, false},
    {"flv", "video/x-flv", NULL, false},
    {"mkv", "video/x-matroska", NULL, false},
    {"m4v", "video/x-m4v", NULL, false},
    {"3gp", "video/3gpp", NULL, false},

    /* Audio */
    {"mp3", "audio/mpeg", NULL, false},
    {"wav", "audio/wav", NULL, false},
    {"ogg", "audio/ogg", NULL, false},
    {"m4a", "audio/mp4", NULL, false},
    {"aac", "audio/aac", NULL, false},
    {"flac", "audio/flac", NULL, false},
    {"opus", "audio/opus", NULL, false},
    {"weba", "audio/webm", NULL, false},

    /* Application */
    {"wasm", "application/wasm", NULL, false},
    {"swf", "application/x-shockwave-flash", NULL, false},
    {"jar", "application/java-archive", NULL, false},
    {"class", "application/java-vm", NULL, false},
    {"bin", "application/octet-stream", NULL, false},
    {"exe", "application/x-msdownload", NULL, false},
    {"dll", "application/x-msdownload", NULL, false},
    {"deb", "application/x-debian-package", NULL, false},
    {"rpm", "application/x-rpm", NULL, false},
    {"dmg", "application/x-apple-diskimage", NULL, false},
    {"iso", "application/x-iso9660-image", NULL, false},

    /* Markup */
    {"xhtml", "application/xhtml+xml", "UTF-8", true},
    {"atom", "application/atom+xml", "UTF-8", true},
    {"rss", "application/rss+xml", "UTF-8", true},

    /* Scripts */
    {"sh", "application/x-sh", NULL, true},
    {"pl", "application/x-perl", NULL, true},
    {"py", "text/x-python", "UTF-8", true},
    {"rb", "text/x-ruby", "UTF-8", true},
    {"php", "text/x-php", "UTF-8", true},

    /* Data */
    {"yaml", "text/yaml", "UTF-8", true},
    {"yml", "text/yaml", "UTF-8", true},
    {"toml", "application/toml", "UTF-8", true},
    {"ini", "text/plain", "UTF-8", true},
    {"cfg", "text/plain", "UTF-8", true},
    {"conf", "text/plain", "UTF-8", true},
    {"log", "text/plain", "UTF-8", true},

    {NULL, NULL, NULL, false}
};

/* ==================== Helper Functions ==================== */

const char* kmime_get_extension(const char *filename) {
    if (!filename) return "";

    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return "";

    return dot + 1;
}

void kmime_normalize(char *mime_type) {
    if (!mime_type) return;

    // Lowercase
    for (char *p = mime_type; *p; p++) {
        *p = tolower(*p);
    }

    // Trim
    char *start = mime_type;
    while (*start && isspace(*start)) start++;

    char *end = start + strlen(start) - 1;
    while (end > start && isspace(*end)) end--;
    *(end + 1) = '\0';

    if (start != mime_type) {
        memmove(mime_type, start, strlen(start) + 1);
    }
}

/* ==================== Core API ==================== */

int kmime_lookup(const char *extension, char *mime_type, size_t size) {
    if (!extension || !mime_type || size == 0) return -1;

    // Default
    strncpy(mime_type, "application/octet-stream", size - 1);
    mime_type[size - 1] = '\0';

    // Lookup
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        if (strcasecmp(extension, e->ext) == 0) {
            strncpy(mime_type, e->mime, size - 1);
            mime_type[size - 1] = '\0';
            return 0;
        }
    }

    return 0;
}

int kmime_get_info(const char *extension, kmime_info_t *info) {
    if (!extension || !info) return -1;

    memset(info, 0, sizeof(kmime_info_t));

    // Default
    strncpy(info->mime_type, "application/octet-stream",
            sizeof(info->mime_type) - 1);
    info->compressible = false;

    // Lookup
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        if (strcasecmp(extension, e->ext) == 0) {
            strncpy(info->mime_type, e->mime, sizeof(info->mime_type) - 1);
            strncpy(info->extension, e->ext, sizeof(info->extension) - 1);

            if (e->charset) {
                strncpy(info->charset, e->charset, sizeof(info->charset) - 1);
            }

            info->compressible = e->compressible;
            return 0;
        }
    }

    return 0;
}

int kmime_extension(const char *mime_type, char *extension, size_t size) {
    if (!mime_type || !extension || size == 0) return -1;

    extension[0] = '\0';

    // Normalize
    char normalized[KMIME_MAX_TYPE];
    strncpy(normalized, mime_type, sizeof(normalized) - 1);
    normalized[sizeof(normalized) - 1] = '\0';
    kmime_normalize(normalized);

    // Lookup
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        char entry_mime[KMIME_MAX_TYPE];
        strncpy(entry_mime, e->mime, sizeof(entry_mime) - 1);
        entry_mime[sizeof(entry_mime) - 1] = '\0';
        kmime_normalize(entry_mime);

        if (strcmp(normalized, entry_mime) == 0) {
            strncpy(extension, e->ext, size - 1);
            extension[size - 1] = '\0';
            return 0;
        }
    }

    return -1;
}

int kmime_charset(const char *mime_type, char *charset, size_t size) {
    if (!mime_type || !charset || size == 0) return -1;

    charset[0] = '\0';

    // Normalize
    char normalized[KMIME_MAX_TYPE];
    strncpy(normalized, mime_type, sizeof(normalized) - 1);
    normalized[sizeof(normalized) - 1] = '\0';
    kmime_normalize(normalized);

    // Lookup
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        char entry_mime[KMIME_MAX_TYPE];
        strncpy(entry_mime, e->mime, sizeof(entry_mime) - 1);
        entry_mime[sizeof(entry_mime) - 1] = '\0';
        kmime_normalize(entry_mime);

        if (strcmp(normalized, entry_mime) == 0 && e->charset) {
            strncpy(charset, e->charset, size - 1);
            charset[size - 1] = '\0';
            return 0;
        }
    }

    return -1;
}

bool kmime_is_compressible(const char *mime_type) {
    if (!mime_type) return false;

    // Normalize
    char normalized[KMIME_MAX_TYPE];
    strncpy(normalized, mime_type, sizeof(normalized) - 1);
    normalized[sizeof(normalized) - 1] = '\0';
    kmime_normalize(normalized);

    // Lookup
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        char entry_mime[KMIME_MAX_TYPE];
        strncpy(entry_mime, e->mime, sizeof(entry_mime) - 1);
        entry_mime[sizeof(entry_mime) - 1] = '\0';
        kmime_normalize(entry_mime);

        if (strcmp(normalized, entry_mime) == 0) {
            return e->compressible;
        }
    }

    // Default: text/* and application/json are compressible
    if (strncmp(normalized, "text/", 5) == 0) return true;
    if (strcmp(normalized, "application/json") == 0) return true;
    if (strcmp(normalized, "application/javascript") == 0) return true;
    if (strcmp(normalized, "application/xml") == 0) return true;

    return false;
}

int kmime_content_type(const char *mime_type, const char *charset,
                       char *output, size_t size) {
    if (!mime_type || !output || size == 0) return -1;

    if (charset && charset[0]) {
        int n = snprintf(output, size, "Content-Type: %s; charset=%s",
                         mime_type, charset);
        if (n < 0 || (size_t)n >= size) return -1;
    } else {
        // Auto-detect charset
        char auto_charset[KMIME_MAX_CHARSET];
        if (kmime_charset(mime_type, auto_charset, sizeof(auto_charset)) == 0 &&
            auto_charset[0]) {
            int n = snprintf(output, size, "Content-Type: %s; charset=%s",
                             mime_type, auto_charset);
            if (n < 0 || (size_t)n >= size) return -1;
        } else {
            int n = snprintf(output, size, "Content-Type: %s", mime_type);
            if (n < 0 || (size_t)n >= size) return -1;
        }
    }

    return 0;
}

/* ==================== Utilities ==================== */

bool kmime_is_text(const char *mime_type) {
    if (!mime_type) return false;
    return strncasecmp(mime_type, "text/", 5) == 0;
}

bool kmime_is_image(const char *mime_type) {
    if (!mime_type) return false;
    return strncasecmp(mime_type, "image/", 6) == 0;
}

bool kmime_is_video(const char *mime_type) {
    if (!mime_type) return false;
    return strncasecmp(mime_type, "video/", 6) == 0;
}

bool kmime_is_audio(const char *mime_type) {
    if (!mime_type) return false;
    return strncasecmp(mime_type, "audio/", 6) == 0;
}

int kmime_count(void) {
    int count = 0;
    for (const mime_entry_t *e = mime_db; e->ext; e++) {
        count++;
    }
    return count;
}

int kmime_get_by_index(int index, kmime_info_t *info) {
    if (index < 0 || !info) return -1;

    int i = 0;
    for (const mime_entry_t *e = mime_db; e->ext; e++, i++) {
        if (i == index) {
            memset(info, 0, sizeof(kmime_info_t));
            strncpy(info->mime_type, e->mime, sizeof(info->mime_type) - 1);
            strncpy(info->extension, e->ext, sizeof(info->extension) - 1);

            if (e->charset) {
                strncpy(info->charset, e->charset, sizeof(info->charset) - 1);
            }

            info->compressible = e->compressible;
            return 0;
        }
    }

    return -1;
}

/**
 * Kim-Range-Parser (krange.h)
 * Sovereign HTTP Range Header Parser in Pure C
 *
 * HTTP Range request parser for partial content (HTTP 206),
 * multipart ranges, and conditional requests (If-Range).
 *
 * Features:
 * - Range header parsing (bytes=0-1023)
 * - Multiple ranges (bytes=0-499,1000-1499)
 * - Suffix ranges (bytes=-500)
 * - Open-ended ranges (bytes=9500-)
 * - Content-Range generation
 * - If-Range validation (ETag/Last-Modified)
 * - Multipart/byteranges support
 * - Zero external dependencies (libc only)
 *
 * Philosophy: Stability > Creativity > 0% External Dependencies
 *
 * @author Kim AI Empire
 * @version 1.0.0
 * @date 2026-01-19
 */

#ifndef KRANGE_H
#define KRANGE_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

/* ==================== Configuration ==================== */

#define KRANGE_VERSION "1.0.0"
#define KRANGE_MAX_RANGES 16

/* ==================== Types ==================== */

/**
 * Range type
 */
typedef enum {
    KRANGE_NORMAL,      // 0-1023 (start-end)
    KRANGE_SUFFIX,      // -500 (last N bytes)
    KRANGE_OPEN,        // 9500- (from start to end)
    KRANGE_INVALID      // Invalid range
} krange_type_t;

/**
 * Single range
 */
typedef struct {
    krange_type_t type;    // Range type
    int64_t start;         // Start byte (inclusive)
    int64_t end;           // End byte (inclusive)
} krange_t;

/**
 * Range list (parsed result)
 */
typedef struct {
    krange_t ranges[KRANGE_MAX_RANGES];  // Range array
    int count;             // Number of ranges
    const char *unit;      // Unit (e.g., "bytes")
} krange_list_t;

/**
 * Satisfied range (after validation)
 */
typedef struct {
    int64_t start;         // Start byte
    int64_t end;           // End byte (inclusive)
    int64_t length;        // Content length (end - start + 1)
    int64_t total;         // Total file size
    bool valid;            // Range is satisfiable
} krange_result_t;

/**
 * If-Range condition
 */
typedef struct {
    const char *etag;      // ETag (NULL if not present)
    time_t modified;       // Last-Modified (0 if not present)
} krange_condition_t;

/* ==================== Core API ==================== */

/**
 * Parse Range header
 * @param range_header Range header value (e.g., "bytes=0-1023")
 * @param list Range list (output)
 * @return 0 on success, -1 on error
 */
int krange_parse(const char *range_header, krange_list_t *list);

/**
 * Satisfy range (validate against file size)
 * @param range Single range
 * @param total_size Total file size
 * @param result Satisfied range (output)
 * @return 0 on success, -1 on error
 */
int krange_satisfy(const krange_t *range, int64_t total_size,
                   krange_result_t *result);

/**
 * Satisfy all ranges
 * @param list Range list
 * @param total_size Total file size
 * @param results Satisfied ranges (output, must be KRANGE_MAX_RANGES)
 * @param count Number of satisfied ranges (output)
 * @return 0 on success, -1 on error
 */
int krange_satisfy_all(const krange_list_t *list, int64_t total_size,
                       krange_result_t *results, int *count);

/**
 * Check if ranges are satisfiable
 * @param list Range list
 * @param total_size Total file size
 * @return true if satisfiable, false otherwise
 */
bool krange_is_satisfiable(const krange_list_t *list, int64_t total_size);

/**
 * Generate Content-Range header (single range)
 * @param result Satisfied range
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_content_range(const krange_result_t *result, char *output,
                         size_t size);

/**
 * Check If-Range condition (ETag)
 * @param if_range If-Range header value (ETag)
 * @param current_etag Current ETag
 * @return true if condition met, false otherwise
 */
bool krange_check_if_range_etag(const char *if_range,
                                const char *current_etag);

/**
 * Check If-Range condition (Last-Modified)
 * @param if_range If-Range header value (date)
 * @param current_mtime Current modification time
 * @return true if condition met, false otherwise
 */
bool krange_check_if_range_date(const char *if_range, time_t current_mtime);

/* ==================== Multipart Support ==================== */

/**
 * Generate multipart boundary
 * @param boundary Output buffer (min 64 bytes)
 * @return 0 on success, -1 on error
 */
int krange_generate_boundary(char *boundary);

/**
 * Format multipart header
 * @param result Satisfied range
 * @param content_type Content-Type
 * @param boundary Multipart boundary
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_multipart_header(const krange_result_t *result,
                            const char *content_type,
                            const char *boundary,
                            char *output, size_t size);

/**
 * Format multipart trailer
 * @param boundary Multipart boundary
 * @param output Output buffer
 * @param size Buffer size
 * @return 0 on success, -1 on error
 */
int krange_multipart_trailer(const char *boundary, char *output, size_t size);

/* ==================== Utilities ==================== */

/**
 * Normalize range (convert to absolute offsets)
 * @param range Range to normalize
 * @param total_size Total file size
 * @return Normalized range
 */
krange_t krange_normalize(const krange_t *range, int64_t total_size);

/**
 * Check if range overlaps
 * @param r1 First range
 * @param r2 Second range
 * @return true if overlaps, false otherwise
 */
bool krange_overlaps(const krange_result_t *r1, const krange_result_t *r2);

/**
 * Merge overlapping ranges
 * @param results Range results
 * @param count Number of ranges (input/output)
 * @return 0 on success, -1 on error
 */
int krange_merge(krange_result_t *results, int *count);

/**
 * Calculate total bytes from multiple ranges
 * @param results Range results
 * @param count Number of ranges
 * @return Total bytes
 */
int64_t krange_total_bytes(const krange_result_t *results, int count);

#endif /* KRANGE_H */

