     9→
    10→#define _XOPEN_SOURCE 700
    11→#define _GNU_SOURCE
    12→
    13→#include "krange.h"
    14→#include <ctype.h>
    15→
    16→/* ==================== Helper Functions ==================== */
    17→
    18→static void trim_whitespace(char *str) {
    19→    if (!str) return;
    20→
    21→    char *start = str;
    22→    while (*start && isspace(*start)) start++;
    23→
    24→    char *end = start + strlen(start) - 1;
    25→    while (end > start && isspace(*end)) end--;
    26→    *(end + 1) = '\0';
    27→
    28→    if (start != str) {
    29→        memmove(str, start, strlen(start) + 1);
    30→    }
    31→}
    32→
    33→static int64_t parse_int64(const char *str) {
    34→    if (!str || *str == '\0') return -1;
    35→    return strtoll(str, NULL, 10);
    36→}
    37→
    38→/* ==================== Core API ==================== */
    39→
    40→int krange_parse(const char *range_header, krange_list_t *list) {
    41→    if (!range_header || !list) return -1;
    42→
    43→    memset(list, 0, sizeof(krange_list_t));
    44→
    45→    // Copy for parsing
    46→    char buffer[1024];
    47→    strncpy(buffer, range_header, sizeof(buffer) - 1);
    48→    buffer[sizeof(buffer) - 1] = '\0';
    49→
    50→    trim_whitespace(buffer);
    51→
    52→    // Parse unit (e.g., "bytes=...")
    53→    char *equals = strchr(buffer, '=');
    54→    if (!equals) return -1;
    55→
    56→    *equals = '\0';
    57→    list->unit = "bytes";  // Static string
    58→
    59→    char *unit = buffer;
    60→    trim_whitespace(unit);
    61→
    62→    if (strcmp(unit, "bytes") != 0) {
    63→        return -1;  // Only "bytes" unit supported
    64→    }
    65→
    66→    // Parse ranges
    67→    char *range_spec = equals + 1;
    68→    char *token = strtok(range_spec, ",");
    69→
    70→    while (token && list->count < KRANGE_MAX_RANGES) {
    71→        trim_whitespace(token);
    72→
    73→        krange_t range;
    74→        memset(&range, 0, sizeof(range));
    75→
    76→        // Parse "start-end", "-suffix", or "start-"
    77→        char *hyphen = strchr(token, '-');
    78→        if (!hyphen) {
    79→            continue;  // Invalid
    80→        }
    81→
    82→        *hyphen = '\0';
    83→        char *start_str = token;
    84→        char *end_str = hyphen + 1;
    85→
    86→        trim_whitespace(start_str);
    87→        trim_whitespace(end_str);
    88→
    89→        if (*start_str == '\0' && *end_str == '\0') {
    90→            // Invalid: "-"
    91→            continue;
    92→        } else if (*start_str == '\0') {
    93→            // Suffix range: "-500"
    94→            range.type = KRANGE_SUFFIX;
    95→            range.start = -1;
    96→            range.end = parse_int64(end_str);
    97→            if (range.end <= 0) continue;
    98→        } else if (*end_str == '\0') {
    99→            // Open range: "500-"
   100→            range.type = KRANGE_OPEN;
   101→            range.start = parse_int64(start_str);
   102→            range.end = -1;
   103→            if (range.start < 0) continue;
   104→        } else {
   105→            // Normal range: "0-1023"
   106→            range.type = KRANGE_NORMAL;
   107→            range.start = parse_int64(start_str);
   108→            range.end = parse_int64(end_str);
   109→            if (range.start < 0 || range.end < 0 || range.start > range.end) {
   110→                continue;
   111→            }
   112→        }
   113→
   114→        list->ranges[list->count++] = range;
   115→        token = strtok(NULL, ",");
   116→    }
   117→
   118→    return list->count > 0 ? 0 : -1;
