/**
 * Kim-Range-Parser (krange.c)
 * Implementation of HTTP Range parser in Pure C
 *
 * @author Kim AI Empire
 * @version 1.0.0
 * @date 2026-01-19
 */

#define _XOPEN_SOURCE 700
#define _GNU_SOURCE

#include "krange.h"
#include <ctype.h>

/* ==================== Helper Functions ==================== */

static void trim_whitespace(char *str) {
    if (!str) return;

    char *start = str;
    while (*start && isspace(*start)) start++;

    char *end = start + strlen(start) - 1;
    while (end > start && isspace(*end)) end--;
    *(end + 1) = '\0';

    if (start != str) {
        memmove(str, start, strlen(start) + 1);
    }
}

static int64_t parse_int64(const char *str) {
    if (!str || *str == '\0') return -1;
    return strtoll(str, NULL, 10);
}

/* ==================== Core API ==================== */

int krange_parse(const char *range_header, krange_list_t *list) {
    if (!range_header || !list) return -1;

    memset(list, 0, sizeof(krange_list_t));

    // Copy for parsing
    char buffer[1024];
    strncpy(buffer, range_header, sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';

    trim_whitespace(buffer);

    // Parse unit (e.g., "bytes=...")
    char *equals = strchr(buffer, '=');
    if (!equals) return -1;

    *equals = '\0';
    list->unit = "bytes";  // Static string

    char *unit = buffer;
    trim_whitespace(unit);

    if (strcmp(unit, "bytes") != 0) {
        return -1;  // Only "bytes" unit supported
    }

    // Parse ranges
    char *range_spec = equals + 1;
    char *token = strtok(range_spec, ",");

    while (token && list->count < KRANGE_MAX_RANGES) {
        trim_whitespace(token);

        krange_t range;
        memset(&range, 0, sizeof(range));

        // Parse "start-end", "-suffix", or "start-"
        char *hyphen = strchr(token, '-');
        if (!hyphen) {
            continue;  // Invalid
        }

        *hyphen = '\0';
        char *start_str = token;
        char *end_str = hyphen + 1;

        trim_whitespace(start_str);
        trim_whitespace(end_str);

        if (*start_str == '\0' && *end_str == '\0') {
            // Invalid: "-"
            continue;
        } else if (*start_str == '\0') {
            // Suffix range: "-500"
            range.type = KRANGE_SUFFIX;
            range.start = -1;
            range.end = parse_int64(end_str);
            if (range.end <= 0) continue;
        } else if (*end_str == '\0') {
            // Open range: "500-"
            range.type = KRANGE_OPEN;
            range.start = parse_int64(start_str);
            range.end = -1;
            if (range.start < 0) continue;
        } else {
            // Normal range: "0-1023"
            range.type = KRANGE_NORMAL;
            range.start = parse_int64(start_str);
            range.end = parse_int64(end_str);
            if (range.start < 0 || range.end < 0 || range.start > range.end) {
                continue;
            }
        }

        list->ranges[list->count++] = range;
        token = strtok(NULL, ",");
    }

    return list->count > 0 ? 0 : -1;
}

int krange_satisfy(const krange_t *range, int64_t total_size,
                   krange_result_t *result) {
    if (!range || !result) return -1;

    memset(result, 0, sizeof(krange_result_t));
    result->total = total_size;

    if (total_size <= 0) {
        result->valid = false;
        return -1;
    }

    switch (range->type) {
        case KRANGE_NORMAL:
            // Normal range: 0-1023
            if (range->start >= total_size) {
                result->valid = false;
                return -1;
            }
            result->start = range->start;
            result->end = (range->end >= total_size) ? (total_size - 1) : range->end;
            break;

        case KRANGE_SUFFIX:
            // Suffix range: -500 (last 500 bytes)
            if (range->end > total_size) {
                result->start = 0;
            } else {
                result->start = total_size - range->end;
            }
            result->end = total_size - 1;
            break;

        case KRANGE_OPEN:
            // Open range: 9500- (from 9500 to end)
            if (range->start >= total_size) {
                result->valid = false;
                return -1;
            }
            result->start = range->start;
            result->end = total_size - 1;
            break;

        default:
            result->valid = false;
            return -1;
    }

    result->length = result->end - result->start + 1;
    result->valid = true;

    return 0;
}

int krange_satisfy_all(const krange_list_t *list, int64_t total_size,
                       krange_result_t *results, int *count) {
    if (!list || !results || !count) return -1;

    *count = 0;

    for (int i = 0; i < list->count && *count < KRANGE_MAX_RANGES; i++) {
        krange_result_t result;
        if (krange_satisfy(&list->ranges[i], total_size, &result) == 0 &&
            result.valid) {
            results[(*count)++] = result;
        }
    }

    return *count > 0 ? 0 : -1;
}

bool krange_is_satisfiable(const krange_list_t *list, int64_t total_size) {
    if (!list || total_size <= 0) return false;

    for (int i = 0; i < list->count; i++) {
        krange_result_t result;
        if (krange_satisfy(&list->ranges[i], total_size, &result) == 0 &&
            result.valid) {
            return true;
        }
    }

    return false;
}

int krange_content_range(const krange_result_t *result, char *output,
                         size_t size) {
    if (!result || !output || size == 0) return -1;

    if (!result->valid) {
        // 416 Range Not Satisfiable
        int n = snprintf(output, size, "Content-Range: bytes */%lld",
                         (long long)result->total);
        if (n < 0 || (size_t)n >= size) return -1;
        return 0;
    }

    int n = snprintf(output, size, "Content-Range: bytes %lld-%lld/%lld",
                     (long long)result->start,
                     (long long)result->end,
                     (long long)result->total);
    if (n < 0 || (size_t)n >= size) return -1;

    return 0;
}

bool krange_check_if_range_etag(const char *if_range,
                                const char *current_etag) {
    if (!if_range || !current_etag) return false;
    return strcmp(if_range, current_etag) == 0;
}

bool krange_check_if_range_date(const char *if_range, time_t current_mtime) {
    if (!if_range) return false;

    struct tm tm;
    memset(&tm, 0, sizeof(tm));

    // Parse RFC 7231 format: "Sun, 06 Nov 1994 08:49:37 GMT"
    if (strptime(if_range, "%a, %d %b %Y %H:%M:%S", &tm) == NULL) {
        return false;
    }

    time_t req_time = timegm(&tm);
    return req_time >= current_mtime;
}

/* ==================== Multipart Support ==================== */

int krange_generate_boundary(char *boundary) {
    if (!boundary) return -1;

    // Generate simple boundary
    static int counter = 0;
    snprintf(boundary, 64, "KRANGE_BOUNDARY_%d_%ld",
             counter++, (long)time(NULL));

    return 0;
}

int krange_multipart_header(const krange_result_t *result,
                            const char *content_type,
                            const char *boundary,
                            char *output, size_t size) {
    if (!result || !content_type || !boundary || !output || size == 0) {
        return -1;
    }

    int n = snprintf(output, size,
                     "\r\n--%s\r\n"
                     "Content-Type: %s\r\n"
                     "Content-Range: bytes %lld-%lld/%lld\r\n"
                     "\r\n",
                     boundary,
                     content_type,
                     (long long)result->start,
                     (long long)result->end,
                     (long long)result->total);

    if (n < 0 || (size_t)n >= size) return -1;

    return 0;
}

int krange_multipart_trailer(const char *boundary, char *output, size_t size) {
    if (!boundary || !output || size == 0) return -1;

    int n = snprintf(output, size, "\r\n--%s--\r\n", boundary);
    if (n < 0 || (size_t)n >= size) return -1;

    return 0;
}

/* ==================== Utilities ==================== */

krange_t krange_normalize(const krange_t *range, int64_t total_size) {
    krange_t normalized = *range;

    switch (range->type) {
        case KRANGE_SUFFIX:
            // Convert "-500" to absolute offsets
            normalized.type = KRANGE_NORMAL;
            if (range->end > total_size) {
                normalized.start = 0;
            } else {
                normalized.start = total_size - range->end;
            }
            normalized.end = total_size - 1;
            break;

        case KRANGE_OPEN:
            // Convert "9500-" to absolute offsets
            normalized.type = KRANGE_NORMAL;
            normalized.end = total_size - 1;
            break;

        case KRANGE_NORMAL:
            // Clamp to file size
            if (normalized.end >= total_size) {
                normalized.end = total_size - 1;
            }
            break;

        default:
            break;
    }

    return normalized;
}

bool krange_overlaps(const krange_result_t *r1, const krange_result_t *r2) {
    if (!r1 || !r2 || !r1->valid || !r2->valid) return false;

    return (r1->start <= r2->end) && (r2->start <= r1->end);
}

int krange_merge(krange_result_t *results, int *count) {
    if (!results || !count || *count <= 0) return -1;

    // Simple bubble sort + merge
    for (int i = 0; i < *count - 1; i++) {
        for (int j = i + 1; j < *count; j++) {
            if (krange_overlaps(&results[i], &results[j])) {
                // Merge j into i
                if (results[j].start < results[i].start) {
                    results[i].start = results[j].start;
                }
                if (results[j].end > results[i].end) {
                    results[i].end = results[j].end;
                }
                results[i].length = results[i].end - results[i].start + 1;

                // Remove j
                for (int k = j; k < *count - 1; k++) {
                    results[k] = results[k + 1];
                }
                (*count)--;
                j--;
            }
        }
    }

    return 0;
}

int64_t krange_total_bytes(const krange_result_t *results, int count) {
    if (!results || count <= 0) return 0;

    int64_t total = 0;
    for (int i = 0; i < count; i++) {
        if (results[i].valid) {
            total += results[i].length;
        }
    }

    return total;
}

