#include "kfinal.h"
#include <stdio.h>
#include <string.h>
static kfinal_handler_t global_handler = NULL;
static const char* error_messages[] = {
    "OK", "Bad Request", "Not Found", "Server Error",
    "Unauthorized", "Forbidden", "Conflict", "Gone"
};
void kfinal_set_handler(kfinal_handler_t handler) {
    global_handler = handler;
}
void kfinal_handle_error(int code, const char *msg) {
    if (global_handler) {
        global_handler(code, msg);
    } else {
        fprintf(stderr, "[%d] %s\n", code, msg ? msg : "Unknown error");
    }
}
const char* kfinal_error_message(int code) {
    if (code >= 0 && code < 8) return error_messages[code];
    return "Unknown";
}
int kfinal_error_code(const char *msg) {
    if (!msg) return -1;
    for (int i = 0; i < 8; i++) {
        if (strcmp(error_messages[i], msg) == 0) return i;
    }
    return -1;
}

