/*
 * Kim Commander (kcommander.h)
 *
 * CLI 인자 파싱 라이브러리
 * - 명령어 정의 및 해석
 * - 옵션 및 플래그 관리
 * - 서브커맨드 지원
 */

#ifndef KCOMMANDER_H
#define KCOMMANDER_H

#include <stdbool.h>

/* ============================================
   명령어 구조체
   ============================================ */

typedef struct {
    char name[256];
    char description[512];
    char short_flag;  // -f 형태
    char long_flag[64];  // --flag 형태
    bool is_flag;  // true면 값 없음 (boolean)
    bool required;
    char default_value[256];
} kcommander_option_t;

typedef struct {
    char name[256];
    char description[512];
    kcommander_option_t *options;
    int option_count;
    int option_capacity;
} kcommander_command_t;

typedef struct {
    kcommander_command_t *commands;
    int command_count;
    int command_capacity;

    char *argv[512];
    int argc;

    char parsed_command[256];
    char parsed_args[512][256];
    int parsed_arg_count;
} kcommander_t;

/* ============================================
   초기화 및 정리
   ============================================ */

/**
 * Commander 생성
 */
kcommander_t* kcommander_new(void);

/**
 * Commander 정리
 */
void kcommander_free(kcommander_t *cmd);

/**
 * 명령어 추가
 */
bool kcommander_add_command(kcommander_t *cmd, const char *name, const char *desc);

/**
 * 옵션 추가
 */
bool kcommander_add_option(kcommander_t *cmd, const char *command,
                          const char *name, char short_flag, const char *long_flag,
                          bool is_flag, bool required, const char *default_value);

/* ============================================
   파싱
   ============================================ */

/**
 * 명령줄 인자 파싱
 */
bool kcommander_parse(kcommander_t *cmd, int argc, char **argv);

/**
 * 파싱된 명령어 조회
 */
const char* kcommander_get_command(kcommander_t *cmd);

/**
 * 옵션 값 조회
 */
const char* kcommander_get_option(kcommander_t *cmd, const char *option_name);

/**
 * 플래그 조회 (boolean)
 */
bool kcommander_has_flag(kcommander_t *cmd, const char *flag_name);

/**
 * 위치 인자 조회 (--다음의 값들)
 */
const char* kcommander_get_arg(kcommander_t *cmd, int index);

/**
 * 위치 인자 개수
 */
int kcommander_arg_count(kcommander_t *cmd);

/* ============================================
   헬퍼
   ============================================ */

/**
 * 도움말 출력
 */
void kcommander_print_help(kcommander_t *cmd);

/**
 * 버전 출력
 */
void kcommander_print_version(const char *version);

#endif // KCOMMANDER_H

