/*
 * Kim Commander (kcommander.c)
 *
 * CLI 인자 파싱 구현
 */

#define _GNU_SOURCE
#include "kcommander.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ============================================
   초기화 및 정리
   ============================================ */

kcommander_t* kcommander_new(void) {
    kcommander_t *cmd = (kcommander_t *)malloc(sizeof(kcommander_t));
    if (!cmd) return NULL;

    memset(cmd, 0, sizeof(kcommander_t));
    cmd->command_capacity = 10;
    cmd->commands = (kcommander_command_t *)malloc(cmd->command_capacity * sizeof(kcommander_command_t));

    return cmd;
}

void kcommander_free(kcommander_t *cmd) {
    if (!cmd) return;

    for (int i = 0; i < cmd->command_count; i++) {
        if (cmd->commands[i].options) {
            free(cmd->commands[i].options);
        }
    }

    if (cmd->commands) free(cmd->commands);
    free(cmd);
}

bool kcommander_add_command(kcommander_t *cmd, const char *name, const char *desc) {
    if (!cmd || !name) return false;

    if (cmd->command_count >= cmd->command_capacity) {
        cmd->command_capacity *= 2;
        cmd->commands = (kcommander_command_t *)realloc(cmd->commands,
                        cmd->command_capacity * sizeof(kcommander_command_t));
    }

    kcommander_command_t *new_cmd = &cmd->commands[cmd->command_count];
    strncpy(new_cmd->name, name, sizeof(new_cmd->name) - 1);
    if (desc) strncpy(new_cmd->description, desc, sizeof(new_cmd->description) - 1);

    new_cmd->option_capacity = 5;
    new_cmd->options = (kcommander_option_t *)malloc(new_cmd->option_capacity * sizeof(kcommander_option_t));
    new_cmd->option_count = 0;

    cmd->command_count++;
    return true;
}

bool kcommander_add_option(kcommander_t *cmd, const char *command,
                          const char *name, char short_flag, const char *long_flag,
                          bool is_flag, bool required, const char *default_value) {
    if (!cmd || !command || !name) return false;

    // 명령어 찾기
    kcommander_command_t *target_cmd = NULL;
    for (int i = 0; i < cmd->command_count; i++) {
        if (strcmp(cmd->commands[i].name, command) == 0) {
            target_cmd = &cmd->commands[i];
            break;
        }
    }

    if (!target_cmd) return false;

    if (target_cmd->option_count >= target_cmd->option_capacity) {
        target_cmd->option_capacity *= 2;
        target_cmd->options = (kcommander_option_t *)realloc(target_cmd->options,
                              target_cmd->option_capacity * sizeof(kcommander_option_t));
    }

    kcommander_option_t *opt = &target_cmd->options[target_cmd->option_count];
    strncpy(opt->name, name, sizeof(opt->name) - 1);
    opt->short_flag = short_flag;
    if (long_flag) strncpy(opt->long_flag, long_flag, sizeof(opt->long_flag) - 1);
    opt->is_flag = is_flag;
    opt->required = required;
    if (default_value) strncpy(opt->default_value, default_value, sizeof(opt->default_value) - 1);

    target_cmd->option_count++;
    return true;
}

/* ============================================
   파싱
   ============================================ */

bool kcommander_parse(kcommander_t *cmd, int argc, char **argv) {
    if (!cmd || argc < 1) return false;

    cmd->argc = argc;
    for (int i = 0; i < argc && i < 512; i++) {
        cmd->argv[i] = argv[i];
    }

    // 첫 번째 인자가 명령어인지 확인
    if (argc > 1) {
        for (int i = 0; i < cmd->command_count; i++) {
            if (strcmp(cmd->commands[i].name, argv[1]) == 0) {
                strncpy(cmd->parsed_command, argv[1], sizeof(cmd->parsed_command) - 1);
                break;
            }
        }
    }

    // 나머지 인자 파싱
    int arg_start = 1;
    if (cmd->parsed_command[0] != '\0') {
        arg_start = 2;
    }

    for (int i = arg_start; i < argc; i++) {
        if (argv[i][0] != '-') {
            // 위치 인자
            if (cmd->parsed_arg_count < 512) {
                strncpy(cmd->parsed_args[cmd->parsed_arg_count], argv[i],
                       sizeof(cmd->parsed_args[0]) - 1);
                cmd->parsed_arg_count++;
            }
        }
    }

    return true;
}

const char* kcommander_get_command(kcommander_t *cmd) {
    if (!cmd || cmd->parsed_command[0] == '\0') return NULL;
    return cmd->parsed_command;
}

const char* kcommander_get_option(kcommander_t *cmd, const char *option_name) {
    if (!cmd || !option_name) return NULL;

    // argv에서 -o value 또는 --option value 형태 검색
    for (int i = 1; i < cmd->argc - 1; i++) {
        const char *arg = cmd->argv[i];

        // 짧은 형태 (-o value)
        if (arg[0] == '-' && arg[1] != '-' && arg[2] == '\0') {
            char opt_char = arg[1];
            // 옵션 정의에서 해당 문자 찾기
            if (cmd->parsed_command[0] != '\0') {
                for (int j = 0; j < cmd->command_count; j++) {
                    if (strcmp(cmd->commands[j].name, cmd->parsed_command) == 0) {
                        for (int k = 0; k < cmd->commands[j].option_count; k++) {
                            kcommander_option_t *opt = &cmd->commands[j].options[k];
                            if (opt->short_flag == opt_char &&
                                strcmp(opt->name, option_name) == 0) {
                                return cmd->argv[i + 1];
                            }
                        }
                    }
                }
            }
        }

        // 긴 형태 (--option value)
        if (arg[0] == '-' && arg[1] == '-') {
            if (strcmp(arg + 2, option_name) == 0 && i + 1 < cmd->argc) {
                return cmd->argv[i + 1];
            }
        }
    }

    return NULL;
}

bool kcommander_has_flag(kcommander_t *cmd, const char *flag_name) {
