#ifndef KEXPRESS_H
#define KEXPRESS_H

#include <stdint.h>
#include <stdlib.h>

/* 요청/응답 타입 */
typedef struct kexpress_app kexpress_app_t;
typedef struct kexpress_req kexpress_req_t;
typedef struct kexpress_res kexpress_res_t;

/* 핸들러 함수 타입 */
typedef void (*kexpress_handler_t)(kexpress_req_t *req, kexpress_res_t *res);

/* 요청 객체 */
struct kexpress_req {
    char method[16];           /* GET, POST, etc */
    char path[256];            /* /users, /hello, etc */
    char query[512];           /* ?name=value */
    char body[4096];           /* POST body */
    int body_len;
    char headers[2048];        /* Raw headers */
};

/* 응답 객체 */
struct kexpress_res {
    int status;                /* HTTP status code */
    char headers[1024];        /* Response headers */
    char body[8192];           /* Response body */
    int body_len;
};

/* Express 앱 */
struct kexpress_app {
    int port;
    int listen_fd;
    kexpress_handler_t handlers[32];
    char routes[32][256];
    int route_count;
};

/* API */
kexpress_app_t* kexpress_create(int port);
void kexpress_free(kexpress_app_t *app);

/* 라우팅 */
void kexpress_get(kexpress_app_t *app, const char *path, kexpress_handler_t handler);
void kexpress_post(kexpress_app_t *app, const char *path, kexpress_handler_t handler);

/* 서버 시작 */
int kexpress_listen(kexpress_app_t *app);

/* 응답 헬퍼 */
void kexpress_send(kexpress_res_t *res, int status, const char *body);
void kexpress_json(kexpress_res_t *res, int status, const char *json);

#endif /* KEXPRESS_H */

