#include "kexpress.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

/* 앱 생성 */
kexpress_app_t* kexpress_create(int port) {
    kexpress_app_t *app = malloc(sizeof(kexpress_app_t));
    app->port = port;
    app->listen_fd = -1;
    app->route_count = 0;
    return app;
}

/* 앱 해제 */
void kexpress_free(kexpress_app_t *app) {
    if (app->listen_fd >= 0) {
        close(app->listen_fd);
    }
    free(app);
}

/* GET 라우트 등록 */
void kexpress_get(kexpress_app_t *app, const char *path, kexpress_handler_t handler) {
    if (app->route_count >= 32) return;

    snprintf(app->routes[app->route_count], 256, "GET %s", path);
    app->handlers[app->route_count] = handler;
    app->route_count++;
}

/* POST 라우트 등록 */
void kexpress_post(kexpress_app_t *app, const char *path, kexpress_handler_t handler) {
    if (app->route_count >= 32) return;

    snprintf(app->routes[app->route_count], 256, "POST %s", path);
    app->handlers[app->route_count] = handler;
    app->route_count++;
}

/* HTTP 요청 파싱 */
static void kexpress_parse_request(const char *raw, kexpress_req_t *req) {
    memset(req, 0, sizeof(kexpress_req_t));

    char buffer[8192];
    strncpy(buffer, raw, 8191);

    /* 첫 번째 라인: METHOD /path HTTP/1.1 */
    char *line = strtok(buffer, "\r\n");
    if (line) {
        sscanf(line, "%s %s", req->method, req->path);
    }

    /* 헤더 */
    while ((line = strtok(NULL, "\r\n")) != NULL && line[0] != '\0') {
        strncat(req->headers, line, sizeof(req->headers) - 1);
        strncat(req->headers, "\n", sizeof(req->headers) - 1);
    }

    /* 바디 (POST일 때) */
    line = strtok(NULL, "\r\n");
    if (line && strcmp(req->method, "POST") == 0) {
        strncpy(req->body, line, sizeof(req->body) - 1);
        req->body_len = strlen(req->body);
    }
}

/* 라우트 매칭 및 핸들러 실행 */
static int kexpress_route_match(kexpress_app_t *app, kexpress_req_t *req, kexpress_res_t *res) {
    for (int i = 0; i < app->route_count; i++) {
        char method[16], path[256];
        sscanf(app->routes[i], "%s %s", method, path);

        if (strcmp(method, req->method) == 0 && strcmp(path, req->path) == 0) {
            app->handlers[i](req, res);
            return 1;
        }
    }
    return 0;
}

/* 응답 전송 */
static void kexpress_send_response(int client_fd, kexpress_res_t *res) {
    char http_response[16384];

    snprintf(http_response, sizeof(http_response),
        "HTTP/1.1 %d OK\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "%s\r\n"
        "%s",
        res->status,
        res->body_len,
        res->headers[0] ? res->headers : "",
        res->body);

    send(client_fd, http_response, strlen(http_response), 0);
}

/* 응답 헬퍼 */
void kexpress_send(kexpress_res_t *res, int status, const char *body) {
    res->status = status;
    strncpy(res->body, body, sizeof(res->body) - 1);
    res->body_len = strlen(res->body);
}

void kexpress_json(kexpress_res_t *res, int status, const char *json) {
    res->status = status;
    strncpy(res->body, json, sizeof(res->body) - 1);
    res->body_len = strlen(res->body);
    strcpy(res->headers, "Content-Type: application/json\r\n");
}

/* 서버 시작 */
int kexpress_listen(kexpress_app_t *app) {
    /* TCP 소켓 생성 */
    app->listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (app->listen_fd < 0) {
        perror("socket");
        return -1;
    }

    /* SO_REUSEADDR */
