    int max_age;           // Max age in seconds (-1 = session)
    char domain[256];      // Domain
    char path[256];        // Path
    bool secure;           // Secure flag (HTTPS only)
    bool http_only;        // HttpOnly flag
    char same_site[16];    // SameSite (Strict, Lax, None)
} kcookie_options_t;

/**
 * Zero-copy cookie entry (v1.1.0)
 * Points to original header string (no memory copy)
 */
typedef struct {
    const char *name_ptr;   // Pointer to name in original header
    size_t name_len;        // Name length
    const char *value_ptr;  // Pointer to value in original header
    size_t value_len;       // Value length
