/**
 * Kim-Cookie-Parser (kcookie.c)
 * Implementation of cookie parser library in Pure C
 *
 * @author Kim AI Empire
 * @version 1.1.0
 * @date 2026-01-19
 */

#include "kcookie.h"
#include "kcookie_crypto.h"
#include <ctype.h>

/* ==================== Helper Functions ==================== */

static void trim_whitespace(char *str) {
    if (!str) return;

    char *start = str;
    while (*start && isspace(*start)) start++;

    char *end = start + strlen(start) - 1;
    while (end > start && isspace(*end)) end--;
    *(end + 1) = '\0';

    if (start != str) {
        memmove(str, start, strlen(start) + 1);
    }
}

static int hex_to_int(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static char int_to_hex(int n) {
    if (n < 10) return '0' + n;
    return 'a' + (n - 10);
}

/* ==================== Core API ==================== */

int kcookie_parse(const char *cookie_header, kcookie_jar_t *jar) {
    if (!cookie_header || !jar) return -1;

    memset(jar, 0, sizeof(kcookie_jar_t));

    char buffer[8192];
    strncpy(buffer, cookie_header, sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';

    char *token = strtok(buffer, ";");
    while (token && jar->count < KCOOKIE_MAX_COOKIES) {
        trim_whitespace(token);

        char *equals = strchr(token, '=');
        if (!equals) {
            token = strtok(NULL, ";");
            continue;
        }

        *equals = '\0';
        char *name = token;
        char *value = equals + 1;

        trim_whitespace(name);
        trim_whitespace(value);

        kcookie_entry_t *entry = &jar->cookies[jar->count];
        strncpy(entry->name, name, sizeof(entry->name) - 1);
        entry->name[sizeof(entry->name) - 1] = '\0';

        // URL decode value
        kcookie_url_decode(value, entry->value, sizeof(entry->value));

        jar->count++;
        token = strtok(NULL, ";");
    }

    return 0;
}

const char* kcookie_get(const kcookie_jar_t *jar, const char *name) {
    if (!jar || !name) return NULL;

    for (int i = 0; i < jar->count; i++) {
        if (strcmp(jar->cookies[i].name, name) == 0) {
            return jar->cookies[i].value;
        }
    }

    return NULL;
}

bool kcookie_has(const kcookie_jar_t *jar, const char *name) {
    return kcookie_get(jar, name) != NULL;
}

int kcookie_count(const kcookie_jar_t *jar) {
    return jar ? jar->count : 0;
}

/* ==================== Signed Cookies (v1.1.0 Pluggable) ==================== */

int kcookie_sign(const char *value, const char *secret,
                 char *output, size_t size) {
    // Use current crypto provider
    kcookie_crypto_provider_t *provider = kcookie_get_crypto_provider();
    return provider->sign(value, secret, output, size);
}

int kcookie_unsign(const char *signed_value, const char *secret,
                   char *output, size_t size) {
    // Auto-detect algorithm and verify
    return kcookie_crypto_auto_verify(signed_value, secret, output, size);
}

int kcookie_get_signed(const kcookie_jar_t *jar, const char *name,
                       const char *secret, char *output, size_t size) {
    if (!jar || !name || !secret || !output || size == 0) return -1;

    const char *signed_value = kcookie_get(jar, name);
    if (!signed_value) return -1;

    return kcookie_unsign(signed_value, secret, output, size);
}

/* ==================== Set-Cookie Generation ==================== */

void kcookie_options_init(kcookie_options_t *options) {
    if (!options) return;

    memset(options, 0, sizeof(kcookie_options_t));
    options->max_age = -1;  // Session cookie
    strcpy(options->path, "/");
    options->secure = false;
    options->http_only = false;
    strcpy(options->same_site, "");
}

int kcookie_set_cookie(const char *name, const char *value,
                       const kcookie_options_t *options,
                       char *output, size_t size) {
    if (!name || !value || !output || size == 0) return -1;

    char encoded_value[KCOOKIE_MAX_VALUE_SIZE];
    kcookie_url_encode(value, encoded_value, sizeof(encoded_value));

