/**
 * Kim-Cookie-Parser Crypto Core
 * Global provider management and auto-detection
 *
 * @author Kim AI Empire
 * @version 1.1.0
 * @date 2026-01-19
 */

#include "kcookie_crypto.h"
#include <string.h>
#include <stdio.h>

/* ==================== Global Provider ==================== */

static kcookie_crypto_provider_t *global_provider = NULL;

void kcookie_set_crypto_provider(kcookie_crypto_provider_t *provider) {
    global_provider = provider;
}

kcookie_crypto_provider_t* kcookie_get_crypto_provider(void) {
    // Default to FNV-1a if not set
    if (!global_provider) {
        global_provider = kcookie_crypto_fnv1a();
    }
    return global_provider;
}

/* ==================== Auto-detection ==================== */

int kcookie_crypto_detect_algorithm(const char *signed_value) {
    if (!signed_value) return -1;

    // Check format: "s:value.signature"
    if (strncmp(signed_value, "s:", 2) != 0) return -1;

    const char *rest = signed_value + 2;
    const char *dot = strrchr(rest, '.');
    if (!dot) return -1;

    // Get signature length
    const char *signature = dot + 1;
    size_t sig_len = strlen(signature);

    // Detect algorithm by signature length
    if (sig_len == 16) {
        return KCOOKIE_HASH_FNV1A;
    } else if (sig_len == 64) {
        return KCOOKIE_HASH_HMAC_SHA256;
    }

    return -1;  // Unknown
}

int kcookie_crypto_auto_verify(const char *signed_value, const char *secret,
                                char *output, size_t size) {
    if (!signed_value || !secret || !output || size == 0) return -1;

    // Detect algorithm
    int algo = kcookie_crypto_detect_algorithm(signed_value);
    if (algo < 0) return -1;

    // Get appropriate provider
    kcookie_crypto_provider_t *provider = NULL;

    switch (algo) {
        case KCOOKIE_HASH_FNV1A:
            provider = kcookie_crypto_fnv1a();
            break;
        case KCOOKIE_HASH_HMAC_SHA256:
            provider = kcookie_crypto_hmac_sha256();
            break;
        default:
            return -1;
    }

    // Verify with detected provider
    return provider->verify(signed_value, secret, output, size);
}

