     1→// FreeLang v6: Regex builtins (Phase 2)
     2→// Pure JS RegExp-based
     3→
     4→import { Value } from "../compiler";
     5→import { VM } from "../vm";
     6→import { registerBuiltin } from "./builtins";
     7→
     8→function num(n: number): Value { return { tag: "num", val: n }; }
     9→function str(s: string): Value { return { tag: "str", val: s }; }
    10→function bool(b: boolean): Value { return { tag: "bool", val: b }; }
    11→function arr(items: Value[]): Value { return { tag: "array", val: items }; }
    12→function numVal(v: Value): number { return v.tag === "num" ? v.val : 0; }
    13→function strVal(v: Value): string { return v.tag === "str" ? v.val : ""; }
    14→
    15→function makeRe(pattern: string, flags?: string): RegExp | null {
    16→  try { return new RegExp(pattern, flags); }
    17→  catch { return null; }
    18→}
    19→
    20→registerBuiltin("regex_test", (args) => {
    21→  const re = makeRe(strVal(args[0]));
    22→  return re ? bool(re.test(strVal(args[1]))) : bool(false);
    23→});
    24→
    25→registerBuiltin("regex_match", (args) => {
    26→  const re = makeRe(strVal(args[0]));
    27→  if (!re) return { tag: "null" };
    28→  const m = strVal(args[1]).match(re);
    29→  return m ? str(m[0]) : { tag: "null" };
    30→});
    31→
    32→registerBuiltin("regex_find_all", (args) => {
    33→  const re = makeRe(strVal(args[0]), "g");
    34→  if (!re) return arr([]);
    35→  const matches = strVal(args[1]).match(re);
    36→  return arr(matches ? matches.map(s => str(s)) : []);
    37→});
    38→
    39→registerBuiltin("regex_replace", (args) => {
    40→  const re = makeRe(strVal(args[0]));
    41→  if (!re) return args[1];
    42→  return str(strVal(args[1]).replace(re, strVal(args[2])));
    43→});
    44→
    45→registerBuiltin("regex_replace_all", (args) => {
    46→  const re = makeRe(strVal(args[0]), "g");
    47→  if (!re) return args[1];
    48→  return str(strVal(args[1]).replace(re, strVal(args[2])));
    49→});
    50→
    51→registerBuiltin("regex_split", (args) => {
    52→  const re = makeRe(strVal(args[0]));
    53→  if (!re) return arr([args[1]]);
    54→  return arr(strVal(args[1]).split(re).map(s => str(s)));
    55→});
    56→
    57→registerBuiltin("regex_capture", (args) => {
    58→  const re = makeRe(strVal(args[0]));
    59→  if (!re) return arr([]);
    60→  const m = strVal(args[1]).match(re);
    61→  return m ? arr(m.slice(1).map(s => s !== undefined ? str(s) : { tag: "null" } as Value)) : arr([]);
    62→});
    63→
    64→registerBuiltin("regex_capture_all", (args) => {
    65→  const re = makeRe(strVal(args[0]), "g");
    66→  if (!re) return arr([]);
    67→  const results: Value[] = [];
    68→  const input = strVal(args[1]);
    69→  const reLocal = makeRe(strVal(args[0]));
    70→  if (!reLocal) return arr([]);
    71→  let m: RegExpExecArray | null;
    72→  const reExec = new RegExp(strVal(args[0]), "g");
    73→  while ((m = reExec.exec(input)) !== null) {
    74→    results.push(arr(m.slice(1).map(s => s !== undefined ? str(s) : { tag: "null" } as Value)));
    75→    if (!reExec.lastIndex) break;
    76→  }
    77→  return arr(results);
    78→});
    79→
    80→registerBuiltin("regex_count", (args) => {
    81→  const re = makeRe(strVal(args[0]), "g");
    82→  if (!re) return num(0);
    83→  const matches = strVal(args[1]).match(re);
    84→  return num(matches ? matches.length : 0);
    85→});
    86→
    87→registerBuiltin("regex_is_valid", (args) => {
    88→  return bool(makeRe(strVal(args[0])) !== null);
    89→});
    90→
    91→registerBuiltin("regex_escape", (args) => {
    92→  return str(strVal(args[0]).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    93→});
    94→
    95→registerBuiltin("regex_first_index", (args) => {
    96→  const re = makeRe(strVal(args[0]));
    97→  if (!re) return num(-1);
    98→  const m = strVal(args[1]).search(re);
    99→  return num(m);
   100→});
   101→
   102→registerBuiltin("regex_word_count", (args) => {
   103→  const words = strVal(args[0]).match(/\b\w+\b/g);
   104→  return num(words ? words.length : 0);
   105→});
