      timeout,
      maxBuffer: 10 * 1024 * 1024,
      stdio: ['pipe', 'pipe', 'pipe']
    });

    if (result.error) return { success: false, error: result.error.message };
    return {
      success: result.status === 0,
      stdout: result.stdout?.toString(),
      error: result.stderr?.toString()
    };
