import { execFile } from 'child_process';
import { promisify } from 'util';

const execFileAsync = promisify(execFile);

export interface KPMSearchResult {
  name: string;
  version: string;
  description?: string;
  downloads?: number;
}

export interface InstallOptions {
  version?: string;
  force?: boolean;
  offline?: boolean;
