   162→        const iterName = `__iter_${currentPos()}`;
   163→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: iterName }));
   164→        const loop: LoopInfo = { startAddr: currentPos(), breakPatches: [] };
   165→        loopStack.push(loop);
   166→        // Check done
   167→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: iterName }));
   168→        emit(Op.IterDone);
   169→        const exit = currentPos(); emitArg(Op.JumpIfTrue, 0);
   170→        // Get next value, store as loop variable
   171→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: iterName }));
   172→        emit(Op.IterNext);
   173→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   174→        compileStmts(s.body);
   175→        emitArg(Op.Jump, loop.startAddr);
   176→        patchJump(exit);
   177→        for (const bp of loop.breakPatches) patchJump(bp);
   178→        loopStack.pop();
   179→        break;
   180→      }
   181→      case "block": {
   182→        scope().depth++;
   183→        compileStmts(s.body);
   184→        const localsToRemove = scope().locals.filter(l => l.depth === scope().depth).length;
   185→        for (let i = 0; i < localsToRemove; i++) { emit(Op.Pop); scope().locals.pop(); }
   186→        scope().depth--;
   187→        break;
   188→      }
   189→      case "break": {
   190→        if (loopStack.length === 0) throw new Error("break outside loop");
   191→        const bp = currentPos(); emitArg(Op.Jump, 0);
   192→        loopStack[loopStack.length - 1].breakPatches.push(bp);
   193→        break;
   194→      }
   195→      case "continue": {
   196→        if (loopStack.length === 0) throw new Error("continue outside loop");
   197→        emitArg(Op.Jump, loopStack[loopStack.length - 1].startAddr);
   198→        break;
   199→      }
   200→      case "print": {
   201→        compileExpr(s.expr);
   202→        emit(s.newline ? Op.Println : Op.Print);
   203→        break;
   204→      }
   205→      case "try": {
   206→        const tryBegin = currentPos(); emitArg(Op.TryBegin, 0); // catch addr
   207→        compileStmts(s.body);
   208→        emit(Op.TryEnd);
   209→        const jumpFinally = currentPos(); emitArg(Op.Jump, 0);
   210→        // Catch
   211→        patchJump(tryBegin);
   212→        if (s.catchVar) {
   213→          scope().depth++;
   214→          declareLocal(s.catchVar);
   215→          compileStmts(s.catchBody);
   216→          const localsToRemove = scope().locals.filter(l => l.depth === scope().depth).length;
   217→          for (let i = 0; i < localsToRemove; i++) { emit(Op.Pop); scope().locals.pop(); }
   218→          scope().depth--;
   219→        } else {
   220→          emit(Op.Pop); // discard error
   221→          compileStmts(s.catchBody);
   222→        }
   223→        // Finally
   224→        patchJump(jumpFinally);
   225→        compileStmts(s.finallyBody);
   226→        break;
   227→      }
   228→      case "throw": {
   229→        compileExpr(s.expr);
   230→        emit(Op.Throw);
   231→        break;
   232→      }
   233→      case "struct": {
   234→        // Store struct definition as global
   235→        globals.add(s.name);
   236→        emitArg(Op.Const, addConst({ tag: "object", val: new Map(s.fields.map(f => [f, { tag: "null" } as Value])) }));
   237→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: s.name }));
   238→        break;
   239→      }
   240→      case "import": break; // handled by module loader
   241→      case "export": compileStmt(s.stmt); break; // compile inner stmt
   242→      case "multi": compileStmts(s.stmts); break;
   243→      case "match": {
   244→        // Compile subject once, store as temp global
   245→        compileExpr(s.subject);
   246→        const tempName = `__match_${currentPos()}`;
   247→        emitArg(Op.StoreGlobal, addConst({ tag: "str", val: tempName }));
   248→        const endPatches: number[] = [];
   249→        for (const arm of s.arms) {
   250→          if (arm.pattern !== null) {
   251→            emitArg(Op.LoadGlobal, addConst({ tag: "str", val: tempName }));
   252→            compileExpr(arm.pattern);
   253→            emit(Op.Eq);
   254→            const skip = currentPos(); emitArg(Op.JumpIfFalse, 0);
   255→            compileStmts(arm.body);
   256→            endPatches.push(currentPos()); emitArg(Op.Jump, 0);
   257→            patchJump(skip);
   258→          } else {
   259→            // Default arm (_)
   260→            compileStmts(arm.body);
   261→          }
   262→        }
   263→        const end = currentPos();
   264→        for (const p of endPatches) patchJump(p);
   265→        break;
   266→      }
   267→    }
   268→  }
   269→
   270→  function compileFnBody(name: string, params: string[], body: Stmt[]) {
   271→    const jumpOver = currentPos(); emitArg(Op.Jump, 0);
   272→    const fnAddr = currentPos();
   273→    scopes.push({ locals: [], depth: 1, upvalues: [] });
   274→    for (const p of params) declareLocal(p);
   275→    compileStmts(body);
   276→    emitArg(Op.Const, addConst({ tag: "null" }));
   277→    emit(Op.Return);
   278→    const fnScope = scopes.pop()!;
   279→    patchJump(jumpOver);
   280→
   281→    if (fnScope.upvalues.length > 0) {
   282→      for (const uv of fnScope.upvalues) {
   283→        if (uv.isLocal) emitArg(Op.Load, uv.index);
   284→        else emitArg(Op.LoadFree, uv.index);
   285→      }
   286→      emitArg(Op.Const, addConst({ tag: "fn", name, arity: params.length, addr: fnAddr, freeVars: [] }));
   287→      emitArg(Op.NewClosure, fnScope.upvalues.length);
   288→    } else {
   289→      emitArg(Op.Const, addConst({ tag: "fn", name, arity: params.length, addr: fnAddr, freeVars: [] }));
   290→    }
   291→  }
   292→
   293→  function compileExpr(e: Expr) {
   294→    switch (e.kind) {
   295→      case "number": emitArg(Op.Const, addConst({ tag: "num", val: e.value })); break;
   296→      case "string": emitArg(Op.Const, addConst({ tag: "str", val: e.value })); break;
   297→      case "bool": emitArg(Op.Const, addConst({ tag: "bool", val: e.value })); break;
   298→      case "null": emitArg(Op.Const, addConst({ tag: "null" })); break;
   299→      case "ident": {
   300→        const local = resolveLocal(e.name);
   301→        if (local !== -1) { emitArg(Op.Load, local); break; }
   302→        const upval = resolveUpvalue(e.name);
   303→        if (upval !== -1) { emitArg(Op.LoadFree, upval); break; }
   304→        emitArg(Op.LoadGlobal, addConst({ tag: "str", val: e.name }));
   305→        break;
   306→      }
   307→      case "binary": {
   308→        compileExpr(e.left);
   309→        compileExpr(e.right);
   310→        const ops: Record<string, Op> = {
   311→          "+": Op.Add, "-": Op.Sub, "*": Op.Mul, "/": Op.Div, "%": Op.Mod,
   312→          "==": Op.Eq, "!=": Op.Neq, "<": Op.Lt, ">": Op.Gt, "<=": Op.Lte, ">=": Op.Gte,
   313→          "&&": Op.And, "||": Op.Or,
   314→        };
   315→        emit(ops[e.op]);
   316→        break;
   317→      }
   318→      case "unary": {
   319→        compileExpr(e.expr);
   320→        if (e.op === "-") emit(Op.Neg);
   321→        else if (e.op === "!" || e.op === "not") emit(Op.Not);
   322→        break;
   323→      }
   324→      case "call": {
   325→        compileExpr(e.callee); // Standard ident resolution: local → upvalue → global
   326→        for (const arg of e.args) compileExpr(arg);
   327→        emitArg(Op.Call, e.args.length);
   328→        break;
   329→      }
   330→      case "assign": {
   331→        compileExpr(e.value);
   332→        if (e.target.kind === "ident") {
   333→          const local = resolveLocal(e.target.name);
   334→          if (local !== -1) { emit(Op.Dup); emitArg(Op.Store, local); }
   335→          else {
   336→            const upval = resolveUpvalue(e.target.name);
   337→            if (upval !== -1) { emit(Op.Dup); emitArg(Op.StoreFree, upval); }
   338→            else { emit(Op.Dup); emitArg(Op.StoreGlobal, addConst({ tag: "str", val: e.target.name })); }
   339→          }
   340→        } else if (e.target.kind === "index") {
   341→          compileExpr(e.target.object);
   342→          compileExpr(e.target.index);
   343→          emit(Op.SetIndex);
   344→        } else if (e.target.kind === "member") {
   345→          compileExpr(e.target.object);
   346→          emitArg(Op.Const, addConst({ tag: "str", val: e.target.property }));
   347→          emit(Op.SetProp);
   348→        }
   349→        break;
   350→      }
   351→      case "array": {
   352→        for (const el of e.elements) compileExpr(el);
   353→        emitArg(Op.NewArray, e.elements.length);
   354→        break;
   355→      }
   356→      case "object": {
   357→        for (const { key, value } of e.entries) {
   358→          emitArg(Op.Const, addConst({ tag: "str", val: key }));
   359→          compileExpr(value);
   360→        }
   361→        emitArg(Op.NewObject, e.entries.length);
   362→        break;
   363→      }
   364→      case "index": {
   365→        compileExpr(e.object);
   366→        compileExpr(e.index);
   367→        emit(Op.Index);
   368→        break;
   369→      }
   370→      case "member": {
   371→        compileExpr(e.object);
   372→        emitArg(Op.GetProp, addConst({ tag: "str", val: e.property }));
   373→        break;
   374→      }
   375→      case "fn": {
   376→        compileFnBody(e.name ?? "<anon>", e.params, e.body);
   377→        break;
   378→      }
   379→      case "ternary": {
   380→        compileExpr(e.cond);
   381→        const jumpFalse = currentPos(); emitArg(Op.JumpIfFalse, 0);
   382→        compileExpr(e.then);
   383→        const jumpEnd = currentPos(); emitArg(Op.Jump, 0);
   384→        patchJump(jumpFalse);
   385→        compileExpr(e.else);
   386→        patchJump(jumpEnd);
   387→        break;
   388→      }
   389→    }
   390→  }
   391→
   392→  compileStmts(program.stmts);
   393→  emit(Op.Halt);
   394→  return chunk;
   395→}
