import * as path from 'path';

function validateFilePath(filePath: string, baseDir: string): string {
  const resolved = path.resolve(baseDir, filePath);
  const normalizedBase = path.resolve(baseDir);

  // 경로가 베이스 디렉토리 내에 있는지 확인
  if (!resolved.startsWith(normalizedBase)) {
    throw new Error("Path traversal attempt detected");
  }

  return resolved;
}

registerBuiltin("file_read_safe", (args) => {
  try {
    const filePath = strVal(args[0]);
    const baseDir = strVal(args[1] || "./data");
    const validated = validateFilePath(filePath, baseDir);
    return str(fs.readFileSync(validated, "utf-8"));
  } catch (e) {
    return { tag: "null" } as Value;
  }
});
```

