// src/vm/data-masking.ts
class DataMasking {
  private sensitivePatterns = [
    { regex: /password/i, mask: '****' },
    { regex: /token|api_key|secret/i, mask: '[REDACTED]' },
    { regex: /credit_card|ssn|pii/i, mask: '[MASKED]' }
  ];

  maskMemoryDump(data: Buffer): Buffer {
    let masked = data.toString('utf8', 0, Math.min(data.length, 1000));

    for (const { regex, mask } of this.sensitivePatterns) {
      masked = masked.replace(regex, mask);
    }

    return Buffer.from(masked);
  }

  maskDebugInfo(info: DebugInfo): DebugInfo {
    return {
      ...info,
      variables: info.variables.map(v => ({
        ...v,
        value: this.sensitivePatterns.some(p => p.regex.test(v.name))
          ? '[MASKED]'
          : v.value
      }))
    };
  }
}
