// src/observability/data-masking.ts
class DataMasker {
  private sensitivePatterns = [
    { pattern: /password/i, mask: '****' },
    { pattern: /api_key|token/i, mask: '[REDACTED]' },
    { pattern: /credit_card|ssn/i, mask: '[MASKED]' }
  ];

  maskObservabilityData(data: ObservabilityData): ObservabilityData {
    return {
      ...data,
      variables: data.variables.map(v => ({
        ...v,
        value: this.maskValue(v.name, v.value)
      }))
    };
  }

  private maskValue(name: string, value: any): any {
    for (const { pattern, mask } of this.sensitivePatterns) {
      if (pattern.test(name)) {
        return mask;
      }
    }
    return value;
  }
}
