// ✅ 안전한 쿼리 파라미터 처리
const DEFAULT_LIMIT = 50;
const MAX_LIMIT = 1000;
const MIN_LIMIT = 1;

function parseLimitParam(limitStr?: string): number {
  try {
    const parsed = parseInt(limitStr || String(DEFAULT_LIMIT), 10);

    // 범위 검증
    return Math.max(MIN_LIMIT, Math.min(parsed, MAX_LIMIT));
  } catch {
    return DEFAULT_LIMIT;
  }
}

// 사용
app.get('/alerts/records', (req, res) => {
  const limit = parseLimitParam(req.query.limit as string);
  const records = this.alertManager.getRecords(limit);
  res.json(records);
});
