    re->max_depth = REGEX_DEPTH_LIMIT;
    re->timeout_ms = REGEX_TIMEOUT_MS;

    // 취약한 패턴 감지
    if (strchr(pattern, '*') && strchr(pattern, '+')) {
        if (strstr(pattern, ".*+") || strstr(pattern, ".+*")) {
            fprintf(stderr, "Warning: Potentially catastrophic regex pattern\\n");
        }
    }
    return re;
}

int count_regex_depth(const char* pattern) {
    int depth = 0;
    int max_depth = 0;
    for (int i = 0; pattern[i]; i++) {
        if (pattern[i] == '(') depth++;
        if (depth > max_depth) max_depth = depth;
        if (pattern[i] == ')') depth--;
    }
    return max_depth;
}

int validate_regex_pattern(const char* pattern) {
    if (strlen(pattern) > 512) return 0;
    if (count_regex_depth(pattern) > REGEX_DEPTH_LIMIT) return 0;
    return 1;
}
