// XSS/CSRF 방어
#include <string.h>
#include <stdlib.h>

typedef struct {
    char* html_safe;
} XSSProtection;

char* html_escape(const char* input) {
    if (!input) return calloc(1, 1);

    size_t len = strlen(input);
    char* escaped = malloc(len * 6 + 1);  // Worst case: all special chars
    int out = 0;

