            case '&': out += sprintf(escaped + out, "&amp;"); break;
            case '\\"': out += sprintf(escaped + out, "&quot;"); break;
            case '\\'': out += sprintf(escaped + out, "&#x27;"); break;
            default: escaped[out++] = input[i];
        }
    }
    escaped[out] = '\\0';
    return escaped;
