// CSRF 토큰 생성/검증
typedef struct {
    char token[128];
    time_t created_at;
    int valid;
} CSRFToken;

CSRFToken* generate_csrf_token() {
    CSRFToken* token = malloc(sizeof(CSRFToken));
    token->created_at = time(NULL);
    token->valid = 1;

    // Generate random 128-char token
    for (int i = 0; i < 128; i++) {
        token->token[i] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
                          [rand() % 62];
    }
    return token;
}

int validate_csrf_token(CSRFToken* token, const char* provided_token) {
    if (!token || !provided_token) return 0;
    if (!token->valid) return 0;

    // Check expiration (e.g., 1 hour)
    if (time(NULL) - token->created_at > 3600) {
        token->valid = 0;
        return 0;
    }

    return strcmp(token->token, provided_token) == 0;
}
