/* ===================== 벤치마킹 유틸리티 ===================== */

typedef struct {
    double start;
    double elapsed;
} benchmark_timer_t;

static inline double get_time_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1000000.0;
}

static void timer_start(benchmark_timer_t *timer) {
    timer->start = get_time_ms();
}

static void timer_stop(benchmark_timer_t *timer) {
    timer->elapsed = get_time_ms() - timer->start;
}

/* ===================== 메모리 할당 벤치마크 ===================== */

typedef struct {
    int iterations;
    int size;
    double time_ms;
} malloc_benchmark_result_t;

malloc_benchmark_result_t benchmark_malloc(int iterations, int size) {
    benchmark_timer_t timer;
    malloc_benchmark_result_t result = {iterations, size, 0};

    timer_start(&timer);

    for (int i = 0; i < iterations; i++) {
        void *ptr = malloc(size);
        memset(ptr, 0xFF, size);
        free(ptr);
    }

    timer_stop(&timer);
    result.time_ms = timer.elapsed;

    return result;
}

