// 캐싱 자동화 (v3에서 AI가 자동으로 메모이제이션 추가)
@auto_cache
fn fibonacci(n: int) -> int {
    // v1/v2: 수동으로 메모이제이션 코드 작성 필요
    // v3: AI가 자동으로 결과 캐싱 추가
    if n <= 1 {
        return n
    }
    return fibonacci(n - 1) + fibonacci(n - 2)
}

// 지연 평가 (Lazy Evaluation) - v3 신기능
@lazy_eval
