// FreeLang v4 - Example 1: Complete Web Server
// Features: HTTP handling, routing, middleware, async operations, full-featured

use http::{Server, Request, Response, Router, Middleware}
use async::{spawn, await}
use concurrency::{channel, mutex, Actor}
use errors::{Result, Error}

// 라우터 타입
type RouteHandler = fn(Request) -> Result<Response, Error>

// 요청 로깅 미들웨어
fn logging_middleware(req: Request) -> Result<Request, Error> {
    print("[LOG] " + req.method + " " + req.path)
    return Ok(req)
}

// 인증 미들웨어
fn auth_middleware(req: Request) -> Result<Request, Error> {
    match req.header("Authorization") {
        Some(token) => {
            if valid_token(token) {
                return Ok(req)
            } else {
                return Err(Error::Unauthorized)
            }
        }
        None() => {
            return Err(Error::Unauthorized)
        }
    }
}

// 토큰 검증 (단순화)
fn valid_token(token: string) -> bool {
    return token == "Bearer valid_token"
}

// GET / - 홈페이지
fn home_handler(req: Request) -> Result<Response, Error> {
    let response: Response = Response::new()
    response = response.status(200)
    response = response.body("<h1>Welcome to FreeLang v4 Web Server</h1>")
    response = response.header("Content-Type", "text/html")
    return Ok(response)
}

// GET /api/users - 사용자 목록
fn users_handler(req: Request) -> Result<Response, Error> {
    let json_body: string = "[{\"id\":1,\"name\":\"Alice\"},{\"id\":2,\"name\":\"Bob\"}]"
    let response: Response = Response::new()
    response = response.status(200)
    response = response.body(json_body)
    response = response.header("Content-Type", "application/json")
    return Ok(response)
}

// GET /api/users/:id - 특정 사용자
fn user_detail_handler(req: Request) -> Result<Response, Error> {
    match req.param("id") {
        Some(user_id) => {
            let json_body: string = "{\"id\":" + user_id + ",\"name\":\"User\",\"email\":\"user@example.com\"}"
            let response: Response = Response::new()
            response = response.status(200)
            response = response.body(json_body)
            response = response.header("Content-Type", "application/json")
            return Ok(response)
        }
        None() => {
            return Err(Error::NotFound)
        }
    }
}

// POST /api/users - 새 사용자 생성
fn create_user_handler(req: Request) -> Result<Response, Error> {
    match parse_json(req.body()) {
        Ok(json) => {
            // 데이터베이스에 저장
            let user_id: string = "3"
            let response: Response = Response::new()
            response = response.status(201)
            response = response.body("{\"id\":" + user_id + ",\"status\":\"created\"}")
            response = response.header("Content-Type", "application/json")
            return Ok(response)
        }
        Err(e) => {
            return Err(Error::BadRequest)
        }
    }
}

// 간단한 JSON 파싱 (v4 신기능)
fn parse_json(json_str: string) -> Result<map<string, string>, Error> {
    if len(json_str) == 0 {
        return Err(Error::BadRequest)
    }
    // 실제 구현은 더 복잡함
    return Ok(map())
}

// 에러 핸들러
fn error_handler(error: Error) -> Response {
    let status: int = 500
    let message: string = "Internal Server Error"

    match error {
        Error::NotFound => {
            status = 404
            message = "Not Found"
        }
        Error::Unauthorized => {
            status = 401
            message = "Unauthorized"
        }
        Error::BadRequest => {
            status = 400
            message = "Bad Request"
        }
        _ => {}
    }

    let response: Response = Response::new()
    response = response.status(status)
    response = response.body("{\"error\":\"" + message + "\"}")
    response = response.header("Content-Type", "application/json")
    return response
}

// 라우터 설정
fn setup_router() -> Router {
    let router: Router = Router::new()

    // 공개 라우트
    router = router.get("/", home_handler)
    router = router.get("/api/users", users_handler)

    // 보호된 라우트 (인증 필요)
    router = router.get("/api/users/:id", user_detail_handler)
        .middleware(auth_middleware)
    router = router.post("/api/users", create_user_handler)
        .middleware(auth_middleware)

    // 모든 라우트에 로깅 적용
    router = router.middleware(logging_middleware)

    return router
}

// 메인 서버 함수 (비동기)
async fn run_server() -> Result<void, Error> {
    let server: Server = Server::new()
    server = server.host("127.0.0.1")
    server = server.port(8000)

    let router: Router = setup_router()

    // 각 요청을 비동기로 처리
    server = server.router(router)

    print("Server running on http://127.0.0.1:8000")
    return server.listen().await
}

// 메인 함수
fn main() -> void {
    print("=== FreeLang v4: Complete Web Server ===")
    print("")
    print("Starting server...")

    // 비동기 서버 실행
    spawn(run_server())

    print("")
    print("Available endpoints:")
    print("GET  /                  - Home page (public)")
    print("GET  /api/users         - List all users (public)")
    print("GET  /api/users/:id     - Get user details (protected)")
    print("POST /api/users         - Create new user (protected)")
    print("")
    print("Features in v4:")
    print("✓ Full HTTP server with routing")
    print("✓ Middleware support (logging, authentication)")
    print("✓ Async/await for non-blocking I/O")
    print("✓ Error handling with custom types")
    print("✓ JSON serialization/deserialization")
    print("✓ Type-safe request/response handling")
}

// FreeLang v4 - Example 2: Concurrency & Actor Model
// Features: Actors, channels, async/await, concurrent operations, supervision

use concurrency::{Actor, Channel, spawn, await, select}
use errors::{Result, Error}

// Actor 메시지 타입 (디자인 패턴)
union WorkerMessage {
    Task(int),
    Cancel,
    Status
}

union WorkerResponse {
    Result(int),
    Cancelled,
    Busy
}

// Worker Actor - 작업 처리
actor Worker {
    id: int,
    busy: bool,
    tasks_completed: int,

    // 메시지 핸들러
    fn handle_message(msg: WorkerMessage) -> WorkerResponse {
        match msg {
            Task(work_id) => {
                self.busy = true
                self.tasks_completed = self.tasks_completed + 1
                // 작업 시뮬레이션
                let result: int = self.process_work(work_id)
                self.busy = false
                return Result(result)
            }
            Cancel => {
                self.busy = false
                return Cancelled
            }
            Status => {
                if self.busy {
                    return Busy
                } else {
                    return Result(self.tasks_completed)
                }
            }
        }
    }

    fn process_work(work_id: int) -> int {
        // 실제 작업
        let result: int = work_id * 2
        return result
    }
}

// 작업 큐 Actor - 작업 분배
actor WorkQueue {
    workers: array<Actor<WorkerMessage, WorkerResponse>>,
    queue: array<int>,
    next_worker: int,

    fn distribute_work() -> Result<void, Error> {
        // 대기 중인 작업을 워커에게 분배
        while len(self.queue) > 0 {
            let work_id: int = self.queue[0]
            self.queue = slice(self.queue, 1, len(self.queue))

            let worker: Actor<WorkerMessage, WorkerResponse> =
                self.workers[self.next_worker]

            let response: WorkerResponse = worker.send(Task(work_id)).await
            self.next_worker = (self.next_worker + 1) % len(self.workers)
        }
        return Ok()
    }

    fn add_work(work_id: int) -> void {
        self.queue = push(self.queue, work_id)
    }
}

// 채널을 이용한 통신
fn example_channels() -> Result<void, Error> {
    // 채널 생성 (발신자, 수신자 분리)
    let (sender, receiver) = channel<string>()

    // 발신 작업
    spawn(fn() -> void {
        sender.send("Hello from async task")
    })

    // 수신 작업
    spawn(fn() -> void {
        match receiver.recv().await {
            Some(msg) => {
                print("Received: " + msg)
            }
            None() => {
                print("Channel closed")
            }
        }
    })

    return Ok()
}

// 타임아웃이 있는 선택 연산 (select)
